namespace Cogitator
{
    static class Program
    {
        [DllImport("user32.dll")] static extern bool SetProcessDPIAware();

        static Mutex single;

        // отпустить единственный экземпляр перед перезапуском (смена языка)
        public static void ReleaseSingle()
        {
            try { single.ReleaseMutex(); } catch { }
            try { single.Dispose(); } catch { }
            try { if (ShowSignal != null) ShowSignal.Dispose(); } catch { }
            ShowSignal = null;
        }
        public static EventWaitHandle ShowSignal;
        public const string ShowSignalName = "Cogitator.Svyazi.Show";
        public const string AckSignalName = "Cogitator.Svyazi.ShowAck";

        [STAThread]
        static void Main(string[] args)
        {
            Store.LoadLang();
            Theme.InitFont(Environment.GetEnvironmentVariable("COG_FONT") ?? Store.FontChoice);
            bool fresh;
            single = new Mutex(true, "Cogitator.Svyazi.SingleInstance", out fresh);
            if (!fresh)
            {
                // когитатор уже работает (например, в трее после автозапуска) — просим его показаться
                // просим работающий когитатор показаться и ждём подтверждения
                bool acked = false;
                try
                {
                    using (var ack = new EventWaitHandle(false, EventResetMode.AutoReset, AckSignalName))
                    using (var ev = EventWaitHandle.OpenExisting(ShowSignalName))
                    {
                        ev.Set();
                        acked = ack.WaitOne(2500);
                    }
                }
                catch { }
                if (acked) return;
                // старый когитатор молчит (зависла старая версия или осталась в трее без ответа) — предложить сменить его
                var me = Process.GetCurrentProcess();
                var others = Process.GetProcessesByName(me.ProcessName).Where(x => x.Id != me.Id).ToList();
                if (others.Count == 0 || MessageBox.Show(Loc.T("Работает другой когитатор (возможно, старая версия в трее), и он не отзывается.\n\nУпокоить его и пробудить этот?"), Loc.T("Когитатор"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
                foreach (var o in others) { try { o.Kill(); o.WaitForExit(3000); } catch { } }
                try { single.Dispose(); } catch { }
                single = new Mutex(true, "Cogitator.Svyazi.SingleInstance", out fresh);
            }
            try { ShowSignal = new EventWaitHandle(false, EventResetMode.AutoReset, ShowSignalName); } catch { }
            bool tray = args.Any(a => a.Equals("--tray", StringComparison.OrdinalIgnoreCase));
            try { if (Environment.OSVersion.Version.Major >= 6) SetProcessDPIAware(); } catch { }
            try { ServicePointManager.SecurityProtocol = (SecurityProtocolType)(3072 | 768 | 192); } catch { }
            ServicePointManager.Expect100Continue = false;
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
            AppDomain.CurrentDomain.UnhandledException += (s, e) => { try { File.AppendAllText(Path.Combine(Store.Dir, "crash.log"), DateTime.Now + "\r\n" + e.ExceptionObject + "\r\n\r\n"); } catch { } };
            bool shown = false;
            Application.ThreadException += (s, e) =>
            {
                if (shown) return;
                shown = true;
                MessageBox.Show(Loc.T("Машинный дух споткнулся, но когитатор продолжает работу:\n\n") + e.Exception.Message, Loc.T("Когитатор"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
                shown = false;
            };
            MainForm form;
            try { form = new MainForm(tray); }
            catch (Exception ex)
            {
                try { File.WriteAllText(Path.Combine(Store.Dir, "crash.log"), DateTime.Now + "\r\n" + ex); } catch { }
                MessageBox.Show(Loc.T("Когитатор не смог пробудиться:\n\n") + ex.Message + "\n\n" + Path.Combine(Store.Dir, "crash.log"), Loc.T("Когитатор"), MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }
            Application.Run(form);
        }
    }

    // ============================== ЛОКАЛИЗАЦИЯ ==============================
    static class Loc
    {
        public static bool En;
        static Dictionary<string, string> ru2en, en2ru;

        static void Init()
        {
            if (ru2en != null) return;
            var a = new Dictionary<string, string>(); var b = new Dictionary<string, string>();
            for (int i = 0; i < Ru.Length; i++)
            {
                if (!a.ContainsKey(Ru[i])) a[Ru[i]] = EnS[i];
                if (!b.ContainsKey(EnS[i])) b[EnS[i]] = Ru[i];
            }
            ru2en = a; en2ru = b;
        }

        // перевод: в английском режиме русское → английское; в русском — наоборот (для записей летописи, сделанных на другом языке)
        public static string T(string s)
        {
            if (s == null) return null;
            Init();
            string r;
            if (En) return ru2en.TryGetValue(s, out r) ? r : s;
            return en2ru.TryGetValue(s, out r) ? r : s;
        }

        // приговор с переменной частью («СВЯЗЬ ВОССТАНОВЛЕНА · ПРОСТОЙ 2 МИН 17 С»)
        static readonly string[][] Units = { new[] { " МИН ", " MIN " }, new[] { " Ч ", " H " }, new[] { " С", " S" } };
        public static string TH(string h)
        {
            string t = T(h);
            if (t != h || h == null) return t;
            const string ruP = "СВЯЗЬ ВОССТАНОВЛЕНА · ПРОСТОЙ ", enP = "CONNECTION RESTORED · DOWNTIME ";
            string from = En ? ruP : enP, to = En ? enP : ruP;
            if (!h.StartsWith(from)) return h;
            string rest = h.Substring(from.Length);
            foreach (var u in Units) rest = rest.Replace(En ? u[0] : u[1], En ? u[1] : u[0]);
            return to + rest;
        }

        // начинается ли строка с фразы — на любом из двух языков
        public static bool Starts(string text, string ru)
        {
            if (text == null) return false;
            Init();
            string e;
            return text.StartsWith(ru) || (ru2en.TryGetValue(ru, out e) && text.StartsWith(e));
        }

