    // ============================== ТЕМА: CRT-КОГИТАТОР ==============================
    static class Theme
    {
        public static readonly Color Bg = Color.FromArgb(4, 9, 5);
        public static readonly Color BgLog = Color.FromArgb(3, 7, 4);
        public static readonly Color Green = Color.FromArgb(84, 238, 112);
        public static readonly Color GreenMid = Color.FromArgb(52, 170, 78);
        public static readonly Color GreenDim = Color.FromArgb(30, 104, 48);
        public static readonly Color GreenDark = Color.FromArgb(10, 34, 16);
        public static readonly Color Orange = Color.FromArgb(255, 122, 40);
        public static readonly Color OrangeDim = Color.FromArgb(150, 66, 22);
        public static readonly Color Red = Color.FromArgb(255, 70, 52);
        public static readonly Color Amber = Color.FromArgb(255, 150, 46);
        public static readonly Color Text = Color.FromArgb(176, 236, 186);

        static readonly Dictionary<string, Font> cache = new Dictionary<string, Font>();

        // ---- выбор шрифта: consolas (по умолчанию), courier, fixedsys, dos ----
        [DllImport("gdi32.dll", CharSet = CharSet.Unicode)] static extern int AddFontResourceEx(string name, uint fl, IntPtr res);
        static System.Drawing.Text.PrivateFontCollection pfc;
        static FontFamily pixFam;
        public static string FontKey = "fixedsys";
        public static bool Pixel { get { return pixFam != null; } }

        public static void InitFont(string key)
        {
            FontKey = key ?? "consolas";
            string res = FontKey == "fixedsys" ? "FSEX.ttf" : FontKey == "dos" ? "CogDOS.ttf" : null;
            if (res == null) return;
            // уже установлен в системе — берём оттуда
            string sysName = FontKey == "fixedsys" ? "Fixedsys Excelsior" : "Cogitator DOS VGA";
            try { using (var t = new Font(sysName, 10f)) if (t.Name == sysName) { var h = t.Height; pixFam = new FontFamily(sysName); return; } } catch { }
            try
            {
                // шрифт лежит внутри exe; на время работы выкладывается во временную папку
                string dir = Path.Combine(Path.GetTempPath(), "Cogitator");
                Directory.CreateDirectory(dir);
                string path = Path.Combine(dir, res);
                using (var st = Assembly.GetExecutingAssembly().GetManifestResourceStream(res))
                {
                    var data = new byte[st.Length]; st.Read(data, 0, data.Length);
                    if (!File.Exists(path) || new FileInfo(path).Length != data.Length) File.WriteAllBytes(path, data);
                }
                try { AddFontResourceEx(path, 0x10, IntPtr.Zero); } catch { }   // для окон журнала (GDI), только для этого процесса
                pfc = new System.Drawing.Text.PrivateFontCollection();
                pfc.AddFontFile(path);                                            // для отрисовки (GDI+)
                pixFam = pfc.Families[0];
                using (var test = new Font(pixFam, 10f)) { var h = test.Height; }   // проверка, что шрифт живой
            }
            catch { pixFam = null; FontKey = "consolas"; }
        }

        // пиксельный шрифт чёток только в родном размере (16 px) и вдвое больше; мелочь остаётся обычным моноширинным
        static Font PixelFont(float size, FontStyle st)
        {
            float px = size * 96f / 72f;
            if (px < 10.5f) return Try(new[] { "Consolas", "Lucida Console", "Courier New" }, size, st);
            float target = px >= 26f ? 32f : 16f;
            try { return new Font(pixFam, target, FontStyle.Regular, GraphicsUnit.Pixel); } catch { return Try(new[] { "Consolas" }, size, st); }
        }

        public static Font Mono(float size, FontStyle st)
        {
            string key = "m" + size + st;
            Font f;
            if (cache.TryGetValue(key, out f)) return f;
            f = Pixel ? PixelFont(size, st)
              : FontKey == "courier" ? Try(new[] { "Courier New", "Courier", "Consolas" }, size, st)
              : Try(new[] { "Consolas", "Lucida Console", "Courier New" }, size, st);
            cache[key] = f;
            return f;
        }

        public static Font Title(float size)
        {
            string key = "t" + size;
            Font f;
            if (cache.TryGetValue(key, out f)) return f;
            f = Pixel ? PixelFont(size, FontStyle.Bold)
              : FontKey == "courier" ? Try(new[] { "Courier New", "Courier" }, size, FontStyle.Bold)
              : Try(new[] { "OCR A Extended", "Consolas", "Lucida Console" }, size, FontStyle.Bold);
            cache[key] = f;
            return f;
        }

        static Font Try(string[] names, float size, FontStyle st)
        {
            foreach (var n in names)
            {
                try { var f = new Font(n, size, st); if (f.Name == n) return f; f.Dispose(); } catch { }
            }
            return new Font(FontFamily.GenericMonospace, size, st);
        }

        public static void Prep(Graphics g)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.AntiAliasGridFit;
        }

        public static void Glow(Graphics g, string s, Font f, Color c, RectangleF r, StringFormat sf)
        {
            using (var b = new SolidBrush(Color.FromArgb(38, c)))
            {
                g.DrawString(s, f, b, new RectangleF(r.X - 1.5f, r.Y, r.Width, r.Height), sf);
                g.DrawString(s, f, b, new RectangleF(r.X + 1.5f, r.Y, r.Width, r.Height), sf);
                g.DrawString(s, f, b, new RectangleF(r.X, r.Y - 1.5f, r.Width, r.Height), sf);
                g.DrawString(s, f, b, new RectangleF(r.X, r.Y + 1.5f, r.Width, r.Height), sf);
            }
            using (var b = new SolidBrush(c)) g.DrawString(s, f, b, r, sf);
        }

        public static void Glow(Graphics g, string s, Font f, Color c, float x, float y)
        {
            Glow(g, s, f, c, new RectangleF(x, y, 4000, 400), StringFormat.GenericTypographic);
        }

        public static void Box(Graphics g, RectangleF r, Color c, float w = 1.5f)
        {
            using (var p = new Pen(Color.FromArgb(45, c), w + 3f)) g.DrawRectangle(p, r.X, r.Y, r.Width, r.Height);
            using (var p = new Pen(c, w)) g.DrawRectangle(p, r.X, r.Y, r.Width, r.Height);
        }

        public static void Line(Graphics g, Color c, float x1, float y1, float x2, float y2, float w = 1.5f)
        {
            using (var p = new Pen(Color.FromArgb(45, c), w + 3f)) g.DrawLine(p, x1, y1, x2, y2);
            using (var p = new Pen(c, w)) g.DrawLine(p, x1, y1, x2, y2);
        }

        // двойное перекрестие, как на экранах когитаторов
        public static void Cross(Graphics g, float x, float y, float arm, Color c)
        {
            float o = 3.5f;
            Line(g, c, x - arm, y - o, x + arm, y - o, 1.4f);
            Line(g, c, x - arm, y + o, x + arm, y + o, 1.4f);
            Line(g, c, x - o, y - arm, x - o, y + arm, 1.4f);
            Line(g, c, x + o, y - arm, x + o, y + arm, 1.4f);
        }

        public static void Scanlines(Graphics g, Rectangle r)
        {
            using (var b = new SolidBrush(Color.FromArgb(30, 0, 0, 0)))
                for (int y = r.Top; y < r.Bottom; y += 3) g.FillRectangle(b, r.Left, y, r.Width, 1);
        }

        // зерно люминофора и строки развёртки в одной текстуре: одна заливка вместо сотен вызовов
        static TextureBrush overlay;
        static TextureBrush OverlayBrush
        {
            get
            {
                if (overlay != null) return overlay;
                var bmp = new Bitmap(160, 159, PixelFormat.Format32bppPArgb);
                var rnd = new Random(4242);
                for (int y = 0; y < 159; y++)
                    for (int x = 0; x < 160; x++)
                    {
                        Color c = Color.Transparent;
                        double r = rnd.NextDouble();
                        if (r < 0.09) c = Color.FromArgb(rnd.Next(6, 15), 120, 255, 140);
                        else if (r < 0.12) c = Color.FromArgb(rnd.Next(12, 30), 0, 0, 0);
                        if (y % 3 == 0) c = Color.FromArgb(Math.Min(255, c.A + 30), 0, 0, 0);
                        if (c.A > 0) bmp.SetPixel(x, y, c);
                    }
                overlay = new TextureBrush(bmp, WrapMode.Tile);
                return overlay;
            }
        }

        public static void Overlay(Graphics g, Rectangle r, int ox, int oy)
        {
            var b = OverlayBrush;
            b.ResetTransform();
            b.TranslateTransform(ox, oy - oy % 3);
            var old = g.CompositingQuality;
            g.CompositingQuality = CompositingQuality.HighSpeed;
            g.FillRectangle(b, r);
            g.CompositingQuality = old;
        }

        static readonly Dictionary<Size, Bitmap> vignettes = new Dictionary<Size, Bitmap>();

        public static Bitmap VignetteBitmap(Size sz)
        {
            Bitmap bmp;
            if (vignettes.TryGetValue(sz, out bmp)) return bmp;
            if (vignettes.Count > 6) { foreach (var v in vignettes.Values) v.Dispose(); vignettes.Clear(); }
            bmp = new Bitmap(Math.Max(1, sz.Width), Math.Max(1, sz.Height), PixelFormat.Format32bppPArgb);
            using (var g = Graphics.FromImage(bmp))
            using (var gp = new GraphicsPath())
            {
                var r = new Rectangle(0, 0, sz.Width, sz.Height);
                gp.AddEllipse(RectangleF.Inflate(r, r.Width * 0.22f, r.Height * 0.32f));
                using (var pb = new PathGradientBrush(gp) { CenterColor = Color.FromArgb(0, 0, 0, 0), SurroundColors = new[] { Color.FromArgb(170, 0, 0, 0) }, FocusScales = new PointF(0.6f, 0.55f) })
                    g.FillRectangle(pb, r);
            }
            vignettes[sz] = bmp;
            return bmp;
        }

        static TextureBrush grain;
        static TextureBrush GrainBrush
        {
            get
            {
                if (grain != null) return grain;
                var bmp = new Bitmap(160, 160, PixelFormat.Format32bppArgb);
                var rnd = new Random(1337);
                for (int y = 0; y < 160; y++)
                    for (int x = 0; x < 160; x++)
                    {
                        double r = rnd.NextDouble();
                        if (r < 0.10) bmp.SetPixel(x, y, Color.FromArgb(rnd.Next(6, 16), 120, 255, 140));
                        else if (r < 0.14) bmp.SetPixel(x, y, Color.FromArgb(rnd.Next(14, 34), 0, 0, 0));
                    }
                grain = new TextureBrush(bmp, WrapMode.Tile);
                return grain;
            }
        }

        // едва заметное зерно люминофора
        public static void PaintGrain(Graphics g, Rectangle r, int ox, int oy)
        {
            var b = GrainBrush;
            b.ResetTransform();
            b.TranslateTransform(ox, oy);
            g.FillRectangle(b, r);
        }

        // затемнение к краям, как у выпуклого кинескопа
        public static void Vignette(Graphics g, Rectangle r)
        {
            if (r.Width < 10 || r.Height < 10) return;
            g.DrawImageUnscaled(VignetteBitmap(r.Size), r.X, r.Y);
        }

        public static PointF[] CogPoints(PointF c, float ro, float ri, int teeth, float angle)
        {
            int n = teeth * 4;
            var pts = new PointF[n];
            for (int i = 0; i < n; i++)
            {
                double a = 2 * Math.PI * i / n - Math.PI / 2 + angle;
                float r = (i % 4 == 0 || i % 4 == 1) ? ro : ri;
                pts[i] = new PointF(c.X + (float)(r * Math.Cos(a)), c.Y + (float)(r * Math.Sin(a)));
            }
            return pts;
        }

        public static StringFormat Center = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
        public static StringFormat Left = new StringFormat { Alignment = StringAlignment.Near, LineAlignment = StringAlignment.Center };
        public static StringFormat Right = new StringFormat { Alignment = StringAlignment.Far, LineAlignment = StringAlignment.Center };
    }

    // базовая CRT-панель: двойная буферизация, фон, развёртка
    static class TipText
    {
        // перенос по словам под заданную ширину
        public static List<string> Wrap(Graphics g, IEnumerable<string> lines, Font f, float maxW)
        {
            var res = new List<string>();
            foreach (var line in lines)
            {
                if (g.MeasureString(line, f).Width <= maxW) { res.Add(line); continue; }
                var cur = "";
                foreach (var w in line.Split(new[] { ' ' }))
                {
                    string t = cur.Length == 0 ? w : cur + " " + w;
                    if (g.MeasureString(t, f).Width > maxW && cur.Length > 0) { res.Add(cur); cur = w; }
                    else cur = t;
                }
                if (cur.Length > 0) res.Add(cur);
            }
            return res;
        }

        // подсказка внутри заданной области: не вылезает за её края
        public static void Draw(Graphics g, RectangleF area, PointF at, IEnumerable<string> lines, Font f, Color border)
        {
            var wl = Wrap(g, lines, f, Math.Max(80, area.Width - 28));
            float lh = g.MeasureString("Ж", f).Height;
            float w = Math.Min(area.Width - 8, wl.Max(l => g.MeasureString(l, f).Width) + 18), h = lh * wl.Count + 10;
            float x = at.X + 14, y = at.Y - h - 10;
            if (x + w > area.Right - 4) x = at.X - w - 10;
            if (x < area.X + 4) x = area.X + 4;
            if (y < area.Y + 4) y = at.Y + 14;
            if (y + h > area.Bottom - 4) y = Math.Max(area.Y + 4, area.Bottom - 4 - h);
            var r = new RectangleF(x, y, w, h);
            using (var b = new SolidBrush(Color.FromArgb(245, 3, 8, 4))) g.FillRectangle(b, r);
            Theme.Box(g, r, border, 1.3f);
            for (int i = 0; i < wl.Count; i++) using (var b = new SolidBrush(i == 0 ? Theme.Orange : Theme.Text)) g.DrawString(wl[i], f, b, r.X + 8, r.Y + 5 + i * lh);
        }
    }

    class CrtControl : Control
    {
        public CrtControl()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
            BackColor = Theme.Bg;
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            Theme.Prep(g);
            using (var b = new SolidBrush(BackColor)) g.FillRectangle(b, ClientRectangle);
            PaintContent(g);
            Theme.Overlay(g, ClientRectangle, 0, 0);
        }

        protected virtual void PaintContent(Graphics g) { }
    }

    // ---------- верхняя полоса ----------
    class TopBar : CrtControl
    {
        public string Status = Loc.T("СИСТЕМА :ГОТОВ");
        public Color StatusColor = Theme.Green;

        protected override void PaintContent(Graphics g)
        {
            var r = new RectangleF(12, 10, Width - 24, Height - 16);
            Theme.Box(g, r, Theme.Green);
            Theme.Glow(g, Loc.T("КОГИТАТОР СВЯЗИ  -  ИСПЫТАНИЕ МАШИННОГО ДУХА СЕТИ"), Theme.Title(14f), Theme.Orange,
                new RectangleF(r.X + 28, r.Y, r.Width - 380, r.Height), Theme.Left);

            var f = Theme.Mono(10.5f, FontStyle.Bold);
            var sz = g.MeasureString(Status, f);
            float bw = Math.Max(250, sz.Width + 30), bh = 26;
            var sb = new RectangleF(r.Right - bw - 18, r.Y + (r.Height - bh) / 2, bw, bh);
            Theme.Box(g, sb, StatusColor, 1.4f);
            Theme.Glow(g, Status, f, StatusColor, sb, Theme.Center);
        }
    }

    // ---------- эмблема + часы ----------
    class EmblemPanel : CrtControl
    {
        public float Angle;
        readonly Random noise = new Random();
        Point mouse = new Point(-1, -1);
        protected override void OnMouseMove(MouseEventArgs e) { mouse = e.Location; Invalidate(); base.OnMouseMove(e); }
        protected override void OnMouseLeave(EventArgs e) { mouse = new Point(-1, -1); Invalidate(); base.OnMouseLeave(e); }

        protected override void PaintContent(Graphics g)
        {
            float bw = Math.Min(Width - 40, 360), bh = Height - 40;
            var box = new RectangleF((Width - bw) / 2 + 8, 8, bw, bh);
            Theme.Box(g, box, Theme.Orange, 2f);
            Theme.Box(g, new RectangleF(box.X + 5, box.Y + 5, box.Width - 10, box.Height - 10), Theme.OrangeDim, 1f);
            Theme.Glow(g, Loc.T("СОНАР · ПУТЬ ДО 1.1.1.1"), Theme.Mono(7.5f, FontStyle.Bold), Theme.Orange, box.X + 12, box.Y + 9);

            List<SonarHop> hops; int reach; DateTime last; bool tun;
            lock (SonarProbe.Lk) { hops = SonarProbe.Hops.Select(h => new SonarHop { Ttl = h.Ttl, Addr = h.Addr, AsName = h.AsName, Asn = h.Asn, Hist = new List<double>(h.Hist) }).ToList(); reach = SonarProbe.Reach; last = SonarProbe.Last; tun = SonarProbe.Tunnel; }

            var c = new PointF(box.X + box.Width * 0.36f, box.Y + box.Height / 2 + 6);
            float R = Math.Min(box.Width * 0.34f, box.Height / 2 - 20);
            // помехи на экране сонара: редкие искры и полоса шума
            for (int i = 0; i < 46; i++)
            {
                double a = noise.NextDouble() * Math.PI * 2, d = Math.Sqrt(noise.NextDouble()) * R;
                float px = c.X + (float)(Math.Cos(a) * d), py = c.Y + (float)(Math.Sin(a) * d);
                using (var b = new SolidBrush(Color.FromArgb(18 + noise.Next(34), Theme.Green))) g.FillRectangle(b, px, py, 1.5f, 1.5f);
            }
            if (noise.Next(5) == 0)
            {
                float ny = c.Y - R + (float)noise.NextDouble() * R * 2, half = (float)Math.Sqrt(Math.Max(0, R * R - (ny - c.Y) * (ny - c.Y)));
                using (var pen = new Pen(Color.FromArgb(22 + noise.Next(20), Theme.Green), 1f)) g.DrawLine(pen, c.X - half, ny, c.X + half, ny);
            }
            int n = Math.Max(4, hops.Count);
            // кольца прыжков
            for (int i = 1; i <= n; i++)
            {
                float rr = R * i / n;
                using (var pen = new Pen(Color.FromArgb(i == n ? 70 : 34, Theme.Green), 1f)) g.DrawEllipse(pen, c.X - rr, c.Y - rr, rr * 2, rr * 2);
            }
            using (var pen = new Pen(Color.FromArgb(28, Theme.Green), 1f)) { g.DrawLine(pen, c.X - R, c.Y, c.X + R, c.Y); g.DrawLine(pen, c.X, c.Y - R, c.X, c.Y + R); }
            // луч и его шлейф
            float sweep = (Angle * 57.3f) % 360f;
            for (int t = 0; t < 14; t++)
            {
                float a = (sweep - t * 3) * (float)Math.PI / 180f;
                using (var pen = new Pen(Color.FromArgb(Math.Max(0, 90 - t * 6), Theme.Green), 2f)) g.DrawLine(pen, c.X, c.Y, c.X + (float)Math.Cos(a) * R, c.Y + (float)Math.Sin(a) * R);
            }
            // центр — ты
            using (var b = new SolidBrush(Theme.Red)) g.FillEllipse(b, c.X - 3.5f, c.Y - 3.5f, 7, 7);

            string hover = null; Color hoverC = Theme.Green; PointF hoverP = PointF.Empty;
            for (int i = 0; i < hops.Count; i++)
            {
                var h = hops[i];
                float ang = (-90 + i * 360f / n) * (float)Math.PI / 180f, rr = R * (i + 1) / n;
                var p = new PointF(c.X + (float)Math.Cos(ang) * rr, c.Y + (float)Math.Sin(ang) * rr);
                var ok = h.Hist.Where(v => v >= 0).ToList();
                double loss = h.Hist.Count > 0 ? 100.0 * (h.Hist.Count - ok.Count) / h.Hist.Count : 0;
                bool silent = h.Addr == null || ok.Count == 0;
                Color col = silent ? Theme.GreenDim : loss >= 30 ? Theme.Red : loss >= 10 ? Theme.Amber : Theme.Green;
                // вспышка, когда луч проходит над отметкой
                float da = ((sweep - (-90 + i * 360f / n)) % 360 + 360) % 360;
                int glow = silent ? 150 + noise.Next(50) - (int)(Math.Min(1f, da / 240f) * 40) : (int)(255 - Math.Min(1f, da / 240f) * 150);
                if (silent)
                {
                    // призрак: мерцающее пунктирное кольцо со знаком вопроса
                    using (var b = new SolidBrush(Color.FromArgb(28, Theme.GreenMid))) g.FillEllipse(b, p.X - 7, p.Y - 7, 14, 14);
                    using (var pen = new Pen(Color.FromArgb(glow, Theme.GreenMid), 1.3f) { DashStyle = DashStyle.Dash }) g.DrawEllipse(pen, p.X - 6, p.Y - 6, 12, 12);
                    using (var b = new SolidBrush(Color.FromArgb(glow, Theme.GreenMid))) g.DrawString("?", Theme.Mono(7f, FontStyle.Bold), b, p.X - 4, p.Y - 6);
                }
                else
                {
                    using (var b = new SolidBrush(Color.FromArgb(glow / 3, col))) g.FillEllipse(b, p.X - 7, p.Y - 7, 14, 14);
                    using (var b = new SolidBrush(Color.FromArgb(glow, col))) g.FillEllipse(b, p.X - 3.5f, p.Y - 3.5f, 7, 7);
                }
                if (i + 1 == reach) using (var pen = new Pen(Theme.Orange, 1.2f)) g.DrawRectangle(pen, p.X - 6, p.Y - 6, 12, 12);
                if (mouse.X >= 0 && Math.Abs(mouse.X - p.X) < 8 && Math.Abs(mouse.Y - p.Y) < 8)
                {
                    string who = silent ? Loc.T("МОЛЧИТ НА ICMP") : h.Addr + (h.AsName != null ? " · " + h.AsName : "") + (i == 0 && tun ? Loc.T(" · СВЯТИЛИЩЕ") : "");
                    hover = Loc.T("ПРЫЖОК ") + h.Ttl + ": " + who + (silent ? "" : " · " + Math.Round(ok.Average()) + Loc.T(" МС") + (loss > 0 ? " · " + Math.Round(loss) + "%" : ""));
                    hoverC = col; hoverP = p;
                }
            }

            // справа — сводка
            float tx = box.X + box.Width * 0.70f, ty = box.Y + 30;
            var sf = Theme.Mono(7.5f, FontStyle.Bold);
            var tgt = reach > 0 && hops.Count >= reach ? hops[reach - 1] : null;
            double tr = tgt != null && tgt.Hist.Any(v => v >= 0) ? tgt.Hist.Where(v => v >= 0).Average() : -1;
            int silentN = hops.Count(h => h.Addr == null);
            var lines = new[]
            {
                new KeyValuePair<string, Color>(last == DateTime.MinValue ? Loc.T("ПЕРВЫЙ ОПРОС…") : reach > 0 ? Loc.T("ЦЕЛЬ ") + (tr >= 0 ? Math.Round(tr) + Loc.T(" МС") : "—") : Loc.T("ЦЕЛЬ НЕ ОТВЕТИЛА"), reach > 0 ? Theme.Green : Theme.Red),
                new KeyValuePair<string, Color>(Loc.T("ПРЫЖКОВ ") + (reach > 0 ? reach.ToString() : "—"), Theme.GreenMid),
                new KeyValuePair<string, Color>(Loc.T("МОЛЧАТ ") + silentN, silentN > 0 ? Theme.GreenDim : Theme.GreenMid),
                new KeyValuePair<string, Color>(tun ? Loc.T("ТУННЕЛЬ") : Loc.T("НАПРЯМУЮ"), tun ? Theme.Green : Theme.Amber),
                new KeyValuePair<string, Color>(last == DateTime.MinValue ? "" : (int)(DateTime.Now - last).TotalSeconds + Loc.T(" С НАЗАД"), Theme.GreenDim)
            };
            foreach (var kv in lines) { if (kv.Key.Length > 0) Theme.Glow(g, kv.Key, sf, kv.Value, new RectangleF(tx, ty, box.Right - tx - 8, 14), Ui.NoWrap); ty += 17; }

            var tb = new RectangleF(box.X + 14, box.Bottom - 2, box.Width - 28, 24);
            using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, tb);
            Theme.Box(g, tb, Theme.Green, 1.4f);
            Theme.Glow(g, Loc.T("ВРЕМЯ  T ") + DateTime.Now.ToString("HH:mm:ss"), Theme.Mono(10f, FontStyle.Bold), Theme.Green, tb, Theme.Center);

            if (hover != null)
                TipText.Draw(g, new RectangleF(box.X + 6, box.Y + 24, box.Width - 12, box.Height - 30), hoverP, new[] { hover }, Theme.Mono(8f, FontStyle.Bold), hoverC);
            Theme.Line(g, Theme.GreenDim, 14, 6, 14, Height, 1.2f);
        }
    }

    // ---------- шифрованное сообщение (правая колонка) ----------
    class MessagePanel : CrtControl
    {
        List<KeyValuePair<string, Color>> lines = new List<KeyValuePair<string, Color>>();
        List<int> shown = new List<int>();   // сколько символов каждой строки уже «напечатано»
        readonly System.Windows.Forms.Timer typer;
        int blink, step;

        public MessagePanel()
        {
            typer = new System.Windows.Forms.Timer { Interval = 28 };
            typer.Tick += (s, e) =>
            {
                blink++; step++;
                int i = Typing;
                if (i < 0) { typer.Stop(); Invalidate(); return; }
                shown[i] = Math.Min(lines[i].Key.Length, shown[i] + 2 + (step % 7 == 0 ? 0 : 1));   // неровный темп, как у телетайпа
                Invalidate();
            };
        }

        // первая недопечатанная строка (или -1)
        int Typing { get { for (int i = 0; i < lines.Count; i++) if (shown[i] < lines[i].Key.Length) return i; return -1; } }

        public void Set(params object[] pairs)
        {
            var nl = new List<KeyValuePair<string, Color>>();
            for (int i = 0; i + 1 < pairs.Length; i += 2)
                if (pairs[i] != null && ((string)pairs[i]).Length > 0)
                    nl.Add(new KeyValuePair<string, Color>((string)pairs[i], (Color)pairs[i + 1]));
            // каждая строка сама по себе: неизменные остаются как есть, у изменённых допечатывается только новый хвост
            var ns = new List<int>();
            for (int i = 0; i < nl.Count; i++)
            {
                if (i < lines.Count && lines[i].Value == nl[i].Value)
                {
                    string a = lines[i].Key, b = nl[i].Key;
                    int k = 0; while (k < a.Length && k < b.Length && a[k] == b[k]) k++;
                    ns.Add(Math.Min(shown[i], k));
                }
                else ns.Add(0);
            }
            lines = nl; shown = ns;
            if (Typing >= 0) typer.Start();
            Invalidate();
        }

        protected override void PaintContent(Graphics g)
        {
            var f = Theme.Mono(9.25f, FontStyle.Bold);
            float x0 = 14, tx = 36, y = 10, w = Width - tx - 14;
            float lastTick = y;
            int typing = Typing;
            for (int i = 0; i < lines.Count; i++)
            {
                // строки ниже печатаемой и ещё не начатые — не показываем
                if (typing >= 0 && i > typing && shown[i] == 0) break;
                var kv = lines[i];
                string full = kv.Key;
                string vis = full.Substring(0, Math.Min(full.Length, shown[i]));
                var sz = g.MeasureString(full, f, (int)w);
                float lh = g.MeasureString("Ж", f).Height;
                if (y + lh > Height - 6) break;
                float mid = y + lh / 2;
                Theme.Line(g, Theme.GreenDim, x0, mid, tx - 6, mid, 1.2f);
                lastTick = mid;
                float hgt = Math.Min(sz.Height + 2, Height - 6 - y);
                Theme.Glow(g, vis + (i == typing && blink % 6 < 4 ? "█" : ""), f, kv.Value, new RectangleF(tx, y, w, hgt), StringFormat.GenericDefault);
                y += sz.Height + 6;
            }
            Theme.Line(g, Theme.GreenDim, x0, 0, x0, lastTick, 1.2f);
        }
    }

    // ---------- кнопка-ритуал ----------
    class CrtButton : CrtControl
    {
        public string Num, Title, Sub;
        bool hover, down;

        public CrtButton(string num, string title, string sub)
        {
            Num = num; Title = title; Sub = sub;
            Cursor = Cursors.Hand;
            Dock = DockStyle.Fill;
            Margin = new Padding(0, 4, 0, 4);
        }

        protected override void OnMouseEnter(EventArgs e) { hover = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = false; down = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseDown(MouseEventArgs e) { down = true; Invalidate(); base.OnMouseDown(e); }
        protected override void OnMouseUp(MouseEventArgs e) { down = false; Invalidate(); base.OnMouseUp(e); }
        protected override void OnEnabledChanged(EventArgs e) { Cursor = Enabled ? Cursors.Hand : Cursors.Default; Invalidate(); base.OnEnabledChanged(e); }

        protected override void PaintContent(Graphics g)
        {
            bool en = Enabled;
            var r = new RectangleF(2, 2, Width - 5, Height - 5);
            if (en && (hover || down))
                using (var b = new SolidBrush(down ? Color.FromArgb(18, 60, 28) : Theme.GreenDark)) g.FillRectangle(b, r);
            Color bc = !en ? Color.FromArgb(22, 58, 30) : hover ? Theme.Green : Theme.GreenMid;
            Theme.Box(g, r, bc, 1.4f);

            // оранжевые уголки
            Color oc = en ? Theme.Orange : Color.FromArgb(70, 40, 20);
            float k = 7;
            Theme.Line(g, oc, r.X, r.Y, r.X + k, r.Y, 1.6f); Theme.Line(g, oc, r.X, r.Y, r.X, r.Y + k, 1.6f);
            Theme.Line(g, oc, r.Right, r.Y, r.Right - k, r.Y, 1.6f); Theme.Line(g, oc, r.Right, r.Y, r.Right, r.Y + k, 1.6f);
            Theme.Line(g, oc, r.X, r.Bottom, r.X + k, r.Bottom, 1.6f); Theme.Line(g, oc, r.X, r.Bottom, r.X, r.Bottom - k, 1.6f);
            Theme.Line(g, oc, r.Right, r.Bottom, r.Right - k, r.Bottom, 1.6f); Theme.Line(g, oc, r.Right, r.Bottom, r.Right, r.Bottom - k, 1.6f);

            Color tc = en ? Theme.Green : Color.FromArgb(34, 80, 42);
            if (string.IsNullOrEmpty(Num))
            {
                Theme.Glow(g, Title, Theme.Mono(9.5f, FontStyle.Bold), tc, r, Theme.Center);
                return;
            }
            float nw = 58;
            Theme.Glow(g, Num, Theme.Title(15f), en ? Theme.Orange : Color.FromArgb(80, 44, 20), new RectangleF(r.X, r.Y, nw, r.Height), Theme.Center);
            Theme.Line(g, en ? Theme.GreenDim : Color.FromArgb(20, 50, 26), r.X + nw, r.Y + 8, r.X + nw, r.Bottom - 8, 1.2f);
            float tx = r.X + nw + 12;
            var ft = Theme.Mono(10.5f, FontStyle.Bold);
            var fs = Theme.Mono(8.5f, FontStyle.Regular);
            float th = g.MeasureString(Title, ft).Height, sh = g.MeasureString(Sub, fs).Height;
            float y0 = r.Y + (r.Height - th - sh) / 2;
            Theme.Glow(g, Title, ft, tc, tx, y0);
            using (var b = new SolidBrush(en ? Theme.GreenMid : Color.FromArgb(28, 64, 34))) g.DrawString(Sub, fs, b, tx, y0 + th);
        }
    }

    // ---------- осциллограф пинга ----------
    class Scope : CrtControl
    {
        const int Max = 160;
        List<double> data = new List<double>();
        readonly object lk = new object();
        public float Phase;
        public string Target = "—";

        public void Add(double v) { lock (lk) { data.Add(v); if (data.Count > Max) data.RemoveAt(0); } }
        public void Clear() { lock (lk) data.Clear(); }

        // ---- режим трафика: что идёт по сети прямо сейчас ----
        public bool TrafficMode = true;
        public string Source = "—";
        List<double> down = new List<double>(), up = new List<double>();
        double curDown = -1, curUp = -1;
        bool labelHover;

        public void AddTraffic(double downBits, double upBits, string src)
        {
            lock (lk)
            {
                down.Add(downBits); up.Add(upBits);
                if (down.Count > Max) { down.RemoveAt(0); up.RemoveAt(0); }
            }
            curDown = downBits; curUp = upBits; Source = src;
        }

        public void ClearTraffic() { lock (lk) { down.Clear(); up.Clear(); } curDown = curUp = -1; }

        // ---- режим карты пути: итог ритуала III / IV цепочкой узлов ----
        public List<Diag.Leg> Legs;
        public int Mode;   // 0 — трафик, 1 — пинг ритуала, 2 — карта пути
        class PHit { public RectangleF R; public string[] Lines; public Color C; }
        List<PHit> phits = new List<PHit>();
        Point pmouse = new Point(-1, -1);

        public void SetPath(List<Diag.Leg> legs) { Legs = legs; Mode = 2; TrafficMode = false; Invalidate(); }

        void PaintPath(Graphics g)
        {
            phits.Clear();
            var outer = new RectangleF(6, 6, Width - 13, Height - 13);
            PaintHeader(g, outer, Loc.T("КАРТА ПУТИ"));
            var legs = Legs ?? new List<Diag.Leg>();
            if (legs.Count == 0) { Theme.Glow(g, Loc.T("КАРТЫ ЕЩЁ НЕТ — СОВЕРШИ РИТУАЛ III"), Theme.Mono(9f, FontStyle.Bold), Theme.GreenDim, outer, Theme.Center); return; }
            float top = outer.Y + 50, rowH = (outer.Bottom - 8 - top) / legs.Count;
            var lf = Theme.Mono(7.5f, FontStyle.Bold);
            for (int li = 0; li < legs.Count; li++)
            {
                var lg = legs[li];
                var row = new RectangleF(outer.X + 14, top + li * rowH, outer.Width - 28, rowH);
                string name = lg.Tunnel ? Loc.T("ЗА СВЯТИЛИЩЕМ") : Loc.T("ДО СВЯТИЛИЩА");
                using (var b = new SolidBrush(Theme.Orange)) g.DrawString(name, lf, b, row.X, row.Y + row.Height / 2 - 6);
                float cx0 = row.X + 108, cw = row.Right - cx0 - 6;
                float cy = row.Y + row.Height * 0.58f;
                // участки: владелец + автономная система
                var cl = new List<List<Hop>>();
                foreach (var h in lg.Hops)
                {
                    var c = cl.Count > 0 ? cl[cl.Count - 1] : null;
                    string ca = c == null ? null : c.Select(x => x.Asn).FirstOrDefault(x => x != null);
                    if (c == null || c[0].Own != h.Own || (h.Asn != null && ca != null && h.Asn != ca)) cl.Add(new List<Hop> { h }); else c.Add(h);
                }
                bool tailFog = !lg.Reached && (lg.Hidden || lg.Problem);
                int slots = lg.Hops.Count + (tailFog ? 2 : 0) + 1;   // +1 — сам дом/начало
                if (lg.Hops.Count == 0)
                {
                    var fr = new RectangleF(cx0, cy - 12, cw, 24);
                    using (var pen = new Pen(Color.FromArgb(90, Theme.GreenDim), 1f) { DashStyle = DashStyle.Dash }) g.DrawRectangle(pen, fr.X, fr.Y, fr.Width, fr.Height);
                    Theme.Glow(g, lg.Hidden || lg.Blocked ? Loc.T("УЧАСТОК СКРЫТ: ICMP ЗАКРЫТ (KILL SWITCH)") : Loc.T("НИ ОДИН УЗЕЛ НЕ ОТВЕТИЛ"), lf, lg.Problem ? Theme.Red : Theme.GreenDim, fr, Theme.Center);
                    phits.Add(new PHit { R = fr, C = Theme.GreenDim, Lines = new[] { name, lg.Text ?? "" } });
                    continue;
                }
                float step = cw / Math.Max(2, slots);
                // исток
                float x0s = cx0 + step * 0.5f;
                using (var b = new SolidBrush(Theme.GreenMid)) g.FillRectangle(b, x0s - 4, cy - 4, 8, 8);
                using (var b = new SolidBrush(Theme.GreenDim)) g.DrawString(lg.Tunnel ? Loc.T("ТУННЕЛЬ") : Loc.T("ТЫ"), Theme.Mono(6.5f, FontStyle.Bold), b, x0s - 14, cy + 8);
                float prevX = x0s; int k = 1;
                bool afterOrigin = false;
                foreach (var c in cl)
                {
                    float sx = cx0 + step * k, ex = cx0 + step * (k + c.Count);
                    var seg = new RectangleF(sx + 2, cy - row.Height * 0.42f, ex - sx - 4, row.Height * 0.70f);
                    bool bad = lg.Problem && lg.Reached && lg.Origin != null && c.Contains(lg.Origin);
                    Color sc = bad || afterOrigin ? Theme.Red : Theme.GreenDim;
                    using (var pen = new Pen(Color.FromArgb(bad ? 200 : 90, sc), 1f)) g.DrawRectangle(pen, seg.X, seg.Y, seg.Width, seg.Height);
                    var ah = c.FirstOrDefault(h => h.AsName != null);
                    string cap = Diag.Short(!lg.Tunnel && c[0].Own == Owner.Server ? Owner.Beyond : c[0].Own) + (ah != null && c[0].Own != Owner.Router ? " · " + ah.AsName : "");
                    using (var b = new SolidBrush(bad ? Theme.Red : Theme.GreenMid)) g.DrawString(cap, Theme.Mono(6.5f, FontStyle.Bold), b, new RectangleF(seg.X + 3, seg.Y + 1, seg.Width - 4, 11), Ui.NoWrap);
                    foreach (var h in c)
                    {
                        float hx = cx0 + step * (k + 0.5f);
                        Color lc = h.Loss >= 20 ? Theme.Red : h.Loss >= 5 ? Theme.Amber : Theme.Green;
                        using (var pen = new Pen(Color.FromArgb(afterOrigin ? 180 : 120, afterOrigin ? Theme.Red : Theme.GreenMid), 1.4f)) g.DrawLine(pen, prevX + 5, cy, hx - 5, cy);
                        using (var b = new SolidBrush(lc)) g.FillEllipse(b, hx - 4.5f, cy - 4.5f, 9, 9);
                        if (h == lg.Origin) { afterOrigin = true; Theme.Glow(g, "◄", Theme.Mono(9f, FontStyle.Bold), Theme.Red, hx + 6, cy - 8); }
                        using (var b = new SolidBrush(Theme.GreenDim)) g.DrawString(h.Rtt + (h.Loss > 0 ? " · " + h.Loss + "%" : ""), Theme.Mono(6.5f, FontStyle.Regular), b, new RectangleF(hx - step / 2, cy + 7, step, 11), Theme.Center);
                        phits.Add(new PHit { R = new RectangleF(hx - step / 2, seg.Y, step, seg.Height), C = lc, Lines = new[] { h.Num + ". " + h.Addr, Diag.Short(h.Own) + (h.Asn != null ? " · AS" + h.Asn + (h.AsName != null ? " " + h.AsName : "") : ""), "RTT " + h.Rtt + Loc.T(" · ПОТЕРИ ") + h.Loss + "%" } });
                        prevX = hx; k++;
                    }
                }
                if (tailFog)
                {
                    float fx = cx0 + step * k, fw = step * 2 - 4;
                    var fr = new RectangleF(fx + 2, cy - row.Height * 0.42f, fw, row.Height * 0.70f);
                    using (var pen = new Pen(Color.FromArgb(lg.Problem ? 200 : 90, lg.Problem ? Theme.Red : Theme.GreenDim), 1f) { DashStyle = DashStyle.Dash }) g.DrawRectangle(pen, fr.X, fr.Y, fr.Width, fr.Height);
                    using (var pen = new Pen(Color.FromArgb(90, Theme.GreenDim), 1.2f) { DashStyle = DashStyle.Dot }) g.DrawLine(pen, prevX + 5, cy, fr.X + 6, cy);
                    Theme.Glow(g, Diag.Short(lg.Own) + (lg.Problem ? " ✗" : " ?"), Theme.Mono(7f, FontStyle.Bold), lg.Problem ? Theme.Red : Theme.GreenDim, fr, Theme.Center);
                    phits.Add(new PHit { R = fr, C = lg.Problem ? Theme.Red : Theme.GreenDim, Lines = new[] { lg.Problem ? Loc.T("ОБРЫВ") : Loc.T("УЗЛЫ МОЛЧАТ НА ICMP"), lg.Text ?? "" } });
                }
                else if (lg.Reached)
                {
                    // импульс бежит по цепи — сеть жива
                    float run = (Phase * 0.35f) % 1f;
                    float px = cx0 + step * 0.5f + (prevX - cx0 - step * 0.5f) * run;
                    using (var b = new SolidBrush(Color.FromArgb(160, Theme.Orange))) g.FillEllipse(b, px - 2.5f, cy - 2.5f, 5, 5);
                }
            }
            // подсказка — с переносом и в пределах модуля
            if (pmouse.X >= 0)
            {
                var h = phits.LastOrDefault(x => x.R.Contains(pmouse));
                if (h != null) TipText.Draw(g, new RectangleF(outer.X + 2, outer.Y + 2, outer.Width - 4, outer.Height - 4), pmouse, h.Lines, Theme.Mono(8.5f, FontStyle.Bold), h.C);
            }
        }


        RectangleF LabelRect { get { return new RectangleF(20, 30, 210, 20); } }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            pmouse = e.Location; if (Mode == 2 && !TrafficMode) Invalidate();
            bool h = LabelRect.Contains(e.Location);
            if (h != labelHover) { labelHover = h; Cursor = h ? Cursors.Hand : Cursors.Default; Invalidate(); }
            base.OnMouseMove(e);
        }

        protected override void OnMouseLeave(EventArgs e) { labelHover = false; pmouse = new Point(-1, -1); Cursor = Cursors.Default; Invalidate(); base.OnMouseLeave(e); }

        protected override void OnMouseClick(MouseEventArgs e)
        {
            if (LabelRect.Contains(e.Location))
            {
                // трафик → пинг ритуала → карта пути (если есть) → трафик
                int m = TrafficMode ? 0 : Mode == 2 ? 2 : 1;
                m = (m + 1) % 3; if (m == 2 && (Legs == null || Legs.Count == 0)) m = 0;
                Mode = m; TrafficMode = m == 0; Invalidate();
            }
            base.OnMouseClick(e);
        }

        public static string Rate(double bits)
        {
            if (bits < 0) return "---";
            if (bits >= 1e6) return (bits / 1e6).ToString(bits >= 1e8 ? "0" : "0.0") + Loc.T(" Мбит/с");
            if (bits >= 1e3) return Math.Round(bits / 1e3) + Loc.T(" кбит/с");
            return Math.Round(bits) + Loc.T(" бит/с");
        }

        void PaintHeader(Graphics g, RectangleF outer, string title)
        {
