            Theme.Box(g, lb, labelHover ? Theme.Green : Theme.GreenMid, 1.2f);
            Theme.Glow(g, title, lf, Theme.Green, lb, Theme.Center);
            using (var b = new SolidBrush(labelHover ? Theme.Orange : Theme.GreenDim))
                g.DrawString(Loc.T("<> ЩЕЛЧОК — СМЕНИТЬ РЕЖИМ"), Theme.Mono(7.5f, FontStyle.Regular), b, lb.Right + 10, lb.Y + 4);
        }

        void PaintTraffic(Graphics g)
        {
            List<double> dn, upl; lock (lk) { dn = new List<double>(down); upl = new List<double>(up); }
            var outer = new RectangleF(6, 6, Width - 13, Height - 13);
            PaintHeader(g, outer, Loc.T("ОСЦИЛЛОГРАФ ТРАФИКА"));

            float rw = 168;
            var plot = new RectangleF(outer.X + 14, outer.Y + 54, outer.Width - rw - 36, outer.Height - 64);
            using (var p = new Pen(Color.FromArgb(40, Theme.Green), 1f) { DashStyle = DashStyle.Dot })
            {
                for (int i = 1; i < 4; i++) g.DrawLine(p, plot.X, plot.Y + plot.Height * i / 4, plot.Right, plot.Y + plot.Height * i / 4);
                for (int i = 1; i < 8; i++) g.DrawLine(p, plot.X + plot.Width * i / 8, plot.Y, plot.X + plot.Width * i / 8, plot.Bottom);
            }
            Theme.Box(g, plot, Theme.GreenDim, 1f);

            double peak = 0;
            foreach (var v in dn) if (v > peak) peak = v;
            foreach (var v in upl) if (v > peak) peak = v;
            double top = Math.Max(100e3, peak * 1.25);
            using (var b = new SolidBrush(Theme.GreenDim))
            {
                var tf = Theme.Mono(7.5f, FontStyle.Regular);
                g.DrawString(Rate(top), tf, b, plot.X + 3, plot.Y + 2);
                g.DrawString("0", tf, b, plot.X + 3, plot.Bottom - 13);
                if (dn.Count > 0) g.DrawString(Loc.T("ПИК ") + Rate(peak), tf, b, new RectangleF(plot.X, plot.Y + 2, plot.Width - 4, 14), Ui.NoWrapRight);
            }

            float step = plot.Width / (Max - 1);
            if (dn.Count > 1)
            {
                var pd = new PointF[dn.Count]; var pu = new PointF[upl.Count];
                for (int i = 0; i < dn.Count; i++)
                {
                    float x = plot.Right - (dn.Count - 1 - i) * step;   // свежие данные справа, история уезжает влево
                    pd[i] = new PointF(x, plot.Bottom - (float)(plot.Height * Math.Min(1.0, dn[i] / top)));
                    pu[i] = new PointF(x, plot.Bottom - (float)(plot.Height * Math.Min(1.0, upl[i] / top)));
                }
                // заливка под приёмом
                var area = new PointF[pd.Length + 2];
                Array.Copy(pd, area, pd.Length);
                area[pd.Length] = new PointF(pd[pd.Length - 1].X, plot.Bottom);
                area[pd.Length + 1] = new PointF(pd[0].X, plot.Bottom);
                using (var b = new SolidBrush(Color.FromArgb(30, Theme.Green))) g.FillPolygon(b, area);
                using (var p = new Pen(Color.FromArgb(55, Theme.Green), 5f)) g.DrawLines(p, pd);
                using (var p = new Pen(Theme.Green, 1.6f)) g.DrawLines(p, pd);
                using (var p = new Pen(Color.FromArgb(55, Theme.Orange), 4f)) g.DrawLines(p, pu);
                using (var p = new Pen(Theme.Orange, 1.4f)) g.DrawLines(p, pu);
            }
            else Theme.Glow(g, Loc.T("НАСТРАИВАЮСЬ НА ПОТОК..."), Theme.Mono(9f, FontStyle.Bold), Theme.GreenDim, plot, Theme.Center);

            // легенда
            float lx = plot.X + 120, ly = plot.Y + 4;
            using (var b = new SolidBrush(Theme.Green)) g.FillRectangle(b, lx, ly + 5, 12, 3);
            using (var b = new SolidBrush(Theme.GreenMid)) g.DrawString(Loc.T("ПРИЁМ"), Theme.Mono(7.5f, FontStyle.Bold), b, lx + 16, ly);
            using (var b = new SolidBrush(Theme.Orange)) g.FillRectangle(b, lx + 72, ly + 5, 12, 3);
            using (var b = new SolidBrush(Theme.GreenMid)) g.DrawString(Loc.T("ОТДАЧА"), Theme.Mono(7.5f, FontStyle.Bold), b, lx + 88, ly);

            float rx = outer.Right - rw - 10;
            Readout(g, Loc.T("ИСТОЧНИК"), Source, new RectangleF(rx, outer.Y + 8, rw, 0), Theme.Green);
            Readout(g, Loc.T("ПРИЁМ  \u2193"), Rate(curDown), new RectangleF(rx, outer.Y + 8 + (outer.Height - 16) / 3, rw, 0), Theme.Green);
            Readout(g, Loc.T("ОТДАЧА  \u2191"), Rate(curUp), new RectangleF(rx, outer.Y + 8 + 2 * (outer.Height - 16) / 3, rw, 0), Theme.Orange);
        }

        protected override void PaintContent(Graphics g)
        {
            if (TrafficMode) { PaintTraffic(g); return; }
            if (Mode == 2) { PaintPath(g); return; }
            List<double> d; lock (lk) d = new List<double>(data);
            var outer = new RectangleF(6, 6, Width - 13, Height - 13);
            PaintHeader(g, outer, Loc.T("ОСЦИЛЛОГРАФ ПИНГА"));
            var lf = Theme.Mono(8.5f, FontStyle.Bold);

            float rw = 168;
            var plot = new RectangleF(outer.X + 14, outer.Y + 54, outer.Width - rw - 36, outer.Height - 64);
            using (var p = new Pen(Color.FromArgb(40, Theme.Green), 1f) { DashStyle = DashStyle.Dot })
            {
                for (int i = 1; i < 4; i++) g.DrawLine(p, plot.X, plot.Y + plot.Height * i / 4, plot.Right, plot.Y + plot.Height * i / 4);
                for (int i = 1; i < 8; i++) g.DrawLine(p, plot.X + plot.Width * i / 8, plot.Y, plot.X + plot.Width * i / 8, plot.Bottom);
            }
            Theme.Box(g, plot, Theme.GreenDim, 1f);

            double top = 50;
            foreach (var v in d) if (v > top) top = v;
            top = Math.Ceiling(top * 1.2 / 10) * 10;
            using (var b = new SolidBrush(Theme.GreenDim))
            {
                var tf = Theme.Mono(7.5f, FontStyle.Regular);
                g.DrawString(top + Loc.T(" мс"), tf, b, plot.X + 3, plot.Y + 2);
                g.DrawString("0", tf, b, plot.X + 3, plot.Bottom - 13);
            }

            if (d.Count == 0)
            {
                var pts = new List<PointF>();
                for (int i = 0; i <= 120; i++)
                {
                    float x = plot.X + plot.Width * i / 120f;
                    double yy = Math.Sin(i * 0.22 + Phase) * 0.12 + Math.Sin(i * 0.61 + Phase * 1.7) * 0.05;
                    pts.Add(new PointF(x, plot.Y + plot.Height * (0.5f - (float)yy)));
                }
                using (var p = new Pen(Color.FromArgb(35, Theme.Green), 4f)) g.DrawLines(p, pts.ToArray());
                using (var p = new Pen(Theme.GreenDim, 1.4f)) g.DrawLines(p, pts.ToArray());
                Theme.Glow(g, Loc.T("ОЖИДАНИЕ СИГНАЛА"), Theme.Mono(9f, FontStyle.Bold), Theme.GreenDim, plot, Theme.Center);
            }
            else
            {
                float step = plot.Width / (Max - 1);
                var seg = new List<PointF>();
                Action flush = () =>
                {
                    if (seg.Count > 1)
                    {
                        using (var p = new Pen(Color.FromArgb(55, Theme.Green), 5f)) g.DrawLines(p, seg.ToArray());
                        using (var p = new Pen(Theme.Green, 1.6f)) g.DrawLines(p, seg.ToArray());
                    }
                    else if (seg.Count == 1)
                        using (var b = new SolidBrush(Theme.Green)) g.FillEllipse(b, seg[0].X - 2, seg[0].Y - 2, 4, 4);
                    seg.Clear();
                };
                for (int i = 0; i < d.Count; i++)
                {
                    float x = plot.X + i * step;
                    if (d[i] < 0)
                    {
                        flush();
                        Theme.Line(g, Theme.Orange, x, plot.Bottom - 2, x, plot.Bottom - 16, 1.6f);
                    }
                    else seg.Add(new PointF(x, plot.Bottom - (float)(plot.Height * Math.Min(1.0, d[i] / top))));
                }
                flush();
            }

            // показания справа
            var last = d.Skip(Math.Max(0, d.Count - 20)).ToList();
            var ok = last.Where(v => v >= 0).ToList();
            string ping = ok.Count > 0 ? Math.Round(ok.Average()).ToString() : "---";
            string loss = last.Count > 0 ? (int)Math.Round(100.0 * (last.Count - ok.Count) / last.Count) + "%" : "---";
            float rx = outer.Right - rw - 10;
            Readout(g, Loc.T("ЦЕЛЬ"), Target, new RectangleF(rx, outer.Y + 8, rw, 0), Theme.Green);
            Readout(g, Loc.T("ПИНГ, МС"), ping, new RectangleF(rx, outer.Y + 8 + (outer.Height - 16) / 3, rw, 0), Theme.Green);
            Readout(g, Loc.T("ПОТЕРИ"), loss, new RectangleF(rx, outer.Y + 8 + 2 * (outer.Height - 16) / 3, rw, 0),
                last.Count > 0 && ok.Count < last.Count ? Theme.Orange : Theme.Green);
        }

        static void Readout(Graphics g, string label, string val, RectangleF at, Color vc)
        {
            var lf = Theme.Mono(8.5f, FontStyle.Bold);
            Theme.Glow(g, label, lf, Theme.Orange, new RectangleF(at.X, at.Y, at.Width, 16), Theme.Right);
            var vb = new RectangleF(at.X, at.Y + 17, at.Width, 24);
            Theme.Box(g, vb, Theme.Green, 1.4f);
            // крупно, если влезает; иначе мельче; если и так не влезает — обрезать в одну строку
            var vf = Theme.Mono(val.Length > 12 ? 9f : 11.5f, FontStyle.Bold);
            if (g.MeasureString(val, vf).Width > vb.Width - 8) vf = Theme.Mono(7.5f, FontStyle.Bold);
            Theme.Glow(g, val, vf, vc, new RectangleF(vb.X + 4, vb.Y, vb.Width - 8, vb.Height), Ui.NoWrapCenter);
        }
    }

