    // ============================== АВТОПОИСК СВЯТИЛИЩ ==============================
    // Ищет адреса VPN-серверов там, где их оставляют клиенты WireGuard / AmneziaWG / AmneziaVPN:
    // службы туннелей и их конфиги, файлы в папках Amnezia, настройки в реестре.
    static class AutoDetect
    {
        public class Found { public string Host, Name, Source; public int Port = 22; }

        static readonly Regex EndpointRx = new Regex(@"Endpoint\s*=\s*\[?([A-Za-z0-9\.\-]+)\]?\s*:\s*(\d{2,5})", RegexOptions.IgnoreCase);
        static readonly Regex ObjRx = new Regex("\\{[^{}]*\"hostName\"[^{}]*\\}", RegexOptions.Singleline);
        static readonly Regex HostRx = new Regex("\"hostName\"\\s*:\\s*\"([^\"]+)\"");
        static readonly Regex PortRx = new Regex("\"port\"\\s*:\\s*\"?(\\d{1,5})");
        static readonly Regex DescRx = new Regex("\"description\"\\s*:\\s*\"([^\"]*)\"");
        static readonly Regex PathRx = new Regex(@"[A-Za-z]:\\[^""<>|*?\r\n]+?\.(conf|json)", RegexOptions.IgnoreCase);
        const string PrivateRx = @"^(10\.|127\.|0\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.|169\.254\.)";

        public static List<Found> Run(List<string> log)
        {
            var found = new List<Found>();
            int files = 0, values = 0, services = 0;

            // 1. службы туннелей и их конфиги
            try
            {
                using (var svcs = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services"))
                    if (svcs != null)
                        foreach (var name in svcs.GetSubKeyNames())
                        {
                            bool tunnel = name.StartsWith("WireGuardTunnel$", StringComparison.OrdinalIgnoreCase) || name.StartsWith("AmneziaWGTunnel$", StringComparison.OrdinalIgnoreCase);
                            if (!tunnel && name.IndexOf("amnezia", StringComparison.OrdinalIgnoreCase) < 0) continue;
                            services++;
                            string tname = name.Contains("$") ? name.Substring(name.IndexOf('$') + 1) : name;
                            using (var k = svcs.OpenSubKey(name))
                            {
                                var img = k == null ? null : k.GetValue("ImagePath") as string;
                                if (img == null) continue;
                                foreach (Match m in PathRx.Matches(img)) ScanFile(m.Value, Loc.T("служба ") + name, tname, found, ref files);
                            }
                        }
            }
            catch { }
            log.Add(Loc.T("службы туннелей: ") + services);

            // 2. файлы в папках Amnezia
            var roots = new[]
            {
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),
                Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),
                Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)
            };
            foreach (var root in roots.Where(x => !string.IsNullOrEmpty(x)).Distinct())
            {
                try
                {
                    foreach (var dir in Directory.GetDirectories(root))
                    {
                        var dn = Path.GetFileName(dir);
                        if (dn.IndexOf("amnezia", StringComparison.OrdinalIgnoreCase) < 0 && dn.IndexOf("wireguard", StringComparison.OrdinalIgnoreCase) < 0) continue;
                        Walk(dir, 0, found, ref files);
                    }
                }
                catch { }
            }
            log.Add(Loc.T("просмотрено файлов: ") + files);

            // 3. настройки в реестре (QSettings клиента AmneziaVPN)
            try
            {
                using (var sw = Registry.CurrentUser.OpenSubKey("Software"))
                    if (sw != null)
                        foreach (var name in sw.GetSubKeyNames())
                            if (name.IndexOf("amnezia", StringComparison.OrdinalIgnoreCase) >= 0)
                                using (var k = sw.OpenSubKey(name)) ScanKey(k, 0, Loc.T("реестр ") + name, found, ref values);
            }
            catch { }
            log.Add(Loc.T("значений в реестре: ") + values);
            return found;
        }

        static void Walk(string dir, int depth, List<Found> found, ref int files)
        {
            if (depth > 5 || files > 400) return;
            try
            {
                foreach (var f in Directory.GetFiles(dir))
                {
                    var ext = Path.GetExtension(f).ToLowerInvariant();
                    if (ext != ".conf" && ext != ".json" && ext != ".ini" && ext != ".cfg" && ext != ".txt") continue;
                    ScanFile(f, Loc.T("файл ") + f, null, found, ref files);
                    if (files > 400) return;
                }
                foreach (var d in Directory.GetDirectories(dir)) Walk(d, depth + 1, found, ref files);
            }
            catch { }
        }

        static void ScanFile(string path, string source, string tunnelName, List<Found> found, ref int files)
        {
            try
            {
                var fi = new FileInfo(path);
                if (!fi.Exists || fi.Length > 1024 * 1024) return;
                files++;
                ScanText(File.ReadAllText(path), source, tunnelName, found);
            }
            catch { }
        }

        static void ScanKey(RegistryKey k, int depth, string source, List<Found> found, ref int values)
        {
            if (k == null || depth > 4 || values > 3000) return;
            try
            {
                foreach (var vn in k.GetValueNames())
                {
                    values++;
                    var v = k.GetValue(vn);
                    var str = v as string;
                    var arr = v as string[];
                    var bin = v as byte[];
                    if (str != null) ScanText(str, source, null, found);
                    else if (arr != null) ScanText(string.Join("\n", arr), source, null, found);
                    else if (bin != null)
                    {
                        ScanText(Encoding.UTF8.GetString(bin), source, null, found);
                        ScanText(Encoding.Unicode.GetString(bin), source, null, found);
                    }
                }
                foreach (var sk in k.GetSubKeyNames())
                    using (var c = k.OpenSubKey(sk)) ScanKey(c, depth + 1, source, found, ref values);
            }
            catch { }
        }

        static void ScanText(string text, string source, string tunnelName, List<Found> found)
        {
            if (string.IsNullOrEmpty(text)) return;
            text = text.Replace("\\\"", "\"");
            foreach (Match m in EndpointRx.Matches(text))
                Add(found, m.Groups[1].Value, 22, tunnelName, source);
            foreach (Match o in ObjRx.Matches(text))
            {
                var h = HostRx.Match(o.Value);
                if (!h.Success) continue;
                int port = 22;
                var pm = PortRx.Match(o.Value);
                if (pm.Success) { int pp; if (int.TryParse(pm.Groups[1].Value, out pp) && pp > 0 && pp < 65536) port = pp; }
                var dm = DescRx.Match(o.Value);
                Add(found, h.Groups[1].Value, port, dm.Success && dm.Groups[1].Value.Trim().Length > 0 ? dm.Groups[1].Value.Trim() : tunnelName, source);
            }
        }

        static void Add(List<Found> found, string host, int port, string name, string source)
        {
            host = (host ?? "").Trim().Trim('[', ']');
            if (host.Length < 4 || host.Length > 253 || !host.Contains(".")) return;
            if (host.Equals("localhost", StringComparison.OrdinalIgnoreCase) || Regex.IsMatch(host, PrivateRx)) return;
            if (!Regex.IsMatch(host, @"^[A-Za-z0-9\.\-]+$")) return;
            var ex = found.FirstOrDefault(f => f.Host.Equals(host, StringComparison.OrdinalIgnoreCase));
            if (ex != null)
            {
                if ((ex.Name == null || ex.Name.Length == 0) && !string.IsNullOrEmpty(name)) ex.Name = name;
                if (ex.Port == 22 && port != 22) ex.Port = port;
                return;
            }
            found.Add(new Found { Host = host, Port = port, Name = name, Source = source });
        }
    }

    // ============================== КАРКАСЫ СТРАНИЦ ==============================
    class PagePanel : Panel
    {
        public PagePanel()
        {
            DoubleBuffered = true;
            SetStyle(ControlStyles.ResizeRedraw, true);
            BackColor = Theme.Bg;
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            if (bg == null || bg.Size != ClientSize)
            {
                if (bg != null) bg.Dispose();
                bg = new Bitmap(Math.Max(1, ClientSize.Width), Math.Max(1, ClientSize.Height), PixelFormat.Format32bppPArgb);
                using (var bg2 = Graphics.FromImage(bg))
                {
                    using (var b = new SolidBrush(Theme.Bg)) bg2.FillRectangle(b, 0, 0, bg.Width, bg.Height);
                    Theme.PaintGrain(bg2, new Rectangle(0, 0, bg.Width, bg.Height), 0, 0);
                    Theme.Vignette(bg2, new Rectangle(0, 0, bg.Width, bg.Height));
                }
            }
            g.DrawImageUnscaled(bg, 0, 0);
        }
        Bitmap bg;
    }

    class FramePanel : Panel
    {
        public string Title = "", RightText = "";
        public bool Crosses;

        public FramePanel(string title, bool crosses)
        {
            Title = title; Crosses = crosses;
            DoubleBuffered = true;
            SetStyle(ControlStyles.ResizeRedraw, true);
            BackColor = Theme.Bg;
            Padding = crosses ? new Padding(60, 66, 60, 60) : new Padding(22, 66, 22, 22);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            Theme.Prep(g);
            using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, ClientRectangle);
            Theme.Box(g, new RectangleF(5, 5, Width - 11, Height - 11), Theme.OrangeDim, 1.2f);
            Theme.Box(g, new RectangleF(11, 11, Width - 23, Height - 23), Theme.Green, 1.6f);
            float lx = 26;
            if (Crosses)
            {
                Theme.Cross(g, 34, 34, 18, Theme.Orange);
                Theme.Cross(g, Width - 34, 34, 18, Theme.Orange);
                Theme.Cross(g, 34, Height - 34, 18, Theme.Orange);
                Theme.Cross(g, Width - 34, Height - 34, 18, Theme.Orange);
                lx = 66;
            }
            var lf = Theme.Mono(8.5f, FontStyle.Bold);
            Theme.Glow(g, Loc.T("МОДУЛЬ"), lf, Theme.Orange, lx, 18 - (Theme.Pixel ? 3 : 0));
            float tw = Math.Max(176, g.MeasureString(Title, lf).Width + 28);
            var lb = new RectangleF(lx, 34, tw, 20);
            Theme.Box(g, lb, Theme.Green, 1.2f);
            Theme.Glow(g, Title, lf, Theme.Green, lb, Theme.Center);
            if (RightText.Length > 0)
                Theme.Glow(g, RightText, Theme.Mono(9f, FontStyle.Bold), Theme.Orange,
                    new RectangleF(lx + tw + 10, 30, Width - lx - tw - 10 - (Crosses ? 66 : 26), 28), Ui.NoWrapRight);
            Theme.Overlay(g, ClientRectangle, 0, 0);
        }
    }

    // ---------- навигация ----------
    class NavBar : CrtControl
    {
        public string[] Tabs = { Loc.T("ТЕРМИНАЛ"), Loc.T("СВЯТИЛИЩА"), Loc.T("ИСПЫТАНИЯ"), Loc.T("ЛЕТОПИСЬ"), Loc.T("ВРАТА") };
        public string[] Nums = { "0", "I", "II", "III", "IV" };
        public int Selected, Blink;
        public bool Busy, GuardOn, GuardDown;
        public string GuardText = Loc.T("СТРАЖ: ВЫКЛЮЧЕН");
        public event Action<int> TabClicked;
        public event Action GuardClicked;
        int hover = -1;
        bool guardHover;

        RectangleF TabRect(int i)
        {
            float w = Math.Min(220, (Width - 24 - 4 * 10 - 388) / 5f);
            return new RectangleF(12 + i * (w + 10), 6, w, Height - 14);
        }

        RectangleF GuardRect { get { return new RectangleF(Width - 292, 6, 280, Height - 14); } }
        RectangleF LangRect { get { return new RectangleF(Width - 292 - 88, 6, 80, Height - 14); } }
        public event Action LangClicked;
        bool langHover;


        protected override void OnMouseMove(MouseEventArgs e)
        {
            int h = -1;
            for (int i = 0; i < Tabs.Length; i++) if (TabRect(i).Contains(e.Location)) h = i;
            bool gh = GuardRect.Contains(e.Location), lh = LangRect.Contains(e.Location);
            if (h != hover || gh != guardHover || lh != langHover) { hover = h; guardHover = gh; langHover = lh; Cursor = h >= 0 || gh || lh ? Cursors.Hand : Cursors.Default; Invalidate(); }
            base.OnMouseMove(e);
        }

        protected override void OnMouseLeave(EventArgs e) { hover = -1; guardHover = false; langHover = false; Invalidate(); base.OnMouseLeave(e); }

        protected override void OnMouseClick(MouseEventArgs e)
        {
            if (GuardRect.Contains(e.Location) && GuardClicked != null) GuardClicked();
            if (LangRect.Contains(e.Location) && LangClicked != null) LangClicked();
            for (int i = 0; i < Tabs.Length; i++)
                if (TabRect(i).Contains(e.Location) && TabClicked != null) TabClicked(i);
            base.OnMouseClick(e);
        }

        protected override void PaintContent(Graphics g)
        {
            Theme.Line(g, Theme.GreenDim, 0, Height - 2, Width, Height - 2, 1.2f);
            var fn = Theme.Title(11f);
            var ft = Theme.Mono(9.5f, FontStyle.Bold);
            for (int i = 0; i < Tabs.Length; i++)
            {
                var r = TabRect(i);
                bool sel = i == Selected, hov = i == hover;
                if (sel) using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, r);
                Theme.Box(g, r, sel ? Theme.Green : hov ? Theme.GreenMid : Theme.GreenDim, sel ? 1.6f : 1.2f);
                if (sel) Theme.Line(g, Theme.Orange, r.X + 6, r.Bottom - 3, r.Right - 6, r.Bottom - 3, 1.6f);
                Theme.Glow(g, Nums[i], fn, sel ? Theme.Orange : Theme.OrangeDim, new RectangleF(r.X, r.Y, 46, r.Height), Theme.Center);
                Theme.Glow(g, Tabs[i], ft, sel ? Theme.Green : hov ? Theme.GreenMid : Theme.GreenDim, new RectangleF(r.X + 46, r.Y, r.Width - 52, r.Height), Theme.Left);
                if (i == 2 && Busy && (Blink / 5) % 2 == 0)
                    using (var b = new SolidBrush(Theme.Orange)) g.FillEllipse(b, r.Right - 16, r.Y + r.Height / 2 - 4, 8, 8);
            }
            // переключатель языка: активный — ярко, второй — приглушённо
            var lr = LangRect;
            Theme.Box(g, lr, langHover ? Theme.Green : Theme.GreenMid, 1.3f);
            var lf = Theme.Mono(9.5f, FontStyle.Bold);
            float half = lr.Width / 2f;
            var ruR = new RectangleF(lr.X, lr.Y, half, lr.Height); var enR = new RectangleF(lr.X + half, lr.Y, half, lr.Height);
            if (!Loc.En) using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, ruR);
            else using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, enR);
            Theme.Line(g, Theme.GreenDim, lr.X + half, lr.Y + 6, lr.X + half, lr.Bottom - 6, 1f);
            Theme.Glow(g, "RU", lf, Loc.En ? Theme.GreenDim : Theme.Orange, ruR, Theme.Center);
            Theme.Glow(g, "EN", lf, Loc.En ? Theme.Orange : Theme.GreenDim, enR, Theme.Center);

            // переключатель стража
            var gr = GuardRect;
            Color gc = !GuardOn ? Theme.GreenDim : GuardDown ? Theme.Red : Theme.Green;
            if (GuardOn && GuardDown && (Blink / 4) % 2 == 0) using (var b = new SolidBrush(Color.FromArgb(60, Theme.Red))) g.FillRectangle(b, gr);
            else if (GuardOn) using (var b = new SolidBrush(Color.FromArgb(28, Theme.Green))) g.FillRectangle(b, gr);
            Theme.Box(g, gr, guardHover ? Theme.Green : gc, GuardOn ? 1.6f : 1.2f);
            // глаз стража
            float ex = gr.X + 22, ey = gr.Y + gr.Height / 2;
            using (var pen = new Pen(GuardOn ? Theme.Orange : Theme.OrangeDim, 1.6f)) { g.DrawArc(pen, ex - 11, ey - 9, 22, 18, 200, 140); g.DrawArc(pen, ex - 11, ey - 9, 22, 18, 20, 140); }
            using (var b = new SolidBrush(GuardOn ? (GuardDown ? Theme.Red : Theme.Orange) : Theme.OrangeDim)) g.FillEllipse(b, ex - 3.5f, ey - 3.5f, 7, 7);
            Theme.Glow(g, GuardText, Theme.Mono(9f, FontStyle.Bold), gc, new RectangleF(gr.X + 40, gr.Y, gr.Width - 46, gr.Height), Ui.NoWrap);
        }
    }

    // ---------- плитка главного терминала ----------
    class HomeTile : CrtControl
    {
        public string Num, Title, Desc, Stat = "";
        public Color StatColor = Theme.GreenMid;
        bool hover;

        public HomeTile(string num, string title, string desc) { Num = num; Title = title; Desc = desc; Cursor = Cursors.Hand; }

        protected override void OnMouseEnter(EventArgs e) { hover = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = false; Invalidate(); base.OnMouseLeave(e); }

        protected override void PaintContent(Graphics g)
        {
            var r = new RectangleF(3, 3, Width - 7, Height - 7);
            if (hover) using (var b = new SolidBrush(Color.FromArgb(14, 44, 20))) g.FillRectangle(b, r);
            Theme.Box(g, r, hover ? Theme.Green : Theme.GreenMid, 1.6f);
            Theme.Box(g, new RectangleF(r.X + 6, r.Y + 6, r.Width - 12, r.Height - 12), Color.FromArgb(70, Theme.GreenDim), 1f);
            float k = 14;
            foreach (var pt in new[] { new PointF(r.X, r.Y), new PointF(r.Right, r.Y), new PointF(r.X, r.Bottom), new PointF(r.Right, r.Bottom) })
            {
                float sx = pt.X == r.X ? 1 : -1, sy = pt.Y == r.Y ? 1 : -1;
                Theme.Line(g, Theme.Orange, pt.X, pt.Y, pt.X + k * sx, pt.Y, 2f);
                Theme.Line(g, Theme.Orange, pt.X, pt.Y, pt.X, pt.Y + k * sy, 2f);
            }
            Theme.Glow(g, Num, Theme.Title(34f), Theme.Orange, r.X + 26, r.Y + 20);
            Theme.Glow(g, Title, Theme.Title(15f), hover ? Theme.Green : Theme.GreenMid, r.X + 26, r.Y + 82);
            Theme.Line(g, Theme.GreenDim, r.X + 26, r.Y + 112, r.Right - 26, r.Y + 112, 1.2f);
            using (var b = new SolidBrush(Theme.Text))
                g.DrawString(Desc, Theme.Mono(9.5f, FontStyle.Regular), b, new RectangleF(r.X + 26, r.Y + 124, r.Width - 52, r.Height - 180));
            var sr = new RectangleF(r.X + 18, r.Bottom - 48, r.Width - 36, 30);
            Theme.Box(g, sr, Theme.GreenDim, 1.1f);
            Theme.Glow(g, Stat, Theme.Mono(9f, FontStyle.Bold), StatColor, new RectangleF(sr.X + 10, sr.Y, sr.Width - 20, sr.Height), new StringFormat { LineAlignment = StringAlignment.Center, Trimming = StringTrimming.EllipsisCharacter, FormatFlags = StringFormatFlags.NoWrap });
            if (hover) Theme.Glow(g, Loc.T(">> ВОЙТИ"), Theme.Mono(9f, FontStyle.Bold), Theme.Orange, new RectangleF(r.X, r.Y + 26, r.Right - 26, 20), Theme.Right);
        }
    }

    // ---------- переключатель на главном терминале ----------
    class HomeSwitch : CrtControl
    {
        public bool On;
        public string Title = "", SubOn = "", SubOff = "";
        bool hover;

        public HomeSwitch() { Cursor = Cursors.Hand; }
        protected override void OnMouseEnter(EventArgs e) { hover = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = false; Invalidate(); base.OnMouseLeave(e); }

        protected override void PaintContent(Graphics g)
        {
            var r = new RectangleF(2, 2, Width - 5, Height - 5);
            if (hover) using (var b = new SolidBrush(Color.FromArgb(14, 44, 20))) g.FillRectangle(b, r);
            Theme.Box(g, r, hover ? Theme.Green : On ? Theme.GreenMid : Theme.GreenDim, 1.5f);
            float k = 9;
            Theme.Line(g, Theme.Orange, r.X, r.Y, r.X + k, r.Y, 1.8f); Theme.Line(g, Theme.Orange, r.X, r.Y, r.X, r.Y + k, 1.8f);
            Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right - k, r.Bottom, 1.8f); Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right, r.Bottom - k, 1.8f);

            // символ питания
            float cx = r.X + 30, cy = r.Y + r.Height / 2, rr = 11;
            Color ic = On ? Theme.Orange : Theme.OrangeDim;
            using (var pen = new Pen(Color.FromArgb(50, ic), 5f)) g.DrawArc(pen, cx - rr, cy - rr, rr * 2, rr * 2, -60, 300);
            using (var pen = new Pen(ic, 2f)) { g.DrawArc(pen, cx - rr, cy - rr, rr * 2, rr * 2, -60, 300); g.DrawLine(pen, cx, cy - rr - 3, cx, cy - 2); }

            // ползунок ВКЛ / ВЫКЛ
            var sw = new RectangleF(r.Right - 86, cy - 12, 70, 24);
            Theme.Box(g, sw, On ? Theme.Green : Theme.GreenDim, 1.3f);
            var knob = On ? new RectangleF(sw.X + 36, sw.Y + 4, 30, sw.Height - 8) : new RectangleF(sw.X + 4, sw.Y + 4, 30, sw.Height - 8);
            using (var b = new SolidBrush(On ? Theme.Green : Theme.GreenDim)) g.FillRectangle(b, knob);
            using (var b = new SolidBrush(On ? Theme.Green : Theme.GreenDim))
                g.DrawString(On ? Loc.T("ВКЛ") : Loc.T("ВЫКЛ"), Theme.Mono(7.5f, FontStyle.Bold), b, On ? new RectangleF(sw.X + 2, sw.Y, 34, sw.Height) : new RectangleF(sw.X + 34, sw.Y, 34, sw.Height), Theme.Center);

            float tx = r.X + 56, tw = sw.X - tx - 8;
            Theme.Glow(g, Title, Theme.Mono(10f, FontStyle.Bold), On ? Theme.Green : Theme.GreenMid, new RectangleF(tx, r.Y + 9, tw, 20), Ui.NoWrap);
            using (var b = new SolidBrush(Theme.GreenDim))
                g.DrawString(On ? SubOn : SubOff, Theme.Mono(8f, FontStyle.Regular), b, new RectangleF(tx, r.Y + 30, tw, r.Height - 32));
        }
    }

    // ---------- главный терминал ----------
    class HomePage : Panel
    {
        public HomeTile[] Tiles;
        public HomeSwitch AutoSwitch, HudSwitch;
        public MachineGauge Gauge;
        public float Phase;
        public string[] Status = new string[0];
        public Color[] StatusColors = new Color[0];
        int grainX, grainY;
        readonly Random rnd = new Random();
        readonly string[] streams;
        readonly float[] streamSpeed;

        public HomePage()
        {
            DoubleBuffered = true;
            SetStyle(ControlStyles.ResizeRedraw, true);
            BackColor = Theme.Bg;
            Tiles = new[]
            {
                new HomeTile("I", Loc.T("СВЯТИЛИЩА"), Loc.T("Реестр святилищ. Каждое внесено, наречено и освящено — но лишь одно избирается для служения.")),
                new HomeTile("II", Loc.T("ИСПЫТАНИЯ"), Loc.T("Пять ритуалов: от малой литании до великого обряда с трассировкой. Перекличка пакетов исчисляет павших.")),
                new HomeTile("III", Loc.T("ЛЕТОПИСЬ"), Loc.T("Хроника испытаний: когда, над чем и какой приговор вынес когитатор. Ни одна запись не предаётся забвению."))
            };
            foreach (var t in Tiles) Controls.Add(t);
            AutoSwitch = new HomeSwitch
            {
                Title = Loc.T("САМОСТОЯТЕЛЬНОЕ ПРОБУЖДЕНИЕ"),
                SubOn = Loc.T("Пробуждается с машиной и бдит из тени трея."),
                SubOff = Loc.T("Бдение с первым вздохом машины.")
            };
            Controls.Add(AutoSwitch);
            HudSwitch = new HomeSwitch
            {
                Title = Loc.T("АУСПИК ПОВЕРХ ОКОН"),
                SubOn = Loc.T("Око бдит над всеми окнами. Ctrl+Alt+A — сомкнуть."),
                SubOff = Loc.T("Око над играми и окнами. Ctrl+Alt+A — воззвать.")
            };
            Controls.Add(HudSwitch);
            Gauge = new MachineGauge();
            Controls.Add(Gauge);

            const string hex = "0123456789ABCDEF";
            streams = new string[28]; streamSpeed = new float[28];
            for (int i = 0; i < streams.Length; i++)
            {
                var sb = new StringBuilder();
                for (int j = 0; j < 60; j++) { sb.Append(hex[rnd.Next(16)]); sb.Append(hex[rnd.Next(16)]); sb.Append('\n'); }
                streams[i] = sb.ToString();
                streamSpeed[i] = 6f + (float)rnd.NextDouble() * 14f;
            }
        }

        protected override void OnLayout(LayoutEventArgs e)
        {
            base.OnLayout(e);
            if (Tiles == null) return;
            int gap = 26, margin = 60;
            int w = Math.Min(380, (Width - 2 * margin - 2 * gap) / 3);
            int h = Math.Min(330, Math.Max(250, Height - 330));
            int total = 3 * w + 2 * gap;
            int x0 = (Width - total) / 2, y0 = 150;
            for (int i = 0; i < 3; i++) Tiles[i].SetBounds(x0 + i * (w + gap), y0, w, h);
            if (AutoSwitch != null) AutoSwitch.SetBounds(x0 + 2 * (w + gap), y0 + h + 24, w, 68);
            if (HudSwitch != null) HudSwitch.SetBounds(x0 + 2 * (w + gap), y0 + h + 24 + 78, w, 68);
            if (Gauge != null) Gauge.SetBounds(x0 + (w + gap), y0 + h + 24, w, 146);
        }

        public void Tick()
        {
            Phase += 1f;
            Invalidate();
        }

        Bitmap staticLayer; bool staticDirty = true;
        Bitmap[] streamBmps; float streamBlock;

        public void SetStatus(string[] lines, Color[] colors)
        {
            Status = lines; StatusColors = colors; staticDirty = true; Invalidate();
        }

        protected override void OnResize(EventArgs e) { staticDirty = true; base.OnResize(e); }

        void BuildStreams()
        {
            var f = Theme.Mono(9f, FontStyle.Regular);
            float lineH = 15f;
            streamBlock = lineH * 60;
            streamBmps = new Bitmap[streams.Length];
            for (int i = 0; i < streams.Length; i++)
            {
                var bmp = new Bitmap(34, (int)(streamBlock * 2) + 4, PixelFormat.Format32bppPArgb);
                using (var g = Graphics.FromImage(bmp))
                using (var b = new SolidBrush(Color.FromArgb(18, Theme.Green)))
                {
                    g.TextRenderingHint = TextRenderingHint.AntiAlias;
                    g.DrawString(streams[i], f, b, 0, 0);
                    g.DrawString(streams[i], f, b, 0, streamBlock);
                }
                streamBmps[i] = bmp;
            }
        }

        void BuildStatic()
        {
            var r = ClientRectangle;
            if (staticLayer != null) staticLayer.Dispose();
            staticLayer = new Bitmap(Math.Max(1, r.Width), Math.Max(1, r.Height), PixelFormat.Format32bppPArgb);
            using (var g = Graphics.FromImage(staticLayer))
            {
                Theme.Prep(g);
                g.TextRenderingHint = TextRenderingHint.AntiAlias;
                Theme.Overlay(g, r, 0, 0);
                Theme.Vignette(g, r);
                Theme.Cross(g, 34, 34, 18, Theme.Orange);
                Theme.Cross(g, r.Width - 34, 34, 18, Theme.Orange);
                Theme.Cross(g, 34, r.Height - 34, 18, Theme.Orange);
                Theme.Cross(g, r.Width - 34, r.Height - 34, 18, Theme.Orange);
                Theme.Glow(g, Loc.T("ГЛАВНЫЙ ТЕРМИНАЛ КОГИТАТОРА"), Theme.Title(20f), Theme.Orange, new RectangleF(0, 40, r.Width, 40), Theme.Center);
                Theme.Glow(g, Loc.T("++ ИЗБЕРИ НАПРАВЛЕНИЕ СЛУЖЕНИЯ ++"), Theme.Mono(10f, FontStyle.Bold), Theme.GreenMid, new RectangleF(0, 84, r.Width, 24), Theme.Center);
                if (Tiles != null && Tiles.Length > 0)
                {
                    float y = Tiles[0].Bottom + 34, x = Tiles[0].Left;
                    var stf = Theme.Mono(9.5f, FontStyle.Bold);
                    int shown = 0;
                    for (int i = 0; i < Status.Length; i++)
                    {
                        if (y > r.Height - 50) break;
                        Theme.Line(g, Theme.GreenDim, x, y + 8, x + 14, y + 8, 1.2f);
                        Theme.Glow(g, Status[i], stf, StatusColors[i], new RectangleF(x + 22, y - 2, Tiles[0].Width - 22, 20), Ui.NoWrap);
                        y += 24; shown++;
                    }
                    if (shown > 0) Theme.Line(g, Theme.GreenDim, x, Tiles[0].Bottom + 22, x, Tiles[0].Bottom + 34 + 24 * (shown - 1) + 8, 1.2f);
                }
            }
            staticDirty = false;
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            var r = ClientRectangle;
            if (r.Width < 2 || r.Height < 2) return;
            if (streamBmps == null) BuildStreams();
            if (staticDirty || staticLayer == null || staticLayer.Size != r.Size) BuildStatic();
            g.CompositingQuality = CompositingQuality.HighSpeed;
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, r);

            float colW = Math.Max(40, r.Width / (float)streams.Length);
            for (int i = 0; i < streamBmps.Length; i++)
            {
                float off = (Phase * streamSpeed[i] * 0.25f) % streamBlock;
                g.DrawImageUnscaled(streamBmps[i], (int)(i * colW + 6), (int)(off - streamBlock));
            }

            g.SmoothingMode = SmoothingMode.AntiAlias;
            var c = new PointF(r.Width / 2f, r.Height * 0.55f);
            float ro = Math.Min(r.Width, r.Height) * 0.42f;
            var pts = Theme.CogPoints(c, ro, ro * 0.84f, 24, Phase * 0.002f);
            using (var p = new Pen(Color.FromArgb(22, Theme.Orange), 2f)) g.DrawPolygon(p, pts);
            using (var p = new Pen(Color.FromArgb(14, Theme.Orange), 1.5f)) g.DrawEllipse(p, c.X - ro * 0.5f, c.Y - ro * 0.5f, ro, ro);

            float bandH = 140, by = (Phase * 3f) % (r.Height + bandH) - bandH;
            using (var lb = new LinearGradientBrush(new RectangleF(0, by, r.Width, bandH), Color.FromArgb(0, Theme.Green), Color.FromArgb(14, Theme.Green), 90f))
            {
                lb.SetBlendTriangularShape(0.5f);
                g.FillRectangle(lb, 0, by, r.Width, bandH);
            }

            g.DrawImageUnscaled(staticLayer, 0, 0);
        }
    }

    // ============================== ПЛОТЬ МАШИНЫ: ЦП, ОЗУ, ГП ==============================
    static class SysMon
    {
        [StructLayout(LayoutKind.Sequential)] struct FILETIME { public uint Lo, Hi; }
        [StructLayout(LayoutKind.Sequential)] class MEMSTAT { public uint Len = 64, Load; public ulong TotalPhys, AvailPhys, TotalPage, AvailPage, TotalVirt, AvailVirt, AvailExt; }
        [DllImport("kernel32.dll")] static extern bool GetSystemTimes(out FILETIME idle, out FILETIME kernel, out FILETIME user);
        [DllImport("kernel32.dll")] static extern bool GlobalMemoryStatusEx([In, Out] MEMSTAT m);

        public static volatile float Cpu = -1, Ram = -1, Gpu = -1;
        public static double RamUsedGb, RamTotalGb;
        static Thread th;
        static ulong pIdle, pTotal;
        static Dictionary<string, CounterSample> prevGpu;
        static bool gpuDead;

        public static void Start()
        {
            if (th != null) return;
            th = new Thread(() =>
            {
                while (true)
                {
                    try { Sample(); } catch { }
                    Thread.Sleep(1500);
                }
            }) { IsBackground = true, Priority = ThreadPriority.BelowNormal };
            th.Start();
        }

        static ulong U(FILETIME f) { return ((ulong)f.Hi << 32) | f.Lo; }

        static void Sample()
        {
            FILETIME i, k, u;
            if (GetSystemTimes(out i, out k, out u))
            {
                ulong idle = U(i), total = U(k) + U(u);   // kernel уже включает idle
                if (pTotal > 0 && total > pTotal) Cpu = (float)(100.0 * (1 - (double)(idle - pIdle) / (total - pTotal)));
                pIdle = idle; pTotal = total;
            }
            var m = new MEMSTAT();
            if (GlobalMemoryStatusEx(m))
            {
                RamTotalGb = m.TotalPhys / 1073741824.0; RamUsedGb = (m.TotalPhys - m.AvailPhys) / 1073741824.0;
                Ram = (float)(100.0 * (m.TotalPhys - m.AvailPhys) / Math.Max(1, m.TotalPhys));
            }
            if (!gpuDead) SampleGpu();
        }

        // загрузка ГП как в диспетчере задач: сумма по процессам на каждом движке, берётся самый занятый движок
        static void SampleGpu()
        {
            try
            {
                var cat = new PerformanceCounterCategory("GPU Engine");
                var all = cat.ReadCategory();
                InstanceDataCollection col = null;
                foreach (DictionaryEntry de in all)
                {
                    string key = ((string)de.Key).ToLowerInvariant();
                    if (key.Contains("utiliz") || key.Contains("использ")) { col = (InstanceDataCollection)de.Value; break; }
                }
                if (col == null) { gpuDead = true; return; }
                var cur = new Dictionary<string, CounterSample>();
                foreach (InstanceData d in col.Values) cur[d.InstanceName] = d.Sample;
                if (prevGpu != null)
                {
                    var eng = new Dictionary<string, double>();
                    foreach (var kv in cur)
                    {
                        CounterSample old;
                        if (!prevGpu.TryGetValue(kv.Key, out old)) continue;
                        int e = kv.Key.IndexOf("_luid_");
                        string engine = e >= 0 ? kv.Key.Substring(e) : kv.Key;   // без pid — один движок
                        double v = CounterSample.Calculate(old, kv.Value);
                        if (double.IsNaN(v) || v < 0) continue;
                        double acc; eng.TryGetValue(engine, out acc); eng[engine] = acc + v;
                    }
                    Gpu = eng.Count > 0 ? (float)Math.Min(100, eng.Values.Max()) : 0;
                }
                prevGpu = cur;
            }
            catch { gpuDead = true; }   // старая Windows или нет счётчиков — ГП не показываем
        }
    }

    class MachineGauge : CrtControl
    {
        float sc, sr, sg;   // сглаженные значения
        readonly System.Windows.Forms.Timer tm;

        public MachineGauge()
        {
            tm = new System.Windows.Forms.Timer { Interval = 60 };
            tm.Tick += (s, e) =>
            {
                if (!Visible || FindForm() == null || FindForm().WindowState == FormWindowState.Minimized) return;
                bool ch = false;
                Func<float, float, float> ease = (cur, tgt) => { if (tgt < 0) return cur; float n = cur + (tgt - cur) * 0.18f; if (Math.Abs(n - cur) > 0.05f) ch = true; return n; };
                sc = ease(sc, SysMon.Cpu); sr = ease(sr, SysMon.Ram); sg = ease(sg, SysMon.Gpu);
                if (ch) Invalidate();
            };
            tm.Start();
            SysMon.Start();
        }

        protected override void PaintContent(Graphics g)
        {
            var r = new RectangleF(2, 2, Width - 5, Height - 5);
            Theme.Box(g, r, Theme.GreenDim, 1.2f);
            Theme.Line(g, Theme.Orange, r.X, r.Y, r.X + 8, r.Y, 1.6f); Theme.Line(g, Theme.Orange, r.X, r.Y, r.X, r.Y + 8, 1.6f);
            Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right - 8, r.Bottom, 1.6f); Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right, r.Bottom - 8, 1.6f);
            Theme.Glow(g, Loc.T("ЭТА ЕДИНИЦА"), Theme.Mono(9f, FontStyle.Bold), Theme.Orange, 14, 9);
            var rows = new[]
            {
                new object[] { Loc.T("ЦП"), sc, SysMon.Cpu >= 0, null },
                new object[] { Loc.T("ОЗУ"), sr, SysMon.Ram >= 0, SysMon.RamTotalGb > 0 ? SysMon.RamUsedGb.ToString("0.0", CultureInfo.InvariantCulture) + "/" + Math.Round(SysMon.RamTotalGb) + Loc.T(" ГБ") : null },
                new object[] { Loc.T("ГП"), sg, SysMon.Gpu >= 0, null }
            };
            var lf = Theme.Mono(8.5f, FontStyle.Bold);
            float y = 32, rowH = (Height - 40) / 3f;
            foreach (var row in rows)
            {
                string name = (string)row[0]; float v = (float)row[1]; bool have = (bool)row[2]; string extra = (string)row[3];
                using (var b = new SolidBrush(Theme.GreenMid)) g.DrawString(name, lf, b, 14, y + rowH / 2 - 8);
                float bx = 52, bw = Width - 52 - 112, bh = 10, byy = y + rowH / 2 - 5;
                int cells = 20;
                float cw = bw / cells;
                int lit = have ? (int)Math.Round(Math.Max(0, Math.Min(100, v)) / 100f * cells) : 0;
                for (int i = 0; i < cells; i++)
                {
                    Color c = i < lit ? (i >= cells * 0.85f ? Theme.Red : i >= cells * 0.6f ? Theme.Amber : Theme.Green) : Color.FromArgb(40, Theme.GreenDim);
                    using (var b = new SolidBrush(c)) g.FillRectangle(b, bx + i * cw, byy, cw - 2, bh);
                }
                string val = have ? Math.Round(v) + "%" : "—";
                Color vc = !have ? Theme.GreenDim : v >= 85 ? Theme.Red : v >= 60 ? Theme.Amber : Theme.Green;
                Theme.Glow(g, val, Theme.Mono(9.5f, FontStyle.Bold), vc, new RectangleF(Width - 110, y + rowH / 2 - 9, 44, 18), Theme.Right);
                if (extra != null) using (var b = new SolidBrush(Theme.GreenDim)) g.DrawString(extra, Theme.Mono(7.5f, FontStyle.Regular), b, new RectangleF(Width - 64, y + rowH / 2 - 7, 60, 14));
                y += rowH;
            }
        }
    }

    // ============================== ЛУЧ ОБНОВЛЕНИЯ ==============================
    // тонкая полоса проходит сверху вниз — как кадровая развёртка; под ней картинка чуть увеличена, как под линзой.
    // Это не украшение: луч проходит после каждого опроса связи и несёт его показание и цвет состояния.
    class ScanBeam : Control
    {
        public Bitmap Shot;
        public float Cy;
        public Color Col = Theme.Green;
        public string Reading;
        public const int H = 30;

        public ScanBeam() { SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint, true); }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            if (Shot == null) return;
            g.InterpolationMode = InterpolationMode.Bilinear;
            g.PixelOffsetMode = PixelOffsetMode.HighSpeed;
            // линза: полоса высотой 0.72·H растянута на H, по ширине — на 1.5%
            float sh = H * 0.72f, sw = Width * 0.985f;
            var src = new RectangleF((Width - sw) / 2, Cy - sh / 2, sw, sh);
            g.DrawImage(Shot, new RectangleF(0, 0, Width, H), src, GraphicsUnit.Pixel);
            using (var lb = new LinearGradientBrush(new RectangleF(0, 0, Width, H), Color.FromArgb(0, Col), Color.FromArgb(34, Col), 90f))
            {
                lb.SetBlendTriangularShape(0.5f);
                g.FillRectangle(lb, 0, 0, Width, H);
            }
            using (var pen = new Pen(Color.FromArgb(26, Col), 3f)) g.DrawLine(pen, 0, H / 2f, Width, H / 2f);
            using (var pen = new Pen(Color.FromArgb(120, Col), 1f)) g.DrawLine(pen, 0, H / 2f, Width, H / 2f);
            // края линзы — едва заметные кромки
            using (var pen = new Pen(Color.FromArgb(22, Col), 1f)) { g.DrawLine(pen, 0, 0, Width, 0); g.DrawLine(pen, 0, H - 1, Width, H - 1); }
            if (!string.IsNullOrEmpty(Reading))
            {
                var f = Theme.Mono(7.5f, FontStyle.Bold);
                var sz = g.MeasureString(Reading, f);
                var r = new RectangleF(Width - sz.Width - 30, H / 2f - sz.Height / 2 - 1, sz.Width + 12, sz.Height + 2);
                using (var b = new SolidBrush(Color.FromArgb(200, Theme.Bg))) g.FillRectangle(b, r);
                using (var pen = new Pen(Color.FromArgb(150, Col), 1f)) g.DrawRectangle(pen, r.X, r.Y, r.Width, r.Height);
                using (var b = new SolidBrush(Color.FromArgb(220, Col))) g.DrawString(Reading, f, b, r.X + 6, r.Y + 1);
            }
        }
    }

    // ============================== ОЖИВЛЕНИЕ ОПРОСА В СПИСКАХ ==============================
    // 1) по опрашиваемой строке бежит блик; 2) итог печатается посимвольно; 3) итоги раскрываются по очереди сверху вниз
    class RowFx
    {
        class Fx { public bool Probing, Queued; public DateTime Start; public string Text; public Color C; public int Shown; public DateTime Flash = DateTime.MinValue; }
        readonly Dictionary<object, Fx> map = new Dictionary<object, Fx>();
        readonly List<object> reveal = new List<object>();
        DateTime nextReveal = DateTime.MinValue;
        readonly System.Windows.Forms.Timer t;
        readonly ListBox owner;
        readonly Func<object, int> order;
        readonly DrawItemEventHandler draw;
        int tick;

        public RowFx(ListBox list, Func<object, int> orderOf, DrawItemEventHandler drawItem)
        {
            owner = list; order = orderOf; draw = drawItem;
            t = new System.Windows.Forms.Timer { Interval = 30 };
            t.Tick += (s, e) => Step();
        }

        Fx Get(object o) { Fx f; if (!map.TryGetValue(o, out f)) { f = new Fx(); map[o] = f; } return f; }

        public void Queue(object o) { var f = Get(o); f.Queued = true; f.Probing = false; f.Text = null; Wake(); }
        public void Probe(object o) { var f = Get(o); f.Queued = false; f.Probing = true; f.Start = DateTime.Now; f.Text = null; Wake(); }
        public void Result(object o, string text, Color c)
        {
            var f = Get(o); f.Text = text; f.C = c; f.Shown = -1;   // -1 — ждёт своей очереди на раскрытие
            if (!reveal.Contains(o)) reveal.Add(o);
            Wake();
        }

        void Wake() { if (!t.Enabled) t.Start(); RepaintRows(); }

        void Step()
        {
            tick++;
            if (reveal.Count > 0 && DateTime.Now >= nextReveal)
            {
                // сверху вниз: первым раскрывается тот, что выше в списке
                var o = reveal.OrderBy(x => order(x)).First();
                reveal.Remove(o);
                var f = Get(o); f.Probing = false; f.Queued = false; f.Shown = 0; f.Flash = DateTime.Now;
                nextReveal = DateTime.Now.AddMilliseconds(170);
            }
            bool busy = reveal.Count > 0;
            foreach (var f in map.Values)
            {
                if (f.Text != null && f.Shown >= 0 && f.Shown < f.Text.Length) { f.Shown = Math.Min(f.Text.Length, f.Shown + 2 + (tick % 4 == 0 ? 0 : 1)); busy = true; }
                if (f.Probing || f.Queued || (DateTime.Now - f.Flash).TotalMilliseconds < 700) busy = true;
            }
            RepaintRows();
            if (!busy) { t.Stop(); RepaintRows(); }
        }

        // перерисовка только анимируемых строк — через буфер, прямо на экран, без стирания фона (ListBox иначе мерцает)
        void RepaintRows()
        {
            if (!owner.IsHandleCreated || !owner.Visible) return;
            try
            {
                using (var screen = owner.CreateGraphics())
                    foreach (var o in map.Keys.ToList())
                    {
                        int i = order(o);
                        if (i < 0 || i >= owner.Items.Count) continue;
                        var r = owner.GetItemRectangle(i);
                        if (r.Bottom < 0 || r.Top > owner.ClientSize.Height || r.Width <= 0 || r.Height <= 0) continue;
                        using (var bmp = new Bitmap(r.Width, r.Height))
                        using (var bg = Graphics.FromImage(bmp))
                        {
                            bg.Clear(owner.BackColor);
                            bg.TranslateTransform(-r.X, -r.Y);
                            var st = owner.SelectedIndex == i ? DrawItemState.Selected : DrawItemState.None;
                            draw(owner, new DrawItemEventArgs(bg, owner.Font, r, i, st));
                            screen.DrawImageUnscaled(bmp, r.X, r.Y);
                        }
                    }
            }
            catch { owner.Invalidate(); }
        }

        // рисует статус строки; возвращает false, если строку не трогали (тогда рисуется обычный статус)
        public bool Draw(Graphics g, object o, Rectangle row, RectangleF status, Font f, StringFormat sf)
        {
            Fx x;
            if (!map.TryGetValue(o, out x)) return false;
            double flash = (DateTime.Now - x.Flash).TotalMilliseconds;
            if (flash < 700 && x.Text != null)
                using (var b = new SolidBrush(Color.FromArgb((int)(70 * (1 - flash / 700)), x.C))) g.FillRectangle(b, row.X + 2, row.Y + 2, row.Width - 4, row.Height - 4);
            if (x.Probing || (x.Text != null && x.Shown < 0))
            {
                // блик бежит по строке
                float ph = (float)((DateTime.Now - x.Start).TotalMilliseconds % 1400 / 1400.0);
                float bw = 90, bx = row.X - bw + (row.Width + bw) * ph;
                var br = new RectangleF(bx, row.Y + 2, bw, row.Height - 4);
                using (var lg = new LinearGradientBrush(new RectangleF(br.X - 1, br.Y, br.Width + 2, br.Height), Color.FromArgb(0, Theme.Green), Color.FromArgb(46, Theme.Green), LinearGradientMode.Horizontal))
                { lg.SetBlendTriangularShape(0.7f); g.FillRectangle(lg, br); }
                int cells = 3, lit = (int)((DateTime.Now - x.Start).TotalMilliseconds / 260) % (cells + 1);
                string bar = ""; for (int i = 0; i < cells; i++) bar += i < lit ? "▮" : "▯";
                using (var b = new SolidBrush(Theme.Orange)) g.DrawString(Loc.T("ОПРОС ") + bar, f, b, status, sf);
                return true;
            }
            if (x.Queued)
            {
                using (var b = new SolidBrush(Theme.GreenDim)) g.DrawString(Loc.T("В ОЧЕРЕДИ"), f, b, status, sf);
                return true;
            }
            if (x.Text != null)
            {
                bool typing = x.Shown < x.Text.Length;
                string vis = x.Text.Substring(0, Math.Max(0, x.Shown)) + (typing && tick % 6 < 4 ? "█" : "");
                // печать справа налево выглядит дёргано — при выравнивании вправо держим место под весь текст
                if (sf.Alignment == StringAlignment.Far && typing) vis = vis.PadRight(x.Text.Length + 1);
                using (var b = new SolidBrush(x.C)) g.DrawString(vis, f, b, status, sf);
                return true;
            }
            return false;
        }

        public Color? BarColor(object o)
        {
            Fx x;
            if (!map.TryGetValue(o, out x)) return null;
            if (x.Probing || x.Queued || (x.Text != null && x.Shown < 0)) return Theme.Orange;
            return null;
        }
    }

    // ============================== СОНАР ==============================
    // лёгкая трассировка раз в 25 с: по одному пакету на прыжок до 1.1.1.1. Только пока открыты «Испытания».
    class SonarHop { public int Ttl; public string Addr, Asn, AsName; public List<double> Hist = new List<double>(); }
    static class SonarProbe
    {
        public static readonly object Lk = new object();
        public static List<SonarHop> Hops = new List<SonarHop>();
        public static int Reach = -1;          // на каком прыжке ответила цель
        public static DateTime Last = DateTime.MinValue;
        public static bool Tunnel;
        public static volatile bool Want;      // страница видна
        static Thread th;
        public const string Target = "1.1.1.1";

        public static void Start()
        {
            if (th != null) return;
            th = new Thread(() =>
            {
                while (true)
                {
                    try { if (Want && (DateTime.Now - Last).TotalSeconds >= 25) Sweep(); } catch { }
                    Thread.Sleep(1000);
                }
            }) { IsBackground = true, Priority = ThreadPriority.BelowNormal };
            th.Start();
        }

        static void Sweep()
        {
            Tunnel = Tun.Find(Store.Pattern) != null;
            int maxTtl = Reach > 0 ? Math.Min(16, Reach) : 16;
            var buf = new byte[32];
            int reached = -1, silentRun = 0;
            using (var p = new Ping())
                for (int ttl = 1; ttl <= maxTtl; ttl++)
                {
                    string addr = null; double rtt = -1;
                    var sw = Stopwatch.StartNew();
                    try
                    {
                        var r = p.Send(Target, 800, buf, new PingOptions(ttl, true));
                        if (r.Status == IPStatus.Success || r.Status == IPStatus.TtlExpired || r.Status == IPStatus.TimeExceeded)
                        { addr = r.Address != null ? r.Address.ToString() : null; rtt = r.Status == IPStatus.Success && r.RoundtripTime > 0 ? r.RoundtripTime : sw.ElapsedMilliseconds; }
                        if (r.Status == IPStatus.Success) reached = ttl;
                    }
                    catch { }
                    lock (Lk)
                    {
                        while (Hops.Count < ttl) Hops.Add(new SonarHop { Ttl = Hops.Count + 1 });
                        var h = Hops[ttl - 1];
                        if (addr != null && addr != h.Addr) { h.Addr = addr; h.Asn = Diag.AsnOf(addr); h.AsName = Diag.AsName(h.Asn); }
                        h.Hist.Add(rtt); if (h.Hist.Count > 8) h.Hist.RemoveAt(0);
                    }
                    if (reached > 0) break;
                    silentRun = addr == null ? silentRun + 1 : 0;
                    if (Reach < 0 && silentRun >= 4 && ttl > 6) break;   // дальше тишина — нет смысла ждать
                }
            lock (Lk)
            {
                if (reached > 0) { Reach = reached; if (Hops.Count > reached) Hops.RemoveRange(reached, Hops.Count - reached); }
                else Reach = -1;
            }
            Last = DateTime.Now;
        }
    }

    // ============================== СБОИ РАЗВЁРТКИ ==============================
    // изредка картинка дёргается по горизонтали полосами — как старый кинескоп, теряющий синхронизацию
    class GlitchOverlay : Control
    {
        public Bitmap Shot;
        public int Frame;
        readonly Random rnd = new Random();
        int[] bandY, bandH, bandDx;

        public GlitchOverlay() { SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint, true); }

        public void Roll()
        {
            int n = Frame == 0 ? rnd.Next(2, 5) : rnd.Next(1, 3);
            bandY = new int[n]; bandH = new int[n]; bandDx = new int[n];
            for (int i = 0; i < n; i++)
            {
                bandH[i] = rnd.Next(4, Math.Max(6, Height / 9));
                bandY[i] = rnd.Next(0, Math.Max(1, Height - bandH[i]));
                int mag = Frame == 0 ? rnd.Next(5, 18) : rnd.Next(2, 8);
                bandDx[i] = rnd.Next(2) == 0 ? -mag : mag;
            }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            if (Shot == null) return;
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            int whole = Frame == 1 ? (rnd.Next(2) == 0 ? -2 : 2) : 0;   // на втором кадре чуть сдвигается всё
            g.DrawImageUnscaled(Shot, whole, 0);
            if (bandY == null) return;
            for (int i = 0; i < bandY.Length; i++)
            {
                var src = new Rectangle(0, bandY[i], Shot.Width, bandH[i]);
                g.DrawImage(Shot, new Rectangle(bandDx[i], bandY[i], Shot.Width, bandH[i]), src, GraphicsUnit.Pixel);
                // разрыв строки — тонкий цветной срез по краю полосы
                using (var b = new SolidBrush(Color.FromArgb(70, bandDx[i] > 0 ? Theme.Green : Theme.Orange))) g.FillRectangle(b, 0, bandY[i], Shot.Width, 1);
                if (bandDx[i] > 0) using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, 0, bandY[i], bandDx[i], bandH[i]);
                else using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, Shot.Width + bandDx[i], bandY[i], -bandDx[i], bandH[i]);
            }
        }
    }

    // ---------- занавес перехода между страницами ----------
    class Transition : Control
    {
        public float Open, Progress, Angle;
        public string Label = "";
        Region region;

        public Transition()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
            BackColor = Theme.Bg;
        }

        // видимая часть — только раскрытый контейнер; снаружи остаётся страница
        public void Apply()
        {
            int w = (int)Math.Round(Width * Math.Max(0f, Math.Min(1f, Open)));
            int x = (Width - w) / 2;
            var old = region;
            region = new Region(new Rectangle(x, 0, Math.Max(w, 0), Height));
            Region = region;
            if (old != null) old.Dispose();
            Invalidate();
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            Theme.Prep(g);
            var r = ClientRectangle;
            using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, r);

            float w = r.Width * Math.Max(0f, Math.Min(1f, Open));
            float x0 = (r.Width - w) / 2f, x1 = x0 + w;

            // свечение кромок раскрывающегося контейнера
            for (int i = 0; i < 4; i++)
            {
                using (var pen = new Pen(Color.FromArgb(70 - i * 15, Theme.Green), 6 - i))
                {
                    g.DrawLine(pen, x0 + 3 + i * 2, 0, x0 + 3 + i * 2, r.Height);
                    g.DrawLine(pen, x1 - 4 - i * 2, 0, x1 - 4 - i * 2, r.Height);
                }
            }
            Theme.Line(g, Theme.Green, x0 + 2, 0, x0 + 2, r.Height, 2f);
            Theme.Line(g, Theme.Green, x1 - 3, 0, x1 - 3, r.Height, 2f);
            Theme.Line(g, Theme.GreenDim, x0 + 9, 0, x0 + 9, r.Height, 1f);
            Theme.Line(g, Theme.GreenDim, x1 - 10, 0, x1 - 10, r.Height, 1f);
            // оранжевые скобы на кромках
            float cy = r.Height / 2f;
            foreach (float ex in new[] { x0 + 2, x1 - 3 })
            {
                float dir = ex < r.Width / 2f ? 1 : -1;
                Theme.Line(g, Theme.Orange, ex, cy - 60, ex + 16 * dir, cy - 60, 2f);
                Theme.Line(g, Theme.Orange, ex, cy + 60, ex + 16 * dir, cy + 60, 2f);
                Theme.Line(g, Theme.Orange, ex + 16 * dir, cy - 60, ex + 16 * dir, cy - 48, 2f);
                Theme.Line(g, Theme.Orange, ex + 16 * dir, cy + 60, ex + 16 * dir, cy + 48, 2f);
            }

            // шестерни и надписи в центре
            var c = new PointF(r.Width / 2f, cy - 30);
            float ro = 46, ri = ro * 0.78f;
            var big = Theme.CogPoints(c, ro, ri, 12, Angle);
            using (var b = new SolidBrush(Color.FromArgb(40, Theme.Orange))) g.FillPolygon(b, big);
            using (var pen = new Pen(Color.FromArgb(50, Theme.Orange), 6f)) g.DrawPolygon(pen, big);
            using (var pen = new Pen(Theme.Orange, 2f)) g.DrawPolygon(pen, big);
            float h = ri * 0.5f;
            using (var pen = new Pen(Theme.Orange, 2f)) g.DrawEllipse(pen, c.X - h, c.Y - h, h * 2, h * 2);
            using (var b = new SolidBrush(Theme.Red)) g.FillEllipse(b, c.X - h * 0.45f, c.Y - h * 0.45f, h * 0.9f, h * 0.9f);
            // малая шестерня в зацеплении
            var c2 = new PointF(c.X + ro + 18, c.Y - ro * 0.55f);
            var small = Theme.CogPoints(c2, 24, 18, 8, -Angle * 1.5f + 0.2f);
            using (var pen = new Pen(Color.FromArgb(50, Theme.GreenMid), 5f)) g.DrawPolygon(pen, small);
            using (var pen = new Pen(Theme.GreenMid, 1.6f)) g.DrawPolygon(pen, small);
            using (var pen = new Pen(Theme.GreenMid, 1.6f)) g.DrawEllipse(pen, c2.X - 6, c2.Y - 6, 12, 12);

            Theme.Glow(g, Loc.T("ПЕРЕХОД  ·  ") + Label, Theme.Title(13f), Theme.Orange, new RectangleF(0, cy + 34, r.Width, 26), Theme.Center);
            var bar = new RectangleF(r.Width / 2f - 160, cy + 72, 320, 14);
            Theme.Box(g, bar, Theme.GreenMid, 1.2f);
            int cells = 24;
            float cw = (bar.Width - 6) / cells;
            int filled = (int)Math.Round(cells * Math.Max(0f, Math.Min(1f, Progress)));
            using (var b = new SolidBrush(Theme.Green))
                for (int i = 0; i < filled; i++) g.FillRectangle(b, bar.X + 3 + i * cw, bar.Y + 3, cw - 2, bar.Height - 6);
            using (var b = new SolidBrush(Theme.GreenDim))
                g.DrawString(Loc.T("СИНХРОНИЗАЦИЯ МАШИННОГО ДУХА"), Theme.Mono(8.5f, FontStyle.Bold), b, new RectangleF(0, cy + 92, r.Width, 18), Theme.Center);
            Theme.Overlay(g, r, (int)(Angle * 40) % 160, (int)(Angle * 70) % 160);
        }
    }

    // ---------- своя полоса прокрутки ----------
    // Системная полоса остаётся живой (колесо, клавиши), но уезжает за край и обрезается;
    // рядом рисуется своя, синхронизированная с ней.
    class CrtScrollHost : Panel
    {
        [StructLayout(LayoutKind.Sequential)]
        struct SCROLLINFO { public int cbSize; public uint fMask; public int nMin, nMax; public uint nPage; public int nPos, nTrackPos; }
        [DllImport("user32.dll")] static extern bool GetScrollInfo(IntPtr hwnd, int bar, ref SCROLLINFO si);
        [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr hwnd, int msg, IntPtr w, ref Point p);

        public readonly Control Target;
        readonly Panel clip;
        readonly CrtScrollBar bar;
        const int BarW = 14, Gap = 4;

        public CrtScrollHost(Control target)
        {
            Target = target;
            BackColor = Theme.BgLog;
            Dock = DockStyle.Fill;
            clip = new Panel { BackColor = Theme.BgLog };
            target.Dock = DockStyle.None;
            target.Anchor = AnchorStyles.None;
            clip.Controls.Add(target);
            bar = new CrtScrollBar(this);
            Controls.Add(clip);
            Controls.Add(bar);
        }

        protected override void OnLayout(LayoutEventArgs e)
        {
            base.OnLayout(e);
            if (bar == null) return;
            int w = Math.Max(1, Width), h = Math.Max(1, Height);
            bar.SetBounds(w - BarW, 0, BarW, h);
            clip.SetBounds(0, 0, Math.Max(1, w - BarW - Gap), h);
            int sys = SystemInformation.VerticalScrollBarWidth;
            Target.SetBounds(0, 0, clip.Width + sys, h);
        }

        // min, max, page, pos
        public bool GetInfo(out int min, out int max, out int page, out int pos)
        {
            min = max = page = pos = 0;
            try
            {
                var si = new SCROLLINFO { cbSize = Marshal.SizeOf(typeof(SCROLLINFO)), fMask = 0x17 };
                if (Target.IsHandleCreated && GetScrollInfo(Target.Handle, 1, ref si))
                {
                    min = si.nMin; max = si.nMax; page = (int)si.nPage; pos = si.nPos;
                    return true;
                }
            }
            catch { }
            var lb = Target as ListBox;
            if (lb != null && lb.ItemHeight > 0)
            {
                min = 0; max = Math.Max(0, lb.Items.Count - 1); page = Math.Max(1, lb.ClientSize.Height / lb.ItemHeight); pos = lb.TopIndex;
                return true;
            }
            return false;
        }

        public void SetPos(int pos)
        {
            int min, max, page, cur;
            if (!GetInfo(out min, out max, out page, out cur)) return;
            pos = Math.Max(min, Math.Min(pos, Math.Max(min, max - page + 1)));
            var lb = Target as ListBox;
            if (lb != null) { try { lb.TopIndex = pos; } catch { } return; }
            var rt = Target as RichTextBox;
            if (rt != null)
            {
                try { var pt = new Point(0, pos); SendMessage(rt.Handle, 0x400 + 222, IntPtr.Zero, ref pt); } catch { }   // EM_SETSCROLLPOS
            }
        }

        public int WheelStep { get { return Target is ListBox ? 3 : Target.Font.Height * 3; } }
    }

    class CrtScrollBar : Control
    {
        readonly CrtScrollHost host;
        readonly System.Windows.Forms.Timer poll;
        int min, max, page, pos;
        bool hover, dragging; float dragOff;

        public CrtScrollBar(CrtScrollHost host)
        {
            this.host = host;
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
            BackColor = Theme.BgLog;
            poll = new System.Windows.Forms.Timer { Interval = 80 };
            poll.Tick += (s, e) => Sync();
        }

        protected override void OnVisibleChanged(EventArgs e) { base.OnVisibleChanged(e); poll.Enabled = Visible; }
        protected override void OnHandleCreated(EventArgs e) { base.OnHandleCreated(e); poll.Enabled = Visible; }
        protected override void Dispose(bool disposing) { if (disposing) poll.Dispose(); base.Dispose(disposing); }

        void Sync()
        {
            if (!Visible || dragging) return;
            int a, b, c, d;
            if (!host.GetInfo(out a, out b, out c, out d)) return;
            if (a != min || b != max || c != page || d != pos) { min = a; max = b; page = c; pos = d; Invalidate(); }
        }

        bool Scrollable { get { return page > 0 && max - min + 1 > page; } }
        RectangleF Track { get { return new RectangleF(2, 4, Width - 4, Height - 8); } }

        RectangleF Thumb
        {
            get
            {
                var t = Track;
                int range = max - min + 1;
                float th = Math.Max(26, t.Height * page / Math.Max(1, range));
                float frac = range - page > 0 ? (pos - min) / (float)(range - page) : 0;
                return new RectangleF(t.X, t.Y + (t.Height - th) * Math.Max(0, Math.Min(1, frac)), t.Width, th);
            }
        }

        protected override void OnMouseEnter(EventArgs e) { hover = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = false; Invalidate(); base.OnMouseLeave(e); }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (!Scrollable || e.Button != MouseButtons.Left) return;
            var th = Thumb;
            if (th.Contains(e.Location)) { dragging = true; dragOff = e.Y - th.Y; Capture = true; }
            else { host.SetPos(e.Y < th.Y ? pos - page : pos + page); Sync(); }
            Invalidate();
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            if (!dragging) return;
            var t = Track; var th = Thumb;
            int range = max - min + 1;
            float frac = (e.Y - dragOff - t.Y) / Math.Max(1f, t.Height - th.Height);
            pos = min + (int)Math.Round(Math.Max(0, Math.Min(1, frac)) * (range - page));
            host.SetPos(pos);
            Invalidate();
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            if (dragging) { dragging = false; Capture = false; Sync(); Invalidate(); }
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            base.OnMouseWheel(e);
            if (!Scrollable) return;
            host.SetPos(pos - Math.Sign(e.Delta) * host.WheelStep);
            Sync();
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            Theme.Prep(g);
            using (var b = new SolidBrush(Theme.BgLog)) g.FillRectangle(b, ClientRectangle);
            var t = Track;
            // рельс с делениями
            float cx = t.X + t.Width / 2;
            Theme.Line(g, Scrollable ? Theme.GreenDim : Color.FromArgb(24, 60, 32), cx, t.Y, cx, t.Bottom, 1f);
            using (var p = new Pen(Color.FromArgb(Scrollable ? 70 : 30, Theme.GreenDim), 1f))
                for (float y = t.Y; y <= t.Bottom; y += 12) g.DrawLine(p, cx - 3, y, cx + 3, y);
            if (!Scrollable) return;
            var th = Thumb;
            bool hot = hover || dragging;
            using (var b = new SolidBrush(hot ? Color.FromArgb(22, 72, 34) : Theme.GreenDark)) g.FillRectangle(b, th);
            Theme.Box(g, th, hot ? Theme.Green : Theme.GreenMid, 1.3f);
            // оранжевые засечки на концах бегунка и рифление посередине
            Theme.Line(g, Theme.Orange, th.X + 2, th.Y + 3, th.Right - 2, th.Y + 3, 1.4f);
            Theme.Line(g, Theme.Orange, th.X + 2, th.Bottom - 3, th.Right - 2, th.Bottom - 3, 1.4f);
            float my = th.Y + th.Height / 2;
            using (var p = new Pen(hot ? Theme.Green : Theme.GreenMid, 1f))
                for (int i = -1; i <= 1; i++) g.DrawLine(p, th.X + 3, my + i * 3, th.Right - 3, my + i * 3);
        }
    }

    // ---------- тёмные списки ----------
    static class Ui
    {
        public static void DarkScroll(Control c)
        {
            c.HandleCreated += (s, e) => { try { MainForm.SetTheme(c.Handle); } catch { } };
        }

        public static void Buffer(Control c)
        {
            try { typeof(Control).GetProperty("DoubleBuffered", BindingFlags.NonPublic | BindingFlags.Instance).SetValue(c, true, null); } catch { }
        }

        public static ListBox MakeList(int itemHeight)
        {
            var lb = new ListBox
            {
                Dock = DockStyle.Fill, BorderStyle = BorderStyle.None, BackColor = Theme.BgLog, ForeColor = Theme.Green,
                DrawMode = DrawMode.OwnerDrawFixed, ItemHeight = itemHeight, IntegralHeight = false, ScrollAlwaysVisible = true, Font = Theme.Mono(10f, FontStyle.Regular)
            };
            Buffer(lb);
            DarkScroll(lb);
            return lb;
        }

        public static RichTextBox MakeLog()
        {
            var log = new RichTextBox
            {
                Dock = DockStyle.Fill, ReadOnly = true, BorderStyle = BorderStyle.None, BackColor = Theme.BgLog,
                ForeColor = Theme.Text, Font = Theme.Mono(9.5f, FontStyle.Regular), DetectUrls = false, WordWrap = true, ScrollBars = RichTextBoxScrollBars.ForcedVertical
            };
            DarkScroll(log);
            return log;
        }

        public static Label Caption(string t)
        {
            return new Label { Text = t, AutoSize = true, ForeColor = Theme.Orange, Font = Theme.Mono(8.5f, FontStyle.Bold), Margin = new Padding(0, 8, 0, 3), BackColor = Color.Transparent };
        }

        public static void ItemFrame(Graphics g, Rectangle b, bool sel)
        {
            using (var br = new SolidBrush(sel ? Theme.GreenDark : Theme.BgLog)) g.FillRectangle(br, b);
            if (sel) Theme.Box(g, new RectangleF(b.X + 1, b.Y + 1, b.Width - 3, b.Height - 3), Theme.Green, 1.2f);
            else using (var p = new Pen(Color.FromArgb(40, Theme.GreenDim))) g.DrawLine(p, b.X + 8, b.Bottom - 1, b.Right - 8, b.Bottom - 1);
        }

        public static StringFormat NoWrap = new StringFormat { Trimming = StringTrimming.EllipsisCharacter, FormatFlags = StringFormatFlags.NoWrap, LineAlignment = StringAlignment.Center };
        public static StringFormat NoWrapCenter = new StringFormat { Trimming = StringTrimming.EllipsisCharacter, FormatFlags = StringFormatFlags.NoWrap, LineAlignment = StringAlignment.Center, Alignment = StringAlignment.Center };
        public static StringFormat NoWrapRight = new StringFormat { Trimming = StringTrimming.EllipsisCharacter, FormatFlags = StringFormatFlags.NoWrap, LineAlignment = StringAlignment.Center, Alignment = StringAlignment.Far };
    }

    // ---------- выбор святилища ----------
    // ---------- выбор святилища: свой выпадающий список в стиле CRT ----------
    class SanctumPicker : CrtControl
    {
        public List<object> Items = new List<object>();
        public event EventHandler SelectedIndexChanged;
        int selected = -1;
        bool hover;
        PickerPopup popup;

        public SanctumPicker()
        {
            Height = 30;
            Cursor = Cursors.Hand;
            BackColor = Theme.BgLog;
        }

        public int SelectedIndex
        {
            get { return selected; }
            set
            {
                int v = (value >= -1 && value < Items.Count) ? value : -1;
                if (v == selected) return;
                selected = v;
                Invalidate();
                if (SelectedIndexChanged != null) SelectedIndexChanged(this, EventArgs.Empty);
            }
        }

        public object SelectedItem { get { return selected >= 0 && selected < Items.Count ? Items[selected] : null; } }

        public static string TextOf(object o)
        {
            var s = o as Sanctum;
            return s == null ? Loc.T("— БЕЗ СВЯТИЛИЩА —") : s.Name.ToUpperInvariant() + "  ·  " + s.Addr;
        }

        protected override void OnMouseEnter(EventArgs e) { hover = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnEnabledChanged(EventArgs e) { if (!Enabled) ClosePopup(); Cursor = Enabled ? Cursors.Hand : Cursors.Default; Invalidate(); base.OnEnabledChanged(e); }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Left) return;
            if (popup != null) ClosePopup(); else OpenPopup();
        }

        public bool IsOpen { get { return popup != null; } }

        void OpenPopup()
        {
            var form = FindForm();
            if (form == null || Items.Count == 0) return;
            popup = new PickerPopup(this);
            int rowH = 30, rows = Math.Min(Items.Count, 8);
            int h = rows * rowH + 8;
            var origin = form.PointToClient(Parent.PointToScreen(Location));
            int y = origin.Y + Height - 1;
            if (y + h > form.ClientSize.Height - 6) y = origin.Y - h + 1;   // не влезает вниз — раскрыть вверх
            int need = Width;
            var f = Theme.Mono(10f, FontStyle.Bold);
            foreach (var it in Items) need = Math.Max(need, TextRenderer.MeasureText(TextOf(it), f).Width + 44);
            need = Math.Min(need, form.ClientSize.Width - origin.X - 8);
            popup.SetBounds(origin.X, y, need, h);
            popup.RowHeight = rowH;
            form.Controls.Add(popup);
            popup.BringToFront();
            Invalidate();
        }

        public void ClosePopup()
        {
            if (popup == null) return;
            var p = popup; popup = null;
            p.Detach();
            if (p.Parent != null) p.Parent.Controls.Remove(p);
            p.Dispose();
            Invalidate();
        }

        public void Choose(int i) { ClosePopup(); SelectedIndex = i; }

        protected override void PaintContent(Graphics g)
        {
            bool en = Enabled;
            var r = new RectangleF(1, 1, Width - 3, Height - 3);
            if (en && (hover || popup != null)) using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, r);
            Theme.Box(g, r, !en ? Theme.GreenDim : (hover || popup != null) ? Theme.Green : Theme.GreenMid, 1.4f);
            float aw = 30;
            Theme.Line(g, en ? Theme.GreenDim : Color.FromArgb(25, 60, 32), r.Right - aw, r.Y + 5, r.Right - aw, r.Bottom - 5, 1.2f);
            // шеврон
            float cx = r.Right - aw / 2, cy = r.Y + r.Height / 2;
            Color oc = en ? Theme.Orange : Theme.OrangeDim;
            if (popup == null) { Theme.Line(g, oc, cx - 5, cy - 2, cx, cy + 3, 1.8f); Theme.Line(g, oc, cx, cy + 3, cx + 5, cy - 2, 1.8f); }
            else { Theme.Line(g, oc, cx - 5, cy + 3, cx, cy - 2, 1.8f); Theme.Line(g, oc, cx, cy - 2, cx + 5, cy + 3, 1.8f); }
            var item = SelectedItem;
            Color tc = !en ? Theme.GreenDim : item is Sanctum ? Theme.Green : Theme.GreenDim;
            var font = Theme.Mono(10f, FontStyle.Bold);
            float avail = r.Width - aw - 12;
            string txt = TextOf(item);
            var sItem = item as Sanctum;
            if (sItem != null && g.MeasureString(txt, font).Width > avail) txt = sItem.Name.ToUpperInvariant();   // не влезает — только имя
            using (var b = new SolidBrush(tc))
                g.DrawString(txt, font, b, new RectangleF(r.X + 8, r.Y, avail, r.Height), Ui.NoWrap);
        }
    }

    class PickerPopup : CrtControl, IMessageFilter
    {
        readonly SanctumPicker owner;
        public int RowHeight = 30;
        int hover = -1, scroll;
        bool attached;

        public PickerPopup(SanctumPicker owner)
        {
            this.owner = owner;
            BackColor = Theme.BgLog;
            Cursor = Cursors.Hand;
            Application.AddMessageFilter(this);
            attached = true;
        }

        public void Detach()
        {
            if (attached) { Application.RemoveMessageFilter(this); attached = false; }
        }

        protected override void Dispose(bool disposing) { Detach(); base.Dispose(disposing); }

        int Rows { get { return Math.Max(1, (Height - 8) / RowHeight); } }

        // клик мимо списка, Esc или колесо — закрыть / прокрутить
        public bool PreFilterMessage(ref Message m)
        {
            const int WM_LBUTTONDOWN = 0x201, WM_RBUTTONDOWN = 0x204, WM_NCLBUTTONDOWN = 0xA1, WM_KEYDOWN = 0x100, WM_MOUSEWHEEL = 0x20A;
            if (m.Msg == WM_LBUTTONDOWN || m.Msg == WM_RBUTTONDOWN || m.Msg == WM_NCLBUTTONDOWN)
            {
                var pt = Cursor.Position;
                bool inPopup = RectangleToScreen(ClientRectangle).Contains(pt);
                bool inOwner = owner.RectangleToScreen(owner.ClientRectangle).Contains(pt);
                if (!inPopup && !inOwner) BeginInvoke(new Action(() => owner.ClosePopup()));
            }
            else if (m.Msg == WM_KEYDOWN && (int)m.WParam == 27) { BeginInvoke(new Action(() => owner.ClosePopup())); return true; }
            else if (m.Msg == WM_MOUSEWHEEL && RectangleToScreen(ClientRectangle).Contains(Cursor.Position))
            {
                int delta = (short)(((long)m.WParam >> 16) & 0xFFFF);
                int max = Math.Max(0, owner.Items.Count - Rows);
                scroll = Math.Max(0, Math.Min(max, scroll + (delta > 0 ? -1 : 1)));
                Invalidate();
                return true;
            }
            return false;
        }

        int IndexAt(Point p)
        {
            int i = (p.Y - 4) / RowHeight + scroll;
            return (p.Y >= 4 && i >= 0 && i < owner.Items.Count) ? i : -1;
        }

        protected override void OnMouseMove(MouseEventArgs e) { int h = IndexAt(e.Location); if (h != hover) { hover = h; Invalidate(); } base.OnMouseMove(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = -1; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseClick(MouseEventArgs e) { int i = IndexAt(e.Location); if (i >= 0) owner.Choose(i); base.OnMouseClick(e); }

        protected override void PaintContent(Graphics g)
        {
            var r = new RectangleF(1, 1, Width - 3, Height - 3);
            Theme.Box(g, r, Theme.Green, 1.4f);
            float k = 7;
            Theme.Line(g, Theme.Orange, r.X, r.Bottom, r.X + k, r.Bottom, 1.6f); Theme.Line(g, Theme.Orange, r.X, r.Bottom, r.X, r.Bottom - k, 1.6f);
            Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right - k, r.Bottom, 1.6f); Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right, r.Bottom - k, 1.6f);
            for (int row = 0; row < Rows; row++)
            {
                int i = row + scroll;
                if (i >= owner.Items.Count) break;
                var rr = new RectangleF(5, 4 + row * RowHeight, Width - 11, RowHeight - 2);
                bool sel = i == owner.SelectedIndex, hov = i == hover;
                if (hov) using (var b = new SolidBrush(Color.FromArgb(18, 60, 28))) g.FillRectangle(b, rr);
                else if (sel) using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, rr);
                if (hov) Theme.Box(g, rr, Theme.GreenMid, 1f);
                var it = owner.Items[i];
                if (sel) Theme.Glow(g, "»", Theme.Mono(10f, FontStyle.Bold), Theme.Orange, new RectangleF(rr.X + 4, rr.Y, 16, rr.Height), Theme.Left);
                using (var b = new SolidBrush(it is Sanctum ? (hov || sel ? Theme.Green : Theme.GreenMid) : Theme.GreenDim))
                    g.DrawString(SanctumPicker.TextOf(it), Theme.Mono(10f, FontStyle.Bold), b, new RectangleF(rr.X + 22, rr.Y, rr.Width - 28, rr.Height), Ui.NoWrap);
            }
            if (owner.Items.Count > Rows)
                using (var b = new SolidBrush(Theme.GreenDim))
                    g.DrawString((scroll + 1) + "–" + Math.Min(owner.Items.Count, scroll + Rows) + " / " + owner.Items.Count, Theme.Mono(7.5f, FontStyle.Regular), b, new RectangleF(0, Height - 14, Width - 8, 12), Ui.NoWrapRight);
        }
    }

    // ============================== СВОДКА ЛЕТОПИСИ ==============================
    class SummaryPanel : CrtControl
    {
        int period;
        static readonly string[] Periods = { Loc.T("СЕГОДНЯ"), Loc.T("7 ДНЕЙ"), Loc.T("ВСЁ ВРЕМЯ") };
        static readonly string[] RNums = { "", "I", "II", "III", "IV", "V" };
        DateTime from, to;
        List<ChronEntry> verdicts = new List<ChronEntry>();
        List<AxMin> ax = new List<AxMin>();
        List<ChronEntry> tests = new List<ChronEntry>(), withLoss = new List<ChronEntry>(), vpnOffs = new List<ChronEntry>();
        List<KeyValuePair<DateTime, DateTime>> bands = new List<KeyValuePair<DateTime, DateTime>>();
        double[] hourLoss = new double[24]; int[] hourCnt = new int[24];
        int nRed, nAmber, nGreen, nOut, worstHour = -1, minCnt = 1;
        double downSec, avgLoss = -1;
        List<KeyValuePair<string, Color>> findings = new List<KeyValuePair<string, Color>>();

        class Hit { public RectangleF R; public string[] Lines; public Color C; public int Pri, Shape; public PointF Ctr; public float Rad; }   // Shape: 0 — без подсветки, 1 — круг, 2 — ромб, 3 — заливка R
        List<Hit> hits = new List<Hit>();
        RectangleF[] chips = new RectangleF[3];
        RectangleF[] modeChips = new RectangleF[2];
        int chartMode;
        RectangleF chartRect;
        Bitmap beamOld; Stopwatch beamClock; System.Windows.Forms.Timer beamTimer;
        const int BeamMs = 520;

        // луч осциллографа проходит слева направо и прописывает новый график; старый гаснет перед ним
        void SwitchChart(int mode)
        {
            try
            {
                if (beamOld != null) { beamOld.Dispose(); beamOld = null; }
                var full = new Bitmap(Width, Height);
                DrawToBitmap(full, new Rectangle(0, 0, Width, Height));
                var r = Rectangle.Round(chartRect);
                r.Intersect(new Rectangle(0, 0, Width, Height));
                if (r.Width > 0 && r.Height > 0) beamOld = full.Clone(r, full.PixelFormat);
                full.Dispose();
            }
            catch { beamOld = null; }
            chartMode = mode;
            beamClock = Stopwatch.StartNew();
            if (beamTimer == null) { beamTimer = new System.Windows.Forms.Timer { Interval = 15 }; beamTimer.Tick += (s, e) => { Invalidate(Rectangle.Inflate(Rectangle.Round(chartRect), 4, 14)); if (beamClock == null || beamClock.ElapsedMilliseconds > BeamMs + 40) { beamTimer.Stop(); beamClock = null; if (beamOld != null) { beamOld.Dispose(); beamOld = null; } Invalidate(); } }; }
            beamTimer.Start();
            Invalidate();
        }

        void PaintBeam(Graphics g, RectangleF box)
        {
            if (beamClock == null) return;
            float t = Math.Min(1f, beamClock.ElapsedMilliseconds / (float)BeamMs);
            float e = 1 - (1 - t) * (1 - t);   // быстрее на старте, мягко к концу
            var inner = new RectangleF(box.X + 2, box.Y + 12, box.Width - 4, box.Height - 14);
            float bx = inner.X + inner.Width * e;
            // ещё не прописанная часть: старый график гаснет
            var rest = new RectangleF(bx, inner.Y, inner.Right - bx, inner.Height);
            if (rest.Width > 0)
            {
                var st = g.Save();
                g.SetClip(rest);
                using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, rest);
                if (beamOld != null)
                {
                    var cm = new ColorMatrix { Matrix33 = Math.Max(0, 0.75f - t * 0.9f) };
                    using (var ia = new ImageAttributes()) { ia.SetColorMatrix(cm); g.DrawImage(beamOld, new Rectangle((int)box.X, (int)box.Y, beamOld.Width, beamOld.Height), 0, 0, beamOld.Width, beamOld.Height, GraphicsUnit.Pixel, ia); }
                }
                g.Restore(st);
            }
            // шлейф и сам луч
            float tail = Math.Min(60, bx - inner.X);
            if (tail > 1)
                using (var lg = new LinearGradientBrush(new RectangleF(bx - tail - 1, inner.Y, tail + 1, inner.Height), Color.FromArgb(0, Theme.Green), Color.FromArgb(70, Theme.Green), LinearGradientMode.Horizontal))
                    g.FillRectangle(lg, bx - tail, inner.Y, tail, inner.Height);
            using (var pen = new Pen(Color.FromArgb(90, Theme.Green), 6f)) g.DrawLine(pen, bx, inner.Y, bx, inner.Bottom);
            using (var pen = new Pen(Color.FromArgb(240, 220, 255, 225), 1.6f)) g.DrawLine(pen, bx, inner.Y, bx, inner.Bottom);
            Theme.Line(g, Theme.Orange, bx - 5, inner.Y, bx + 5, inner.Y, 1.6f);
            Theme.Line(g, Theme.Orange, bx - 5, inner.Bottom, bx + 5, inner.Bottom, 1.6f);
                // надпись о сверке — пока луч в начале пути
            if (t < 0.75f)
            {
                string cap = chartMode == 0 ? Loc.T("СВЕРКА ЛЕТОПИСИ…") : Loc.T("СЧИТЫВАНИЕ ДНЕВНИКА АУСПИКА…");
                int a = (int)(255 * Math.Min(1, (0.75f - t) / 0.25f));
                var cf = Theme.Mono(10f, FontStyle.Bold);
                var sz = g.MeasureString(cap, cf);
                float cx = inner.X + (inner.Width - sz.Width) / 2, cy = inner.Y + (inner.Height - sz.Height) / 2;
                var cb = new RectangleF(cx - 14, cy - 6, sz.Width + 28, sz.Height + 12);
                using (var b = new SolidBrush(Color.FromArgb(a * 230 / 255, Theme.Bg))) g.FillRectangle(b, cb);
                using (var pen = new Pen(Color.FromArgb(a, Theme.Orange), 1.2f)) g.DrawRectangle(pen, cb.X, cb.Y, cb.Width, cb.Height);
                using (var b = new SolidBrush(Color.FromArgb(a, Theme.Orange))) g.DrawString(cap, cf, b, cx, cy);
            }
        }
        static readonly string[] ChartModes = { Loc.T("ИСПЫТАНИЯ"), Loc.T("ОКО АУСПИКА") };

        // переключатель графика — на верхней кромке рамки, справа
        void PaintChartSwitch(Graphics g, RectangleF box)
        {
            var lf = Theme.Mono(8.5f, FontStyle.Bold);
            float cx = box.Right - 12;
            for (int i = 1; i >= 0; i--)
            {
                float cw = g.MeasureString(ChartModes[i], lf).Width + 24;
                cx -= cw;
                modeChips[i] = new RectangleF(cx, box.Y - 10, cw, 20);
                cx -= 6;
                bool sel = i == chartMode, hov = modeChips[i].Contains(mouse);
                using (var b = new SolidBrush(sel ? Theme.GreenDark : Theme.Bg)) g.FillRectangle(b, modeChips[i]);
                Theme.Box(g, modeChips[i], sel ? Theme.Green : hov ? Theme.GreenMid : Theme.GreenDim, sel ? 1.4f : 1.1f);
                if (sel) Theme.Line(g, Theme.Orange, modeChips[i].X + 5, modeChips[i].Bottom - 3, modeChips[i].Right - 5, modeChips[i].Bottom - 3, 1.4f);
                Theme.Glow(g, ChartModes[i], lf, sel ? Theme.Green : Theme.GreenMid, modeChips[i], Theme.Center);
            }
        }
        Point mouse = new Point(-1, -1);

        public SummaryPanel() { Cursor = Cursors.Default; }

        static Color LossColor(double l) { return l >= 3 ? Theme.Red : l >= 1 ? Theme.Amber : Theme.Green; }
        static string Pct(double v) { return (v >= 10 ? Math.Round(v) : Math.Round(v, 1)).ToString(CultureInfo.InvariantCulture) + "%"; }

        public void Rebuild()
        {
            to = DateTime.Now;
            if (period == 0) from = DateTime.Today;
            else if (period == 1) from = DateTime.Today.AddDays(-6);
            else from = Store.Chronicle.Count > 0 ? Store.Chronicle.Min(x => x.When) : DateTime.Today;
            if ((to - from).TotalMinutes < 60) from = to.AddMinutes(-60);

            var all = Store.Chronicle.Where(x => x.When >= from && x.When <= to.AddMinutes(1)).OrderBy(x => x.When).ToList();
            ax = AuspexLog.Load(from, to);
            // ось времени начинаем от первого события, а не от полуночи
            if (all.Count > 0 || ax.Count > 0)
            {
                var first = all.Count > 0 ? all[0].When : ax[0].When;
                if (ax.Count > 0 && ax[0].When < first) first = ax[0].When;
                var restore = all.FirstOrDefault(x => x.Ritual == 9 && Loc.Starts(x.Headline, "СВЯЗЬ ВОССТАНОВЛЕНА"));
                if (restore != null && restore.When.AddSeconds(-restore.Seconds) < first) first = restore.When.AddSeconds(-restore.Seconds);
                var axis = first.AddMinutes(-Math.Max(10, (to - first).TotalMinutes * 0.03));
                from = axis;   // одна и та же ось при любом периоде, если данных столько же
            }
            foreach (var e in all) Store.Metrics(e);
            tests = all.Where(x => x.Ritual >= 1 && x.Ritual <= 5).ToList();
            verdicts = all.Where(x => x.Ritual >= 1 && x.Ritual <= 6).ToList();
            var guard = all.Where(x => x.Ritual == 9).ToList();
            nRed = tests.Count(x => x.Key == 'r'); nAmber = tests.Count(x => x.Key == 'a'); nGreen = tests.Count(x => x.Key == 'g');
            var downs = guard.Where(x => Loc.Starts(x.Headline, "ТУННЕЛЬ ПАЛ") || Loc.Starts(x.Headline, "СВЯЗЬ ПРОПАЛА")).ToList();
            var ups = guard.Where(x => Loc.Starts(x.Headline, "СВЯЗЬ ВОССТАНОВЛЕНА")).ToList();
            nOut = downs.Count;
            downSec = ups.Sum(x => (double)x.Seconds);
            vpnOffs = guard.Where(x => Loc.Starts(x.Headline, "VPN ОТКЛЮЧЁН")).ToList();
            bands.Clear();
            foreach (var u in ups) bands.Add(new KeyValuePair<DateTime, DateTime>(u.When.AddSeconds(-u.Seconds), u.When));
            var lastDown = downs.LastOrDefault();
            if (lastDown != null && !ups.Any(u => u.When > lastDown.When)) bands.Add(new KeyValuePair<DateTime, DateTime>(lastDown.When, to));

            withLoss = tests.Where(x => x.Loss >= 0).ToList();
            avgLoss = withLoss.Count > 0 ? withLoss.Average(x => x.Loss) : -1;
            for (int h = 0; h < 24; h++) { hourLoss[h] = 0; hourCnt[h] = 0; }
            foreach (var e in withLoss) { hourLoss[e.When.Hour] += e.Loss; hourCnt[e.When.Hour]++; }
            for (int h = 0; h < 24; h++) if (hourCnt[h] > 0) hourLoss[h] /= hourCnt[h];

            findings.Clear();
            worstHour = -1;
            minCnt = withLoss.Count >= 12 ? 2 : 1;
            int bestHour = -1;
            for (int h = 0; h < 24; h++)
            {
                if (hourCnt[h] < minCnt) continue;
                if (worstHour < 0 || hourLoss[h] > hourLoss[worstHour]) worstHour = h;
                if (bestHour < 0 || hourLoss[h] < hourLoss[bestHour]) bestHour = h;
            }
            if (withLoss.Count == 0)
                findings.Add(new KeyValuePair<string, Color>(Loc.T("ЗА ПЕРИОД НЕТ ИСПЫТАНИЙ С ЗАМЕРОМ ПОТЕРЬ. СОВЕРШИ ПЕРЕКЛИЧКУ ПАКЕТОВ (V) — ОНА ДАЁТ САМЫЕ ТОЧНЫЕ ДАННЫЕ."), Theme.GreenMid));
            else
            {
                if (worstHour >= 0 && hourLoss[worstHour] > 0)
                    findings.Add(new KeyValuePair<string, Color>(Loc.T("ХУДШИЙ ЧАС: ") + worstHour.ToString("00") + ":00–" + ((worstHour + 1) % 24).ToString("00") + Loc.T(":00 · ПОТЕРИ ") + Pct(hourLoss[worstHour]) + " (" + hourCnt[worstHour] + Loc.T(" ИСП.)"), LossColor(hourLoss[worstHour])));
                if (bestHour >= 0 && bestHour != worstHour)
                    findings.Add(new KeyValuePair<string, Color>(Loc.T("ЛУЧШИЙ ЧАС: ") + bestHour.ToString("00") + ":00–" + ((bestHour + 1) % 24).ToString("00") + Loc.T(":00 · ПОТЕРИ ") + Pct(hourLoss[bestHour]), Theme.Green));
                int lossy = withLoss.Count(x => x.Loss >= 1);
                findings.Add(new KeyValuePair<string, Color>(Loc.T("С ЗАМЕТНЫМИ ПОТЕРЯМИ (≥1%): ") + lossy + Loc.T(" ИЗ ") + withLoss.Count + " (" + Math.Round(100.0 * lossy / withLoss.Count) + "%)", lossy == 0 ? Theme.Green : Theme.Amber));
                if (withLoss.Count >= 6)
                {
                    int half = withLoss.Count / 2;
                    double a = withLoss.Take(half).Average(x => x.Loss), b = withLoss.Skip(half).Average(x => x.Loss);
                    string trend = Math.Abs(b - a) < 0.5 ? Loc.T("БЕЗ ПЕРЕМЕН") : b > a ? Loc.T("ХУЖЕ") : Loc.T("ЛУЧШЕ");
                    findings.Add(new KeyValuePair<string, Color>(Loc.T("ДИНАМИКА: ") + trend + " (" + Pct(a) + " → " + Pct(b) + ")", trend == Loc.T("ХУЖЕ") ? Theme.Amber : Theme.Green));
                }
            }
            if (ups.Count > 0)
            {
                var longest = ups.OrderByDescending(x => x.Seconds).First();
                findings.Add(new KeyValuePair<string, Color>(Loc.T("САМОЕ ДОЛГОЕ ПАДЕНИЕ: ") + Guardian.Fmt(TimeSpan.FromSeconds(longest.Seconds)).ToUpperInvariant() + " · " + longest.When.AddSeconds(-longest.Seconds).ToString("dd.MM HH:mm"), Theme.Red));
            }
            var lastClean = tests.LastOrDefault(x => x.Key == 'g');
            if (lastClean != null) findings.Add(new KeyValuePair<string, Color>(Loc.T("ПОСЛЕДНЕЕ ЧИСТОЕ ИСПЫТАНИЕ: ") + lastClean.When.ToString("dd.MM HH:mm"), Theme.Green));
            Invalidate();
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            mouse = e.Location;
            bool hand = chips.Any(c => c.Contains(e.Location)) || modeChips.Any(c => c.Contains(e.Location));
            Cursor = hand ? Cursors.Hand : Cursors.Default;
            Invalidate();
            base.OnMouseMove(e);
        }

        protected override void OnMouseLeave(EventArgs e) { mouse = new Point(-1, -1); Invalidate(); base.OnMouseLeave(e); }

        protected override void OnMouseClick(MouseEventArgs e)
        {
            for (int i = 0; i < 3; i++) if (chips[i].Contains(e.Location) && period != i) { period = i; Rebuild(); }
            for (int i = 0; i < 2; i++) if (modeChips[i].Contains(e.Location) && chartMode != i) { SwitchChart(i); break; }
            base.OnMouseClick(e);
        }

        void Header(Graphics g, RectangleF r, string title)
        {
            Theme.Box(g, r, Theme.GreenMid, 1.3f);
            var lf = Theme.Mono(8.5f, FontStyle.Bold);
            float tw = g.MeasureString(title, lf).Width + 24;
            var lb = new RectangleF(r.X + 12, r.Y - 10, tw, 20);
            using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, lb);
            Theme.Box(g, lb, Theme.Green, 1.2f);
            Theme.Glow(g, title, lf, Theme.Green, lb, Theme.Center);
        }

        protected override void PaintContent(Graphics g)
        {
            hits.Clear();
            var R = new RectangleF(6, 6, Width - 13, Height - 13);
            Theme.Box(g, R, Theme.OrangeDim, 1.2f);
            Theme.Box(g, new RectangleF(R.X + 6, R.Y + 6, R.Width - 12, R.Height - 12), Theme.Green, 1.6f);
            float pad = 26, x0 = R.X + pad, w = R.Width - pad * 2;
            var lf = Theme.Mono(8.5f, FontStyle.Bold);
            Theme.Glow(g, Loc.T("МОДУЛЬ"), lf, Theme.Orange, x0, R.Y + 14 - (Theme.Pixel ? 3 : 0));
            var tb = new RectangleF(x0, R.Y + 30, 190, 20);
            Theme.Box(g, tb, Theme.Green, 1.2f);
            Theme.Glow(g, Loc.T("СВОДКА ЛЕТОПИСИ"), lf, Theme.Green, tb, Theme.Center);

            // выбор периода
            float cx = x0 + w;
            for (int i = 2; i >= 0; i--)
            {
                float cw = g.MeasureString(Periods[i], lf).Width + 26;
                cx -= cw;
                chips[i] = new RectangleF(cx, R.Y + 28, cw, 24);
                cx -= 8;
                bool sel = i == period, hov = chips[i].Contains(mouse);
                if (sel) using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, chips[i]);
                Theme.Box(g, chips[i], sel ? Theme.Green : hov ? Theme.GreenMid : Theme.GreenDim, sel ? 1.5f : 1.1f);
                if (sel) Theme.Line(g, Theme.Orange, chips[i].X + 5, chips[i].Bottom - 3, chips[i].Right - 5, chips[i].Bottom - 3, 1.5f);
                Theme.Glow(g, Periods[i], lf, sel ? Theme.Green : Theme.GreenMid, chips[i], Theme.Center);
            }

            // ---- числа-итоги ----
            float ty = R.Y + 68, th = 76, gap = 10, tw2 = (w - gap * 5) / 6;
            int lossy = withLoss.Count(x => x.Loss >= 1);
            var tiles = new[]
            {
                new object[] { Loc.T("ИСПЫТАНИЙ"), tests.Count.ToString(), Theme.Green, Loc.T("ЧИСТО ") + nGreen + Loc.T(" · ТРЕВОГ ") + nAmber + Loc.T(" · ЕРЕСЕЙ ") + nRed },
                new object[] { Loc.T("СРЕДНИЕ ПОТЕРИ"), avgLoss < 0 ? "—" : Pct(avgLoss), avgLoss < 0 ? Theme.GreenDim : LossColor(avgLoss), Loc.T("ПО ") + withLoss.Count + Loc.T(" ЗАМЕРАМ") },
                new object[] { Loc.T("С ПОТЕРЯМИ ≥1%"), withLoss.Count == 0 ? "—" : lossy + "/" + withLoss.Count, lossy > 0 ? Theme.Amber : Theme.Green, Loc.T("ИСПЫТАНИЙ ЗА ПЕРИОД") },
                new object[] { Loc.T("ПАДЕНИЙ СВЯЗИ"), nOut.ToString(), nOut > 0 ? Theme.Red : Theme.Green, Loc.T("ПО ДАННЫМ СТРАЖА") },
                new object[] { Loc.T("ОБЩИЙ ПРОСТОЙ"), downSec <= 0 ? Loc.T("0 С") : Guardian.Fmt(TimeSpan.FromSeconds(downSec)).ToUpperInvariant(), downSec > 0 ? Theme.Red : Theme.Green, Loc.T("БЕЗ СВЯЗИ") },
                new object[] { Loc.T("VPN ОТКЛЮЧАЛСЯ"), vpnOffs.Count.ToString(), vpnOffs.Count > 0 ? Theme.Amber : Theme.Green, Loc.T("РАЗ ЗА ПЕРИОД") }
            };
            for (int i = 0; i < 6; i++)
            {
                var r = new RectangleF(x0 + i * (tw2 + gap), ty, tw2, th);
                Theme.Box(g, r, Theme.GreenDim, 1.2f);
                Theme.Line(g, Theme.Orange, r.X, r.Y, r.X + 10, r.Y, 1.6f); Theme.Line(g, Theme.Orange, r.X, r.Y, r.X, r.Y + 10, 1.6f);
                Theme.Glow(g, (string)tiles[i][0], Theme.Mono(8f, FontStyle.Bold), Theme.Orange, new RectangleF(r.X + 10, r.Y + 6, r.Width - 16, 16), Ui.NoWrap);
                Theme.Glow(g, (string)tiles[i][1], Theme.Title(17f), (Color)tiles[i][2], new RectangleF(r.X + 10, r.Y + 22, r.Width - 16, 32), Ui.NoWrap);
                using (var b = new SolidBrush(Theme.GreenDim))
                    g.DrawString((string)tiles[i][3], Theme.Mono(7.5f, FontStyle.Regular), b, new RectangleF(r.X + 10, r.Y + 54, r.Width - 16, 16), Ui.NoWrap);
            }

            float restTop = ty + th + 26, restH = R.Bottom - 16 - restTop;
            var tl = new RectangleF(x0, restTop, w, restH * 0.55f);
            var hr = new RectangleF(x0, tl.Bottom + 26, w * 0.58f, restH - tl.Height - 26);
            var fr = new RectangleF(hr.Right + 16, hr.Y, w - hr.Width - 16, hr.Height);

            chartRect = tl;
            if (chartMode == 0) PaintTimeline(g, tl); else PaintAuspex(g, tl);
            PaintChartSwitch(g, tl);
            if (beamClock != null) { PaintBeam(g, tl); hits.Clear(); }
            PaintHours(g, hr);
            PaintFindings(g, fr);
            PaintTooltip(g);
        }

        // отрезки привязаны к часам, а не к началу оси: одни и те же данные дают одну и ту же кривую при любом периоде
        static double BucketSec(double spanSec, int target)
        {
            double[] nice = { 60, 120, 300, 600, 900, 1800, 3600, 7200, 10800, 21600, 43200, 86400, 172800, 345600 };
            double want = spanSec / Math.Max(1, target);
            foreach (var n in nice) if (n >= want) return n;
            return nice[nice.Length - 1];
        }
        DateTime BucketOrigin(double size)
        {
            var t0 = new DateTime(2000, 1, 3);   // понедельник, полночь
            return t0.AddSeconds(Math.Floor((from - t0).TotalSeconds / size) * size);
        }

        string AxisLabel(DateTime t) { double d = (to - from).TotalDays; return d <= 1.5 ? t.ToString("HH:mm") : d <= 8 ? t.ToString("dd.MM HH:mm") : t.ToString("dd.MM"); }

        float X(RectangleF p, DateTime t) { double span = Math.Max(1, (to - from).TotalSeconds); return p.X + (float)(p.Width * Math.Max(0, Math.Min(1, (t - from).TotalSeconds / span))); }

        void PaintTimeline(Graphics g, RectangleF box)
        {
            Header(g, box, Loc.T("ПОТЕРИ ПО ВРЕМЕНИ"));
            var lane = new RectangleF(box.X + 48, box.Y + 20, box.Width - 64, 16);
            var p = new RectangleF(box.X + 48, box.Y + 46, box.Width - 64, box.Height - 70);
            double mx = withLoss.Count > 0 ? withLoss.Max(x => x.Loss) : 0;
            double top = Math.Max(5, Math.Ceiling(mx / 5) * 5);
            if (top > 100) top = 100;
            var tf = Theme.Mono(7.5f, FontStyle.Regular);
            using (var pen = new Pen(Color.FromArgb(36, Theme.Green), 1f) { DashStyle = DashStyle.Dot })
            using (var b = new SolidBrush(Theme.GreenDim))
                for (int i = 0; i <= 2; i++)
                {
                    float y = p.Bottom - p.Height * i / 2f;
                    if (i > 0) g.DrawLine(pen, p.X, y, p.Right, y);
                    g.DrawString(Pct(top * i / 2), tf, b, new RectangleF(box.X + 4, y - 7, 42, 14), Theme.Right);
                }
            using (var pen = new Pen(Theme.GreenDim, 1f)) g.DrawLine(pen, p.X, p.Bottom, p.Right, p.Bottom);
            // порог 3%
            if (3 < top)
            {
                float y3 = p.Bottom - (float)(p.Height * 3 / top);
                using (var pen = new Pen(Color.FromArgb(120, Theme.Amber), 1f) { DashStyle = DashStyle.Dash }) g.DrawLine(pen, p.X, y3, p.Right, y3);
                using (var b = new SolidBrush(Color.FromArgb(170, Theme.Amber))) g.DrawString(Loc.T("ПОРОГ 3%"), tf, b, p.Right - 58, y3 - 13);
            }
            // ось времени
            double span = (to - from).TotalDays;
            using (var b = new SolidBrush(Theme.GreenDim))
                for (int i = 0; i <= 6; i++)
                {
                    var t = from.AddSeconds((to - from).TotalSeconds * i / 6);
                    float x = X(p, t);
                    g.DrawString(AxisLabel(t), tf, b, new RectangleF(x - 40, p.Bottom + 4, 80, 14), Theme.Center);
                }
            // падения связи — полосы
            foreach (var bd in bands)
            {
                float a = X(p, bd.Key), z = Math.Max(a + 2, X(p, bd.Value));
                var rr = new RectangleF(a, p.Y, z - a, p.Height);
                using (var b = new SolidBrush(Color.FromArgb(26, Theme.Red))) g.FillRectangle(b, rr);
                hits.Add(new Hit { R = RectangleF.Inflate(rr, 3, 0), C = Theme.Red, Pri = 0, Shape = 3, Lines = new[] { Loc.T("ПАДЕНИЕ СВЯЗИ (СТРАЖ)"), bd.Key.ToString("dd.MM HH:mm:ss") + " — " + bd.Value.ToString("HH:mm:ss"), Loc.T("ПРОСТОЙ: ") + Guardian.Fmt(bd.Value - bd.Key).ToUpperInvariant() } });
            }
            // отключения VPN — засечки
            foreach (var v in vpnOffs)
            {
                float x = X(p, v.When);
                var tri = new[] { new PointF(x, p.Bottom - 7), new PointF(x - 4, p.Bottom), new PointF(x + 4, p.Bottom) };
                using (var b = new SolidBrush(Color.FromArgb(170, Theme.Amber))) g.FillPolygon(b, tri);
                hits.Add(new Hit { R = new RectangleF(x - 6, p.Bottom - 10, 12, 12), C = Theme.Amber, Pri = 2, Shape = 1, Ctr = new PointF(x, p.Bottom - 3), Rad = 7, Lines = new[] { Loc.T("VPN ОТКЛЮЧЁН"), v.When.ToString("dd.MM HH:mm:ss") } });
            }
            double bsz = BucketSec((to - from).TotalSeconds, Math.Max(12, (int)(p.Width / 18)));
            DateTime borg = BucketOrigin(bsz);
            int nb = (int)Math.Ceiling((to - borg).TotalSeconds / bsz) + 1;
            PaintVerdictLane(g, lane, p, bsz, borg);
            if (withLoss.Count == 0)
            {
                Theme.Glow(g, Loc.T("НЕТ ЗАМЕРОВ ПОТЕРЬ ЗА ПЕРИОД"), Theme.Mono(9f, FontStyle.Bold), Theme.GreenDim, p, Theme.Center);
                return;
            }
            Func<double, float> Y = v => p.Bottom - (float)(p.Height * Math.Min(1, v / top));

            // отдельные замеры — тусклые точки фоном
            for (int i = 0; i < withLoss.Count; i++)
            {
                var e = withLoss[i];
                var c = LossColor(e.Loss);
                float x = X(p, e.When), y = Y(e.Loss);
                var dot = new RectangleF(x - 2.5f, y - 2.5f, 5, 5);
                using (var b = new SolidBrush(Color.FromArgb(110, c))) g.FillEllipse(b, dot);
                string name = e.Ritual >= 1 && e.Ritual <= 5 ? RNums[e.Ritual] : "?";
                hits.Add(new Hit
                {
                    R = RectangleF.Inflate(dot, 4, 4), C = c, Pri = 4, Shape = 1, Ctr = new PointF(x, y), Rad = 5,
                    Lines = new[] { e.When.ToString("dd.MM HH:mm") + Loc.T(" · РИТУАЛ ") + name + (e.Sanctum.Length > 0 ? " · " + e.Sanctum.ToUpperInvariant() : ""), Loc.TH(e.Headline),
                                    Loc.T("ПОТЕРИ ") + Pct(e.Loss) + (e.Ping >= 0 ? Loc.T(" · ПИНГ ДО 1.1.1.1 ") + Math.Round(e.Ping) + Loc.T(" МС") : "") }
                });
            }

            // кривая: средние потери по отрезкам времени; там, где замеров не было, — разрыв
            var bucket = new List<double>[nb]; var btime = new double[nb];
            for (int i = 0; i < nb; i++) bucket[i] = new List<double>();
            span = Math.Max(1, (to - from).TotalSeconds);
            foreach (var e in withLoss)
            {
                int k = (int)Math.Floor((e.When - borg).TotalSeconds / bsz);
                k = Math.Max(0, Math.Min(nb - 1, k));
                bucket[k].Add(e.Loss); btime[k] += (e.When - from).TotalSeconds;
            }
            float bw = (float)(p.Width * bsz / span);
            var seg = new List<PointF>(); var segV = new List<double>();
            int lastK = -100;
            Action flush = () =>
            {
                if (seg.Count == 1) { seg.Insert(0, new PointF(seg[0].X - bw * 0.35f, seg[0].Y)); seg[1] = new PointF(seg[1].X + bw * 0.35f, seg[1].Y); segV.Insert(0, segV[0]); }
                if (seg.Count > 1)
                {
                    var poly = new List<PointF>(seg); poly.Add(new PointF(seg[seg.Count - 1].X, p.Bottom)); poly.Add(new PointF(seg[0].X, p.Bottom));
                    using (var b = new SolidBrush(Color.FromArgb(28, Theme.Green))) g.FillPolygon(b, poly.ToArray());
                    for (int i = 1; i < seg.Count; i++)
                        using (var pen = new Pen(LossColor(Math.Max(segV[i - 1], segV[i])), 2.2f)) g.DrawLine(pen, seg[i - 1], seg[i]);
                }
                seg.Clear(); segV.Clear();
            };
            for (int k = 0; k < nb; k++)
            {
                if (bucket[k].Count == 0) continue;
                if (k - lastK > 3) flush();   // больше трёх пустых отрезков подряд — линия рвётся
                double avg = bucket[k].Average();
                var pt = new PointF(X(p, from.AddSeconds(btime[k] / bucket[k].Count)), Y(avg));
                seg.Add(pt); segV.Add(avg);
                lastK = k;
                var t0 = borg.AddSeconds(bsz * k); var t1 = borg.AddSeconds(bsz * (k + 1));
                float cx0 = X(p, t0), cx1 = X(p, t1);
                var col = new RectangleF(cx0, p.Y, Math.Max(2, cx1 - cx0), p.Height);
                var ln = new[] { t0.ToString("dd.MM HH:mm") + " — " + t1.ToString("HH:mm"), Loc.T("ЗАМЕРОВ: ") + bucket[k].Count, Loc.T("СРЕДНИЕ ПОТЕРИ: ") + Pct(avg) + Loc.T(" · ХУДШИЙ ") + Pct(bucket[k].Max()) };
                hits.Add(new Hit { R = col, C = LossColor(avg), Pri = 1, Shape = 3, Lines = ln });
                hits.Add(new Hit { R = new RectangleF(pt.X - 8, pt.Y - 8, 16, 16), C = LossColor(avg), Pri = 3, Shape = 1, Ctr = pt, Rad = 7, Lines = ln });
            }
            flush();
            for (int k = 0; k < nb; k++)
                if (bucket[k].Count > 0)
                {
                    double avg = bucket[k].Average();
                    float cx = X(p, from.AddSeconds(btime[k] / bucket[k].Count)), cy = Y(avg);
                    using (var pen = new Pen(Theme.Bg, 2f)) g.DrawEllipse(pen, cx - 4, cy - 4, 8, 8);
                    using (var b = new SolidBrush(LossColor(avg))) g.FillEllipse(b, cx - 3.5f, cy - 3.5f, 7, 7);
                }
        }

        // приговоры по тем же отрезкам времени: один знак на отрезок, цвет — худший приговор
        void PaintVerdictLane(Graphics g, RectangleF lane, RectangleF p, double bsz, DateTime borg)
        {
            var tf = Theme.Mono(7f, FontStyle.Bold);
            using (var b = new SolidBrush(Theme.GreenDim)) g.DrawString(Loc.T("ПРИГОВ."), tf, b, new RectangleF(lane.X - 52, lane.Y + 1, 50, 14), Theme.Right);
            using (var pen = new Pen(Color.FromArgb(40, Theme.Green), 1f) { DashStyle = DashStyle.Dot }) g.DrawLine(pen, lane.X, lane.Y + lane.Height / 2, lane.Right, lane.Y + lane.Height / 2);
            double span = Math.Max(1, (to - from).TotalSeconds);
            float cy = lane.Y + lane.Height / 2, bw = (float)(p.Width * bsz / span);
            var groups = verdicts.GroupBy(e => (long)Math.Floor((e.When - borg).TotalSeconds / bsz)).OrderBy(gr => gr.Key);
            foreach (var gr in groups)
            {
                var list = gr.OrderBy(e => e.When).ToList();
                int nr = list.Count(e => e.Key == 'r'), na = list.Count(e => e.Key == 'a'), ng = list.Count - nr - na;
                Color c = nr > 0 ? Theme.Red : na > 0 ? Theme.Amber : Theme.Green;
                float x = X(p, from.AddSeconds(list.Average(e => (e.When - from).TotalSeconds)));
                float r = nr > 0 || na > 0 ? 5f : 3.5f;
                var hr = new RectangleF(x - Math.Max(6, bw / 2), lane.Y - 2, Math.Max(12, bw), lane.Height + 4);
                var dm = new[] { new PointF(x, cy - r), new PointF(x + r, cy), new PointF(x, cy + r), new PointF(x - r, cy) };
                using (var b = new SolidBrush(c)) g.FillPolygon(b, dm);
                if (list.Count > 1) using (var b = new SolidBrush(Color.FromArgb(200, c))) g.DrawString(list.Count.ToString(), Theme.Mono(6.5f, FontStyle.Bold), b, x + r + 1, cy - 6);
                var lines = new List<string>();
                lines.Add(list[0].When.ToString("dd.MM HH:mm") + (list.Count > 1 ? " — " + list[list.Count - 1].When.ToString("HH:mm") : "") + " · " + Loc.T("ЧИСТО ") + ng + Loc.T(" · ТРЕВОГ ") + na + Loc.T(" · ЕРЕСЕЙ ") + nr);
                foreach (var e in list.OrderBy(e => e.Key == 'r' ? 0 : e.Key == 'a' ? 1 : 2).ThenBy(e => e.When).Take(5))
                    lines.Add(e.When.ToString("HH:mm") + " " + (e.Ritual == 6 ? Loc.T("ВРАТА") : RNums[e.Ritual]) + " · " + Loc.TH(e.Headline));
                if (list.Count > 5) lines.Add("… +" + (list.Count - 5));
                hits.Add(new Hit { R = hr, C = c, Pri = 3, Shape = 2, Ctr = new PointF(x, cy), Rad = r + 2.5f, Lines = lines.ToArray() });
            }
        }

        // ---- второй график: всё, что видело око ауспика ----
        void PaintAuspex(Graphics g, RectangleF box)
        {
            Header(g, box, Loc.T("ОКО АУСПИКА · ПИНГ И ПОТЕРИ ДО 1.1.1.1"));
            var tf = Theme.Mono(7.5f, FontStyle.Regular);
            var p = new RectangleF(box.X + 48, box.Y + 40, box.Width - 64, box.Height - 64);
            if (ax.Count == 0)
            {
                Theme.Glow(g, Loc.T("ОКО АУСПИКА НЕ ОТКРЫВАЛОСЬ ЗА ЭТОТ ПЕРИОД — ВОЗЗОВИ ЕГО НА ТЕРМИНАЛЕ"), Theme.Mono(9f, FontStyle.Bold), Theme.GreenDim, p, Theme.Center);
                return;
            }
            // сводка одной строкой
            int sentT = ax.Sum(m => m.Sent), recvT = ax.Sum(m => m.Recv);
            double lossT = sentT > 0 ? 100.0 * (sentT - recvT) / sentT : 0;
            var okm = ax.Where(m => m.Recv > 0).ToList();
            double avgT = recvT > 0 ? okm.Sum(m => m.Avg * m.Recv) / recvT : -1;
            var sorted = okm.Select(m => m.Avg).OrderBy(v => v).ToList();
            double p95 = sorted.Count > 0 ? sorted[Math.Min(sorted.Count - 1, (int)(sorted.Count * 0.95))] : -1;
            int dead = ax.Count(m => m.Recv == 0);
            double tunPct = 100.0 * ax.Count(m => m.Mode == 1) / ax.Count;
            double jitT = okm.Count > 0 ? okm.Average(m => m.Jit) : 0;
            var parts = new List<KeyValuePair<string, Color>>
            {
                new KeyValuePair<string, Color>(Loc.T("НАБЛЮДЕНИЕ ") + Guardian.Fmt(TimeSpan.FromMinutes(ax.Count)).ToUpperInvariant(), Theme.GreenMid),
                new KeyValuePair<string, Color>(Loc.T("ПИНГ ") + (avgT < 0 ? "—" : Math.Round(avgT) + Loc.T(" МС")) + " · P95 " + (p95 < 0 ? "—" : Math.Round(p95).ToString()), avgT < 0 ? Theme.GreenDim : avgT < 80 ? Theme.Green : avgT < 200 ? Theme.Amber : Theme.Red),
                new KeyValuePair<string, Color>(Loc.T("ДЖИТТЕР ") + Math.Round(jitT, 1).ToString(CultureInfo.InvariantCulture) + Loc.T(" МС"), jitT < 10 ? Theme.Green : jitT < 30 ? Theme.Amber : Theme.Red),
                new KeyValuePair<string, Color>(Loc.T("ПОТЕРИ ") + Pct(lossT), LossColor(lossT)),
                new KeyValuePair<string, Color>(Loc.T("МИНУТ БЕЗ СВЯЗИ ") + dead, dead > 0 ? Theme.Red : Theme.Green),
                new KeyValuePair<string, Color>(Loc.T("ЧЕРЕЗ ТУННЕЛЬ ") + Math.Round(tunPct) + "%", Theme.GreenMid)
            };
            var sf = Theme.Mono(8f, FontStyle.Bold);
            float sx = p.X;
            foreach (var kv in parts)
            {
                Theme.Glow(g, kv.Key, sf, kv.Value, sx, box.Y + 16);
                sx += g.MeasureString(kv.Key, sf).Width + 18;
            }

            // верх — пинг, низ — потери
            var pp = new RectangleF(p.X, p.Y, p.Width, p.Height * 0.68f);
            var lp = new RectangleF(p.X, pp.Bottom + p.Height * 0.08f, p.Width, p.Height * 0.24f);
            double span = Math.Max(1, (to - from).TotalSeconds);
            double bsz = BucketSec(span, Math.Max(20, (int)(p.Width / 4)));
            DateTime borg = BucketOrigin(bsz);
            int nb = (int)Math.Ceiling((to - borg).TotalSeconds / bsz) + 1;
            var cs = new int[nb]; var cr = new int[nb]; var csum = new double[nb]; var cmax = new double[nb]; var ct = new double[nb]; var cn = new int[nb]; var ctun = new int[nb];
            foreach (var m in ax)
            {
                int k = Math.Max(0, Math.Min(nb - 1, (int)Math.Floor((m.When - borg).TotalSeconds / bsz)));
                cs[k] += m.Sent; cr[k] += m.Recv; csum[k] += m.Avg * m.Recv; cmax[k] = Math.Max(cmax[k], m.Max);
                ct[k] += (m.When.AddSeconds(30) - from).TotalSeconds; cn[k]++; if (m.Mode == 1) ctun[k]++;
            }
            var avgs = Enumerable.Range(0, nb).Where(k => cr[k] > 0).Select(k => csum[k] / cr[k]).OrderBy(v => v).ToList();
            double ref95 = avgs.Count > 0 ? avgs[Math.Min(avgs.Count - 1, (int)(avgs.Count * 0.95))] : 50;
            double ptop = Math.Max(50, Math.Ceiling(ref95 * 1.4 / 50) * 50);
            double lmax = 0; for (int k = 0; k < nb; k++) if (cs[k] > 0) lmax = Math.Max(lmax, 100.0 * (cs[k] - cr[k]) / cs[k]);
            double ltop = lmax <= 5 ? 5 : lmax <= 20 ? 20 : lmax <= 50 ? 50 : 100;

            // сетка и подписи
            using (var pen = new Pen(Color.FromArgb(36, Theme.Green), 1f) { DashStyle = DashStyle.Dot })
            using (var b = new SolidBrush(Theme.GreenDim))
            {
                for (int i = 0; i <= 2; i++)
                {
                    float y = pp.Bottom - pp.Height * i / 2f;
                    if (i > 0) g.DrawLine(pen, pp.X, y, pp.Right, y);
                    g.DrawString(Math.Round(ptop * i / 2) + (i == 2 ? Loc.T(" МС") : ""), tf, b, new RectangleF(box.X + 2, y - 7, 44, 14), Theme.Right);
                }
                g.DrawLine(pen, lp.X, lp.Y, lp.Right, lp.Y);
                g.DrawString(Pct(ltop), tf, b, new RectangleF(box.X + 2, lp.Y - 7, 44, 14), Theme.Right);
                g.DrawString(Loc.T("ПОТЕРИ"), Theme.Mono(6.5f, FontStyle.Bold), b, new RectangleF(box.X + 2, lp.Bottom - 10, 44, 12), Theme.Right);
            }
            using (var pen = new Pen(Theme.GreenDim, 1f)) { g.DrawLine(pen, pp.X, pp.Bottom, pp.Right, pp.Bottom); g.DrawLine(pen, lp.X, lp.Bottom, lp.Right, lp.Bottom); }
            using (var b = new SolidBrush(Theme.GreenDim))
                for (int i = 0; i <= 6; i++)
                {
                    var t = from.AddSeconds(span * i / 6);
                    g.DrawString(AxisLabel(t), tf, b, new RectangleF(X(p, t) - 40, lp.Bottom + 4, 80, 14), Theme.Center);
                }
            // падения связи по Стражу — те же полосы, что и выше
            foreach (var bd in bands)
            {
                float a = X(p, bd.Key), z = Math.Max(a + 2, X(p, bd.Value));
                using (var b = new SolidBrush(Color.FromArgb(22, Theme.Red))) g.FillRectangle(b, a, pp.Y, z - a, lp.Bottom - pp.Y);
            }

            float bw = (float)(p.Width * bsz / span);
            Func<double, float> PY = v => pp.Bottom - (float)(pp.Height * Math.Min(1, v / ptop));
            var seg = new List<PointF>(); var segV = new List<double>(); int lastK = -100;
            Action flush = () =>
            {
                if (seg.Count > 1)
                {
                    var poly = new List<PointF>(seg); poly.Add(new PointF(seg[seg.Count - 1].X, pp.Bottom)); poly.Add(new PointF(seg[0].X, pp.Bottom));
                    using (var b = new SolidBrush(Color.FromArgb(24, Theme.Green))) g.FillPolygon(b, poly.ToArray());
                    for (int i = 1; i < seg.Count; i++)
                    {
                        double v = Math.Max(segV[i - 1], segV[i]);
                        using (var pen = new Pen(v < 80 ? Theme.Green : v < 200 ? Theme.Amber : Theme.Red, 1.6f)) g.DrawLine(pen, seg[i - 1], seg[i]);
                    }
                }
                else if (seg.Count == 1) using (var b = new SolidBrush(Theme.Green)) g.FillEllipse(b, seg[0].X - 1.5f, seg[0].Y - 1.5f, 3, 3);
                seg.Clear(); segV.Clear();
            };
            for (int k = 0; k < nb; k++)
            {
                if (cs[k] == 0) continue;
                float x = X(p, from.AddSeconds(ct[k] / cn[k]));
                double loss = 100.0 * (cs[k] - cr[k]) / cs[k];
                // потери — столбики снизу
                if (loss >= 1)
                {
                    float lh = Math.Max(2, (float)(lp.Height * Math.Min(1, loss / ltop)));
                    using (var b = new SolidBrush(Color.FromArgb(210, LossColor(loss)))) g.FillRectangle(b, x - Math.Max(1, bw / 2 - 0.5f), lp.Bottom - lh, Math.Max(2, bw - 1), lh);
                }
                double avg = cr[k] > 0 ? csum[k] / cr[k] : -1;
                if (avg >= 0)
                {
                    if (k - lastK > 3) flush();
                    // разброс до худшего пинга — тонкая вертикаль
                    seg.Add(new PointF(x, PY(avg))); segV.Add(avg); lastK = k;
                }
                else { flush(); Theme.Line(g, Theme.Red, x, pp.Y + 2, x, pp.Bottom, 1.2f); }
                var t0 = borg.AddSeconds(bsz * k); var t1 = borg.AddSeconds(bsz * (k + 1));
                float cx0 = X(p, t0), cx1 = X(p, t1);
                string md = (ctun[k] * 2 >= cn[k] ? Loc.T("через туннель") : Loc.T("напрямую")).ToUpperInvariant();
                hits.Add(new Hit
                {
                    R = new RectangleF(cx0, pp.Y, Math.Max(2, cx1 - cx0), lp.Bottom - pp.Y), C = avg < 0 ? Theme.Red : LossColor(loss), Pri = 1, Shape = 3,
                    Lines = new[] { t0.ToString("dd.MM HH:mm") + " — " + t1.ToString("HH:mm") + " · " + md,
                                    avg < 0 ? Loc.T("НИ ОДИН ПИНГ НЕ ВЕРНУЛСЯ") : Loc.T("ПИНГ: СРЕДНИЙ ") + Math.Round(avg) + Loc.T(" · ХУДШИЙ ") + Math.Round(cmax[k]) + Loc.T(" МС"),
                                    Loc.T("ПОТЕРИ ") + Pct(loss) + " (" + (cs[k] - cr[k]) + "/" + cs[k] + ")" }
                });
            }
            flush();
        }

        void PaintHours(Graphics g, RectangleF box)

        {
            Header(g, box, Loc.T("ЧАСЫ СУТОК · СРЕДНИЕ ПОТЕРИ"));
            var p = new RectangleF(box.X + 48, box.Y + 22, box.Width - 62, box.Height - 46);
            double mx = 0; for (int h = 0; h < 24; h++) if (hourCnt[h] > 0) mx = Math.Max(mx, hourLoss[h]);
            double top = Math.Max(5, Math.Ceiling(mx / 5) * 5);
            var tf = Theme.Mono(7.5f, FontStyle.Regular);
            using (var b = new SolidBrush(Theme.GreenDim))
            {
                g.DrawString(Pct(top), tf, b, new RectangleF(box.X + 4, p.Y - 7, 42, 14), Theme.Right);
                g.DrawString("0%", tf, b, new RectangleF(box.X + 4, p.Bottom - 7, 42, 14), Theme.Right);
            }
            using (var pen = new Pen(Color.FromArgb(36, Theme.Green), 1f) { DashStyle = DashStyle.Dot }) g.DrawLine(pen, p.X, p.Y, p.Right, p.Y);
            using (var pen = new Pen(Theme.GreenDim, 1f)) g.DrawLine(pen, p.X, p.Bottom, p.Right, p.Bottom);
            float slot = p.Width / 24f, bw = Math.Max(3, slot - 3);
            for (int h = 0; h < 24; h++)
            {
                float x = p.X + h * slot + (slot - bw) / 2;
                if (h % 3 == 0) using (var b = new SolidBrush(Theme.GreenDim)) g.DrawString(h.ToString("00"), tf, b, new RectangleF(x - 8, p.Bottom + 4, bw + 16, 14), Theme.Center);
                var col = new RectangleF(p.X + h * slot, p.Y, slot, p.Height);
                bool hov = col.Contains(mouse);
                if (hourCnt[h] == 0)
                {
                    using (var b = new SolidBrush(Color.FromArgb(40, Theme.GreenDim))) g.FillRectangle(b, x, p.Bottom - 2, bw, 2);
                    hits.Add(new Hit { R = col, C = Theme.GreenDim, Lines = new[] { h.ToString("00") + ":00–" + ((h + 1) % 24).ToString("00") + ":00", Loc.T("ЗАМЕРОВ НЕТ") } });
                    continue;
                }
                float bh = Math.Max(2, (float)(p.Height * Math.Min(1, hourLoss[h] / top)));
                var bar = new RectangleF(x, p.Bottom - bh, bw, bh);
                Color c = h == worstHour && hourLoss[h] > 0 ? Theme.Orange : Theme.GreenMid;
                bool weak = hourCnt[h] < minCnt;   // мало замеров — столбец приглушён и в выводы не идёт
                if (hov) using (var b = new SolidBrush(Color.FromArgb(25, Theme.Green))) g.FillRectangle(b, col);
                if (weak)
                {
                    using (var b = new SolidBrush(Color.FromArgb(hov ? 90 : 55, c))) g.FillRectangle(b, bar);
                    using (var pen = new Pen(Color.FromArgb(150, c), 1f) { DashStyle = DashStyle.Dot }) g.DrawRectangle(pen, bar.X, bar.Y, bar.Width - 1, bar.Height);
                }
                else using (var b = new SolidBrush(Color.FromArgb(hov ? 255 : 210, c))) g.FillRectangle(b, bar);
                hits.Add(new Hit { R = col, C = c, Lines = weak
                    ? new[] { h.ToString("00") + ":00–" + ((h + 1) % 24).ToString("00") + ":00", Loc.T("ЗАМЕРОВ: ") + hourCnt[h] + Loc.T(" — МАЛО, НЕНАДЁЖНО"), Loc.T("СРЕДНИЕ ПОТЕРИ: ") + Pct(hourLoss[h]) }
                    : new[] { h.ToString("00") + ":00–" + ((h + 1) % 24).ToString("00") + ":00", Loc.T("ЗАМЕРОВ: ") + hourCnt[h], Loc.T("СРЕДНИЕ ПОТЕРИ: ") + Pct(hourLoss[h]) } });
            }
            if (worstHour >= 0 && hourCnt[worstHour] > 0 && hourLoss[worstHour] > 0)
            {
                float x = p.X + worstHour * slot + slot / 2;
                float y = p.Bottom - Math.Max(2, (float)(p.Height * Math.Min(1, hourLoss[worstHour] / top)));
                Theme.Glow(g, Loc.T("ХУДШИЙ"), Theme.Mono(7.5f, FontStyle.Bold), Theme.Orange, new RectangleF(x - 40, y - 16, 80, 14), Theme.Center);
            }
        }

        void PaintFindings(Graphics g, RectangleF box)
        {
            Header(g, box, Loc.T("ВЫВОДЫ КОГИТАТОРА"));
            var f = Theme.Mono(9f, FontStyle.Bold);
            float y = box.Y + 22, x = box.X + 14, tw = box.Width - 40;
            foreach (var kv in findings)
            {
                var sz = g.MeasureString(kv.Key, f, (int)tw);
                if (y + sz.Height > box.Bottom - 8) break;
                Theme.Line(g, Theme.GreenDim, x, y + 8, x + 10, y + 8, 1.2f);
                Theme.Glow(g, kv.Key, f, kv.Value, new RectangleF(x + 16, y, tw, sz.Height + 2), StringFormat.GenericDefault);
                y += sz.Height + 8;
            }
        }

        void PaintTooltip(Graphics g)
        {
            if (mouse.X < 0) return;
            Hit h = null; double hd = double.MaxValue;
            foreach (var c in hits)
            {
                if (!c.R.Contains(mouse)) continue;
                double d = c.Shape == 1 || c.Shape == 2 ? Math.Pow(c.Ctr.X - mouse.X, 2) + Math.Pow(c.Ctr.Y - mouse.Y, 2) : 1e9;
                if (h == null || c.Pri > h.Pri || (c.Pri == h.Pri && d < hd)) { h = c; hd = d; }
            }
            if (h == null) return;
            if (h.Shape == 3) using (var b = new SolidBrush(Color.FromArgb(30, h.C))) g.FillRectangle(b, h.R);
            else if (h.Shape == 1)
            {
                using (var pen = new Pen(Theme.Orange, 1.6f)) g.DrawEllipse(pen, h.Ctr.X - h.Rad, h.Ctr.Y - h.Rad, h.Rad * 2, h.Rad * 2);
                using (var pen = new Pen(Color.FromArgb(70, Theme.Orange), 1f) { DashStyle = DashStyle.Dot }) g.DrawLine(pen, h.Ctr.X, h.R.Top < h.Ctr.Y - 20 ? h.R.Top : h.Ctr.Y + h.Rad, h.Ctr.X, h.Ctr.Y + h.Rad);
            }
            else if (h.Shape == 2)
            {
                float rd = h.Rad;
                using (var pen = new Pen(Theme.Orange, 1.4f)) g.DrawPolygon(pen, new[] { new PointF(h.Ctr.X, h.Ctr.Y - rd), new PointF(h.Ctr.X + rd, h.Ctr.Y), new PointF(h.Ctr.X, h.Ctr.Y + rd), new PointF(h.Ctr.X - rd, h.Ctr.Y) });
            }
            var f = Theme.Mono(9f, FontStyle.Bold);
            float w = 0, lh = g.MeasureString("Ж", f).Height;
            foreach (var l in h.Lines) w = Math.Max(w, g.MeasureString(l, f).Width);
            var r = new RectangleF(mouse.X + 16, mouse.Y + 14, w + 20, lh * h.Lines.Length + 14);
            if (r.Right > Width - 8) r.X = mouse.X - r.Width - 12;
            if (r.Bottom > Height - 8) r.Y = mouse.Y - r.Height - 10;
            using (var b = new SolidBrush(Color.FromArgb(245, 3, 8, 4))) g.FillRectangle(b, r);
            Theme.Box(g, r, h.C, 1.4f);
            for (int i = 0; i < h.Lines.Length; i++)
                using (var b = new SolidBrush(i == 0 ? Theme.Orange : Theme.Text))
                    g.DrawString(h.Lines[i], f, b, r.X + 10, r.Y + 7 + i * lh);
        }
    }

    // ============================== АУСПИК: HUD ПОВЕРХ ОКОН ==============================
    // ============================== ОПОЗНАНИЕ ТУННЕЛЕЙ ==============================
    // WireGuard/AmneziaWG, sing-box (Throne, Nekoray, Hiddify), Xray, Clash, OpenVPN — по имени адаптера;
    // неизвестный клиент — по маршруту: интернет уходит в адаптер без MAC-адреса.
    static class Tun
    {
        [DllImport("iphlpapi.dll")] static extern int GetBestInterface(uint dwDestAddr, out uint idx);

        public const string Known = @"amnezia|wireguard|wintun|\bawg|\btun\d*\b|-tun\b|\btun-|tap-windows|openvpn|sing-?box|throne|nekoray|nekobox|hiddify|v2ray|xray|clash|mihomo|outline|warp|psiphon|proton|nordlynx|mullvad";
        const string NotTunnel = @"tailscale|zerotier|hyper-v|vethernet|virtualbox|vmware|wsl|docker|npcap|bluetooth|teredo|isatap|6to4|loopback|kernel debug";

        public static bool Looks(NetworkInterface n, string pattern)
        {
            string id = n.Name + " " + n.Description;
            try
            {
                if (Regex.IsMatch(id, NotTunnel, RegexOptions.IgnoreCase)) return false;
                if (!string.IsNullOrEmpty(pattern) && Regex.IsMatch(id, pattern, RegexOptions.IgnoreCase)) return true;
                return Regex.IsMatch(id, Known, RegexOptions.IgnoreCase);
            }
            catch { return false; }
        }

        static int Idx(NetworkInterface n) { try { return n.GetIPProperties().GetIPv4Properties().Index; } catch { return -1; } }

        // активный туннель или null
        public static NetworkInterface Find(string pattern) { NetworkInterface any; return Find(pattern, out any); }

        public static NetworkInterface Find(string pattern, out NetworkInterface anyKnown)
        {
            anyKnown = null;
            NetworkInterface[] all;
            try { all = NetworkInterface.GetAllNetworkInterfaces(); } catch { return null; }
            int best = -1;
            try { uint bi; if (GetBestInterface(BitConverter.ToUInt32(IPAddress.Parse("1.1.1.1").GetAddressBytes(), 0), out bi) == 0) best = (int)bi; } catch { }
            NetworkInterface up = null;
            foreach (var n in all)
            {
                if (n.NetworkInterfaceType == NetworkInterfaceType.Loopback || !Looks(n, pattern)) continue;
                if (anyKnown == null) anyKnown = n;
                if (n.OperationalStatus != OperationalStatus.Up) continue;
                if (up == null || Idx(n) == best) up = n;   // из нескольких — тот, куда идёт интернет
            }
            if (up != null) return up;
            // незнакомый клиент: интернет уходит в адаптер без MAC — это туннель
            var bn = all.FirstOrDefault(n => n.OperationalStatus == OperationalStatus.Up && Idx(n) == best);
            if (bn != null && bn.NetworkInterfaceType != NetworkInterfaceType.Loopback && !Regex.IsMatch(bn.Name + " " + bn.Description, NotTunnel, RegexOptions.IgnoreCase))
            {
                byte[] mac = null;
                try { mac = bn.GetPhysicalAddress().GetAddressBytes(); } catch { }
                bool pppoe = Regex.IsMatch(bn.Name + " " + bn.Description, @"pppoe|высокоскоростн|broadband|широкополос", RegexOptions.IgnoreCase);   // PPPoE провайдера — не туннель
                if (!pppoe && (mac == null || mac.Length == 0 || mac.All(x => x == 0) || bn.NetworkInterfaceType == NetworkInterfaceType.Ppp || bn.NetworkInterfaceType == NetworkInterfaceType.Tunnel))
                    return bn;
            }
            return null;
        }

        // клиент в режиме системного прокси (Throne/Xray без TUN): адаптера нет, браузеры идут через 127.0.0.1
        public static string SystemProxy()
        {
            try
            {
                using (var k = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Internet Settings"))
                {
                    if (k == null) return null;
                    var en = k.GetValue("ProxyEnable");
                    if (en == null || Convert.ToInt32(en) == 0) return null;
                    string srv = (k.GetValue("ProxyServer") as string ?? "").Trim();
                    if (srv.Length == 0) return null;
                    var m = Regex.Match(srv, @"(?:^|[;=])((?:127\.\d+\.\d+\.\d+|localhost|\[::1\]):\d+)", RegexOptions.IgnoreCase);
                    return m.Success ? m.Groups[1].Value : null;   // внешний корпоративный прокси — не VPN
                }
            }
            catch { return null; }
        }
    }

    // ============================== ДНЕВНИК АУСПИКА ==============================
    // каждую минуту наблюдения — одна строка: сколько пингов ушло, сколько вернулось, средний и худший пинг, режим
    class AxMin { public DateTime When; public int Sent, Recv; public double Avg, Max, Jit; public int Mode; }   // Mode: 0 — напрямую, 1 — туннель, 2 — прокси

    static class AuspexLog
    {
        static string DirA { get { return Path.Combine(Store.Dir, "auspex"); } }
        static readonly object sync = new object();
        static DateTime cur = DateTime.MinValue;
        static int sent, recv, mode; static double sum, max, jit, prev = -1;
        static bool cleaned;

        public static void Add(double v, int m)
        {
            lock (sync)
            {
                var now = DateTime.Now; var minute = new DateTime(now.Year, now.Month, now.Day, now.Hour, now.Minute, 0);
                if (minute != cur) { FlushLocked(); cur = minute; sent = recv = 0; sum = max = jit = 0; }
                sent++; mode = m;
                if (v >= 0)
                {
                    recv++; sum += v; if (v > max) max = v;
                    if (prev >= 0) jit += Math.Abs(v - prev);
                }
                prev = v;
            }
        }

        public static void Flush() { lock (sync) { FlushLocked(); sent = 0; } }

        static void FlushLocked()
        {
            if (sent < 5 || cur == DateTime.MinValue) return;   // огрызки меньше 5 секунд не пишем
            try
            {
                Directory.CreateDirectory(DirA);
                string line = cur.ToString("yyyyMMdd HHmm", CultureInfo.InvariantCulture) + "\t" + sent + "\t" + recv + "\t" +
                    (recv > 0 ? (sum / recv).ToString("0.#", CultureInfo.InvariantCulture) : "-1") + "\t" + max.ToString("0", CultureInfo.InvariantCulture) + "\t" +
                    (recv > 1 ? (jit / Math.Max(1, recv - 1)).ToString("0.#", CultureInfo.InvariantCulture) : "0") + "\t" + mode;
                File.AppendAllText(Path.Combine(DirA, cur.ToString("yyyyMMdd") + ".tsv"), line + "\n");
                if (!cleaned)
                {
                    cleaned = true;
                    foreach (var f in Directory.GetFiles(DirA, "*.tsv"))
                    {
                        DateTime d;
                        if (DateTime.TryParseExact(Path.GetFileNameWithoutExtension(f), "yyyyMMdd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d) && (DateTime.Today - d).TotalDays > 90)
                            try { File.Delete(f); } catch { }
                    }
                }
            }
            catch { }
        }

        public static List<AxMin> Load(DateTime from, DateTime to)
        {
            var res = new List<AxMin>();
            try
            {
                if (!Directory.Exists(DirA)) return res;
                foreach (var f in Directory.GetFiles(DirA, "*.tsv").OrderBy(x => x))
                {
                    DateTime d;
                    if (!DateTime.TryParseExact(Path.GetFileNameWithoutExtension(f), "yyyyMMdd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) continue;
                    if (d < from.Date || d > to.Date) continue;
                    foreach (var line in File.ReadAllLines(f))
                    {
                        var c = line.Split(new[] { '\t' }); if (c.Length < 7) continue;
                        DateTime w;
                        if (!DateTime.TryParseExact(c[0], "yyyyMMdd HHmm", CultureInfo.InvariantCulture, DateTimeStyles.None, out w)) continue;
                        if (w < from || w > to) continue;
                        var m = new AxMin { When = w };
                        int.TryParse(c[1], out m.Sent); int.TryParse(c[2], out m.Recv);
                        double.TryParse(c[3], NumberStyles.Float, CultureInfo.InvariantCulture, out m.Avg);
                        double.TryParse(c[4], NumberStyles.Float, CultureInfo.InvariantCulture, out m.Max);
                        double.TryParse(c[5], NumberStyles.Float, CultureInfo.InvariantCulture, out m.Jit);
                        int.TryParse(c[6], out m.Mode);
                        if (m.Sent > 0) res.Add(m);
                    }
                }
            }
            catch { }
            return res;
        }
    }

    class AuspexData

    {
        public double Last = -2;            // -2 — ещё нет данных, -1 — нет ответа
        public double Loss, Jitter;
        public int MissStreak;
        public bool Vpn, Proxy;
        public List<double> Hist = new List<double>();
        public Color State
        {
            get
            {
                if (Last == -2) return Theme.GreenDim;
                if (MissStreak >= 3) return Theme.Red;
                if (Loss >= 3 || Last > 250) return Theme.Red;
                if (Loss > 0 || Last > 120 || Jitter > 30) return Theme.Amber;
                return Theme.Green;
            }
        }
    }

    // ---------- ползунок в духе когитатора ----------
    class CrtSlider : Control
    {
        public int Min = 25, Max = 100, Value = 90;
        public string Caption = "";
        public event Action Changed;
        bool drag;

        public CrtSlider()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
            BackColor = Theme.BgLog;
            Cursor = Cursors.Hand;
        }

        RectangleF Track { get { return new RectangleF(12, Height - 13, Width - 24, 4); } }

        void SetFromX(int x)
        {
            var t = Track;
            int v = (int)Math.Round((Min + (Max - Min) * Math.Max(0, Math.Min(1, (x - t.X) / t.Width))) / 5.0) * 5;
            v = Math.Max(Min, Math.Min(Max, v));
            if (v == Value) return;
            Value = v; Invalidate();
            if (Changed != null) Changed();
        }

        public void Nudge(int d)
        {
            int v = Math.Max(Min, Math.Min(Max, Value + d));
            if (v == Value) return;
            Value = v; Invalidate();
            if (Changed != null) Changed();
        }

        protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button == MouseButtons.Left) { drag = true; Capture = true; SetFromX(e.X); } }
        protected override void OnMouseMove(MouseEventArgs e) { base.OnMouseMove(e); if (drag) SetFromX(e.X); }
        protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); drag = false; Capture = false; }
        protected override void OnMouseWheel(MouseEventArgs e) { base.OnMouseWheel(e); Nudge(e.Delta > 0 ? 5 : -5); }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            Theme.Prep(g);
            using (var b = new SolidBrush(BackColor)) g.FillRectangle(b, ClientRectangle);
            var f = Theme.Mono(8.5f, FontStyle.Bold);
            using (var b = new SolidBrush(Theme.GreenMid)) g.DrawString(Caption, f, b, 10, 3);
            Theme.Glow(g, Value + "%", f, Theme.Orange, new RectangleF(0, 2, Width - 10, 16), Theme.Right);
            var t = Track;
            float k = (float)(Value - Min) / (Max - Min);
            float x = t.X + t.Width * k;
            // насечки через каждые 25%
            for (int v = Min; v <= Max; v += 25)
            {
                float tx = t.X + t.Width * (v - Min) / (Max - Min);
                Theme.Line(g, Theme.GreenDim, tx, t.Y - 4, tx, t.Bottom + 3, 1f);
            }
            using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, t);
            using (var b = new SolidBrush(Theme.Green)) g.FillRectangle(b, t.X, t.Y, x - t.X, t.Height);
            // ползун — ромб-печать
            var dm = new[] { new PointF(x, t.Y - 6), new PointF(x + 6, t.Y + 2), new PointF(x, t.Y + 10), new PointF(x - 6, t.Y + 2) };
            using (var b = new SolidBrush(Theme.Bg)) g.FillPolygon(b, dm);
            using (var pen = new Pen(Theme.Orange, 1.6f)) g.DrawPolygon(pen, dm);
        }
    }

    class OpacityPopup : Form
    {
        public CrtSlider Slider;
        public OpacityPopup()
        {
            FormBorderStyle = FormBorderStyle.None;
            ShowInTaskbar = false;
            TopMost = true;
            StartPosition = FormStartPosition.Manual;
            Size = new Size(240, 56);
            BackColor = Theme.BgLog;
            KeyPreview = true;
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint, true);
            Slider = new CrtSlider { Caption = Loc.T("ПЛОТНОСТЬ ОБРАЗА"), Bounds = new Rectangle(4, 8, 232, 42) };
            Controls.Add(Slider);
        }
        protected override CreateParams CreateParams { get { var cp = base.CreateParams; cp.ExStyle |= 0x80; return cp; } }   // не в Alt+Tab
        protected override void OnDeactivate(EventArgs e) { base.OnDeactivate(e); BeginInvoke((Action)Close); }   // клик мимо — закрыться
        protected override void OnKeyDown(KeyEventArgs e)
        {
            base.OnKeyDown(e);
            if (e.KeyCode == Keys.Escape || e.KeyCode == Keys.Enter) Close();
            else if (e.KeyCode == Keys.Left || e.KeyCode == Keys.Down) { Slider.Nudge(-5); e.Handled = true; }
            else if (e.KeyCode == Keys.Right || e.KeyCode == Keys.Up) { Slider.Nudge(5); e.Handled = true; }
        }
        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics; Theme.Prep(g);
            using (var b = new SolidBrush(BackColor)) g.FillRectangle(b, ClientRectangle);
            var r = new RectangleF(1, 1, Width - 3, Height - 3);
            Theme.Box(g, r, Theme.GreenMid, 1.4f);
            Theme.Line(g, Theme.Orange, r.X, r.Y, r.X + 8, r.Y, 1.8f); Theme.Line(g, Theme.Orange, r.X, r.Y, r.X, r.Y + 8, 1.8f);
            Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right - 8, r.Bottom, 1.8f); Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right, r.Bottom - 8, 1.8f);
        }
    }

    class AuspexForm : Form
    {
        [DllImport("user32.dll")] static extern bool ReleaseCapture();
        [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr h, int msg, IntPtr w, IntPtr l);

        public AuspexData Data = new AuspexData();
        public List<GateLive> Gates = new List<GateLive>();
        public event Action OpenRequested, HideRequested, Moved;

        public AuspexForm()
        {
            FormBorderStyle = FormBorderStyle.None;
            ShowInTaskbar = false;
            TopMost = true;
            StartPosition = FormStartPosition.Manual;
            Size = new Size(260, 92);
            BackColor = Theme.Bg;
            Opacity = Store.HudOpacity / 100.0;
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
            var menu = new ContextMenuStrip { Renderer = new ToolStripProfessionalRenderer(new CrtMenuColors()), ShowImageMargin = false, Font = Theme.Mono(9.5f, FontStyle.Bold) };
            var mo = new ToolStripMenuItem(Loc.T("ОТКРЫТЬ КОГИТАТОР")) { ForeColor = Theme.Green };
            mo.Click += (s, e) => { if (OpenRequested != null) OpenRequested(); };
            var mh = new ToolStripMenuItem(Loc.T("СКРЫТЬ АУСПИК")) { ForeColor = Theme.GreenMid };
            mh.Click += (s, e) => { if (HideRequested != null) HideRequested(); };
            var mp = new ToolStripMenuItem(Loc.T("ПЛОТНОСТЬ ОБРАЗА") + "…") { ForeColor = Theme.GreenMid };
            mp.Click += (s, e) => BeginInvoke((Action)ShowOpacityPopup);
            menu.Items.Add(mo); menu.Items.Add(mh); menu.Items.Add(new ToolStripSeparator()); menu.Items.Add(mp);
            ContextMenuStrip = menu;
            hintTimer = new System.Windows.Forms.Timer { Interval = 1200 };
            hintTimer.Tick += (s, e) => { hintTimer.Stop(); hint = false; Invalidate(); };
        }

        public CrtSlider Slider;
        Form opPopup;
        System.Windows.Forms.Timer hintTimer;

        // своё окошко с ползунком: в меню Windows ползунок не ловит мышь
        public void ShowOpacityPopup()
        {
            if (opPopup != null && !opPopup.IsDisposed) { opPopup.Close(); }
            var pf = new OpacityPopup();
            Slider = pf.Slider;
            Slider.Value = Store.HudOpacity;
            Slider.Changed += () => ApplyOpacity(Slider.Value);
            var sc = Screen.FromControl(this).WorkingArea;
            int x = Math.Max(sc.Left, Math.Min(sc.Right - pf.Width, Left + (Width - pf.Width) / 2));
            int y = Bottom + 6 + pf.Height <= sc.Bottom ? Bottom + 6 : Top - 6 - pf.Height;
            pf.Location = new Point(x, y);
            pf.FormClosed += (s, e) => { if (Slider == pf.Slider) Slider = null; };
            opPopup = pf;
            pf.Show();
            pf.Activate();
            pf.Slider.Focus();
        }
        bool hint;

        void ApplyOpacity(int v)
        {
            v = Math.Max(25, Math.Min(100, v));
            Store.HudOpacity = v;
            try { Opacity = v / 100.0; } catch { }
            Store.SaveSettings();
            hint = true; hintTimer.Stop(); hintTimer.Start(); Invalidate();
        }

        // колесо над плашкой — прозрачность
        protected override void OnMouseWheel(MouseEventArgs e)
        {
            base.OnMouseWheel(e);
            ApplyOpacity(Store.HudOpacity + (e.Delta > 0 ? 5 : -5));
            if (Slider != null) { Slider.Value = Store.HudOpacity; Slider.Invalidate(); }
        }

        // не появляется в Alt+Tab и не перехватывает фокус у игры
        protected override CreateParams CreateParams
        {
            get { var cp = base.CreateParams; cp.ExStyle |= 0x80 | 0x08000000 | 0x8; return cp; }
        }
        protected override bool ShowWithoutActivation { get { return true; } }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Left) return;
            try { ReleaseCapture(); SendMessage(Handle, 0xA1, (IntPtr)2, IntPtr.Zero); } catch { }   // перетаскивание за любое место
            if (Moved != null) Moved();
        }

        protected override void OnMouseDoubleClick(MouseEventArgs e) { base.OnMouseDoubleClick(e); if (OpenRequested != null) OpenRequested(); }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            Theme.Prep(g);
            var d = Data;
            Color st = d.State;
            using (var b = new SolidBrush(Theme.Bg)) g.FillRectangle(b, ClientRectangle);
            var r = new RectangleF(1, 1, Width - 3, Height - 3);
            Theme.Box(g, r, st, 1.6f);
            float k = 8;
            Theme.Line(g, Theme.Orange, r.X, r.Y, r.X + k, r.Y, 1.8f); Theme.Line(g, Theme.Orange, r.X, r.Y, r.X, r.Y + k, 1.8f);
            Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right - k, r.Bottom, 1.8f); Theme.Line(g, Theme.Orange, r.Right, r.Bottom, r.Right, r.Bottom - k, 1.8f);

            Theme.Glow(g, Loc.T("АУСПИК"), Theme.Mono(7.5f, FontStyle.Bold), Theme.Orange, 10, 6);
            using (var b = new SolidBrush(Theme.GreenDim))
                g.DrawString(d.Vpn ? Loc.T("ТУННЕЛЬ") : d.Proxy ? Loc.T("ПРОКСИ") : Loc.T("НАПРЯМУЮ"), Theme.Mono(7.5f, FontStyle.Bold), b, new RectangleF(0, 6, Width - 14, 14), Theme.Right);

            string big = d.Last == -2 ? "···" : d.MissStreak >= 3 ? Loc.T("НЕТ СВЯЗИ") : d.Last < 0 ? "×" : Math.Round(d.Last).ToString();
            var bf = d.MissStreak >= 3 ? Theme.Title(13f) : Theme.Title(20f);
            Theme.Glow(g, big, bf, st, new RectangleF(10, 18, 120, 34), Theme.Left);
            if (d.Last >= 0 && d.MissStreak < 3)
            {
                float bw = g.MeasureString(big, bf).Width;
                using (var b = new SolidBrush(Theme.GreenMid)) g.DrawString(Loc.T("МС"), Theme.Mono(8f, FontStyle.Bold), b, 12 + bw, 33);
            }
            var sf = Theme.Mono(8f, FontStyle.Bold);
            Color lc = d.Loss >= 3 ? Theme.Red : d.Loss > 0 ? Theme.Amber : Theme.Green;
            using (var b = new SolidBrush(Theme.GreenDim)) g.DrawString(Loc.T("ПОТЕРИ"), sf, b, new RectangleF(120, 22, Width - 130, 14), Theme.Right);
            Theme.Glow(g, d.Last == -2 ? "—" : Math.Round(d.Loss, 1).ToString(CultureInfo.InvariantCulture) + "%", Theme.Mono(10f, FontStyle.Bold), lc, new RectangleF(120, 34, Width - 130, 16), Theme.Right);

            // мини-график последних замеров
            var p = new RectangleF(10, 58, Width - 20, 92 - 66);
            using (var pen = new Pen(Color.FromArgb(50, Theme.GreenDim))) g.DrawLine(pen, p.X, p.Bottom, p.Right, p.Bottom);
            List<double> h; lock (d.Hist) h = new List<double>(d.Hist);
            if (h.Count > 1)
            {
                double top = Math.Max(60, h.Where(v => v >= 0).DefaultIfEmpty(0).Max() * 1.2);
                float step = p.Width / 59f;
                var seg = new List<PointF>();
                for (int i = 0; i < h.Count; i++)
                {
                    float x = p.Right - (h.Count - 1 - i) * step;
                    if (h[i] < 0)
                    {
                        if (seg.Count > 1) using (var pen = new Pen(Theme.Green, 1.3f)) g.DrawLines(pen, seg.ToArray());
                        seg.Clear();
                        Theme.Line(g, Theme.Red, x, p.Bottom, x, p.Y + 2, 1.4f);
                    }
                    else seg.Add(new PointF(x, p.Bottom - (float)(p.Height * Math.Min(1, h[i] / top))));
                }
                if (seg.Count > 1) using (var pen = new Pen(Theme.Green, 1.3f)) g.DrawLines(pen, seg.ToArray());
            }

            // строки своих врат
            var gls = Gates;
            if (gls != null && gls.Count > 0 && Height > 100)
            {
                Theme.Line(g, Theme.GreenDim, 10, 94, Width - 10, 94, 1f);
                for (int gi = 0; gi < gls.Count; gi++)
                {
                    var gl = gls[gi];
                    float y0 = 98 + gi * 22;
                    List<double> gh; lock (gl.Hist) gh = new List<double>(gl.Hist);
                    var okv = gh.Skip(Math.Max(0, gh.Count - 5)).Where(x => x >= 0).OrderBy(x => x).ToList();
                    double shown = okv.Count > 0 ? okv[okv.Count / 2] : -1;   // медиана последних замеров — без скачков
                    int fails = gh.Count(x => x < 0);
                    Color gc = gl.Last == -2 ? Theme.GreenDim : gl.Last < 0 ? Theme.Red : (fails * 3 >= Math.Max(1, gh.Count) || shown > 300) ? Theme.Amber : Theme.Green;
                    Theme.Glow(g, gl.Name.ToUpperInvariant(), Theme.Mono(7.5f, FontStyle.Bold), Theme.Orange, new RectangleF(10, y0 + 3, 92, 16), Ui.NoWrap);
                    string val = gl.Last == -2 ? "···" : gl.Last < 0 ? Loc.T("ЗАПЕЧАТАНЫ") : Math.Round(shown) + " " + Loc.T("МС");
                    Theme.Glow(g, val, Theme.Mono(9f, FontStyle.Bold), gc, new RectangleF(Width - 92, y0 + 2, 82, 18), Theme.Right);
                    for (int i = 0; i < 8; i++)
                    {
                        int idx = gh.Count - 8 + i;
                        float x = 108 + i * 8, y = y0 + 11;
                        if (idx < 0) { using (var b = new SolidBrush(Color.FromArgb(40, Theme.GreenDim))) g.FillEllipse(b, x - 2, y - 2, 4, 4); continue; }
                        double v = gh[idx];
                        Color dc = v < 0 ? Theme.Red : v > 300 ? Theme.Amber : Theme.Green;
                        using (var b = new SolidBrush(dc)) g.FillEllipse(b, x - 3, y - 3, 6, 6);
                    }
                }
            }
            if (hint)
            {
                var hr = new RectangleF(10, 58, Width - 20, 26);
                using (var b = new SolidBrush(Color.FromArgb(235, Theme.Bg))) g.FillRectangle(b, hr);
                Theme.Box(g, hr, Theme.Orange, 1.2f);
                float fw = (hr.Width - 70) * (Store.HudOpacity - 25) / 75f;
                using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, hr.X + 8, hr.Y + 11, hr.Width - 70, 4);
                using (var b = new SolidBrush(Theme.Green)) g.FillRectangle(b, hr.X + 8, hr.Y + 11, fw, 4);
                Theme.Glow(g, Store.HudOpacity + "%", Theme.Mono(9f, FontStyle.Bold), Theme.Orange, new RectangleF(hr.Right - 58, hr.Y + 4, 50, 18), Theme.Right);
            }
            Theme.Overlay(g, ClientRectangle, 0, 0);
        }
    }

    // ============================== ВРАТА: СВОИ ПРОВЕРКИ ==============================
    class Gate
    {
        public string Name = "", Target = "", SpeedUrl = "";
        public int Kind;   // 0 — HTTPS, 1 — TCP, 2 — PING
        // результат последней проверки
        public string Status, Detail;
        public char Key = ' ';
        public DateTime At;
        public Color StatusColor { get { return Key == 'g' ? Theme.Green : Key == 'a' ? Theme.Amber : Key == 'r' ? Theme.Red : Theme.GreenDim; } }
        public static readonly string[] Kinds = { "HTTPS", "TCP", "PING" };
    }

    class GateResult { public char Key; public string Status, Detail, LogLine; }

    static class GateCheck
    {
        [DllImport("iphlpapi.dll")] static extern int GetBestInterface(uint dwDestAddr, out uint idx);

        public static readonly object[][] Presets =
        {
            new object[] { "Discord", 0, "https://discord.com/api/v10/gateway", "" },
            new object[] { "Discord CDN", 0, "https://cdn.discordapp.com", "" },
            new object[] { "YouTube", 0, "https://www.youtube.com/generate_204", "" },
            new object[] { "YouTube · " + Loc.T("видеосерверы"), 0, "https://redirector.googlevideo.com/report_mapping", "" },
            new object[] { "Telegram", 0, "https://api.telegram.org", "" },
            new object[] { "Telegram DC", 1, "149.154.167.51:443", "" },
            new object[] { "Twitch", 0, "https://www.twitch.tv", "" },
            new object[] { "Steam", 0, "https://store.steampowered.com", "" },
            new object[] { "WhatsApp", 0, "https://web.whatsapp.com", "" },
            new object[] { "ChatGPT", 0, "https://chatgpt.com", "" },
            new object[] { "Cloudflare · " + Loc.T("контроль"), 0, "https://www.cloudflare.com/cdn-cgi/trace", "https://speed.cloudflare.com/__down?bytes=2500000" }
        };

        // разбор адреса под любой род проверки: принимает и https://host/path, и host:port, и просто host
        public static void Split(Gate g, out string host, out int port)
        {
            string t = (g.Target ?? "").Trim();
            host = t; port = 443;
            try
            {
                if (t.Contains("://"))
                {
                    var u = new Uri(t);
                    host = u.Host; port = u.IsDefaultPort ? (u.Scheme == "http" ? 80 : 443) : u.Port;
                    return;
                }
                int slash = t.IndexOf('/'); if (slash >= 0) t = t.Substring(0, slash);
                int c = t.LastIndexOf(':'); int p;
                if (c > 0 && t.IndexOf(':') == c && int.TryParse(t.Substring(c + 1), out p) && p > 0 && p < 65536) { host = t.Substring(0, c); port = p; }
                else host = t;
            }
            catch { }
        }

        public static string HostOf(Gate g) { string h; int p; Split(g, out h, out p); return h; }

        // как показать адрес в поле при смене рода проверки
        public static string Convert(string target, int kind)
        {
            string h; int p;
            Split(new Gate { Target = target }, out h, out p);
            if (string.IsNullOrEmpty(h)) return target;
            if (kind == 0) return "https://" + h + (p != 443 ? ":" + p : "");
            if (kind == 1) return h + ":" + p;
            return h;
        }

        public static string Resolve(string h)
        {
            if (string.IsNullOrEmpty(h)) return null;
            IPAddress a;
            if (IPAddress.TryParse(h, out a)) return a.ToString();
            try
            {
                var t = Task.Run(() => Dns.GetHostAddresses(h));
                if (!t.Wait(4000)) return null;
                var ip = t.Result.FirstOrDefault(x => x.AddressFamily == AddressFamily.InterNetwork);
                return ip == null ? null : ip.ToString();
            }
            catch { return null; }
        }

        // через туннель или напрямую пойдёт трафик к этому адресу
        public static string Route(string ip, string pattern)
        {
            if (ip == null) return null;
            try
            {
                var vpn = Tun.Find(pattern);
                if (vpn == null) return Tun.SystemProxy() != null ? Loc.T("напрямую (клиент в режиме прокси — туннеля нет)") : Loc.T("напрямую (VPN выключен)");
                int vIdx = vpn.GetIPProperties().GetIPv4Properties().Index;
                uint idx;
                if (GetBestInterface(BitConverter.ToUInt32(IPAddress.Parse(ip).GetAddressBytes(), 0), out idx) == 0)
                    return (int)idx == vIdx ? Loc.T("через туннель") : Loc.T("мимо туннеля");
            }
            catch { }
            return null;
        }

        static readonly string TlsCut = Loc.T("обрыв на рукопожатии TLS — так выглядит блокировка по имени сервиса (SNI)");

        // одна попытка. Возвращает время установки соединения (это и есть «пинг» до сервиса) или -1.
        // Для HTTPS дополнительно проходит рукопожатие TLS с именем сервиса — по нему ТСПУ и режет.
        public static double Probe(Gate g, string ip, int timeout, out string why, out double tlsMs, out bool certBad)
        {
            why = null; tlsMs = -1; certBad = false;
            string host; int port;
            Split(g, out host, out port);
            try
            {
                if (g.Kind == 2)
                {
                    using (var p = new Ping())
                    {
                        var r = p.Send(ip ?? host, timeout);
                        if (r.Status == IPStatus.Success) return r.RoundtripTime;
                        why = Loc.T("нет ответа на ping (многие сервисы его не пропускают — тогда лучше TCP)");
                        return -1;
                    }
                }
                if (ip == null) { why = Loc.T("имя не разрешается (DNS)"); return -1; }
                var c = new TcpClient();
                try
                {
                    var sw = Stopwatch.StartNew();
                    var ar = c.BeginConnect(ip, port, null, null);
                    if (!ar.AsyncWaitHandle.WaitOne(timeout)) { why = Loc.T("тишина: соединение не установлено (таймаут)"); return -1; }
                    c.EndConnect(ar);
                    double rtt = sw.ElapsedMilliseconds;
                    if (g.Kind == 1) return rtt;

                    bool bad = false;
                    var ssl = new SslStream(c.GetStream(), false, (s, cert, chain, err) => { bad = err != SslPolicyErrors.None; return true; });
                    var sw2 = Stopwatch.StartNew();
                    var ar2 = ssl.BeginAuthenticateAsClient(host, null, (SslProtocols)(3072 | 768), false, null, null);
                    if (!ar2.AsyncWaitHandle.WaitOne(timeout)) { why = TlsCut; return -1; }
                    try { ssl.EndAuthenticateAsClient(ar2); }
                    catch { why = TlsCut; return -1; }
                    tlsMs = sw2.ElapsedMilliseconds;
                    certBad = bad;
                    try { ssl.Dispose(); } catch { }
                    return rtt;
                }
                finally { try { c.Close(); } catch { } }
            }
            catch (SocketException) { why = Loc.T("соединение отвергнуто"); return -1; }
            catch (PingException) { why = Loc.T("имя не разрешается (DNS)"); return -1; }
            catch (Exception ex) { why = ex.Message; return -1; }
        }

        static double Speed(string url, out string note)
        {
            note = null;
            long bytes = 0; bool started = false;
            var sw = Stopwatch.StartNew();
            try
            {
                var req = (HttpWebRequest)WebRequest.Create(url);
                req.Timeout = 8000; req.ReadWriteTimeout = 5000; req.UserAgent = "Mozilla/5.0 Cogitator/1.0";
                using (var resp = req.GetResponse())
                using (var st = resp.GetResponseStream())
                {
                    started = true;
                    var buf = new byte[65536];
                    while (bytes < 2500000 && sw.Elapsed.TotalSeconds < 5)
                    {
                        int n = st.Read(buf, 0, buf.Length);
                        if (n <= 0) break;
                        bytes += n;
                    }
                }
            }
            catch { }
            double secs = Math.Max(0.001, sw.Elapsed.TotalSeconds);
            if (started && bytes < 128 * 1024) { note = Loc.T("поток замер после ") + (bytes / 1024) + Loc.T(" КБ"); return 0; }
            if (bytes < 64 * 1024) { note = Loc.T("замер скорости не удался"); return -1; }
            return Math.Round(bytes * 8 / secs / 1000000, 1);
        }

        public static GateResult Run(Gate g, string pattern, bool speedViaTunnel = false)
        {
            var res = new GateResult();
            string ip = Resolve(HostOf(g));
            string route = Route(ip, pattern);
            var times = new List<double>(); var tls = new List<double>(); string why = null; bool certBad = false;
            int tries = g.Kind == 2 ? 10 : 3;
            for (int i = 0; i < tries; i++)
            {
                string w; double t; bool cb;
                double ms = Probe(g, ip, g.Kind == 2 ? 1000 : 5000, out w, out t, out cb);
                if (ms >= 0) { times.Add(ms); if (t >= 0) tls.Add(t); if (cb) certBad = true; } else why = w;
                if (i == 0 && ms < 0 && g.Kind != 2 && ip == null) { tries = 1; break; }
                if (g.Kind == 2) Thread.Sleep(150);
            }
            int ok = times.Count, sent = tries;
            double avg = ok > 0 ? Math.Round(times.Average()) : -1;
            var parts = new List<string>();
            if (ok > 0) parts.Add(avg + Loc.T(" мс"));
            if (tls.Count > 0) parts.Add("TLS " + Math.Round(tls.Average()) + Loc.T(" мс"));
            if (g.Kind == 2) parts.Add(Loc.T("потери ") + Math.Round(100.0 * (sent - ok) / sent) + "%");
            else if (ok < sent && ok > 0) parts.Add(ok + "/" + sent + Loc.T(" попыток"));
            if (route != null) parts.Add(route);
            if (certBad) parts.Add(Loc.T("сертификат не прошёл проверку — возможна подмена трафика"));
            double speed = -1; string snote = null;
            bool tunnelRoute = route == Loc.T("через туннель");
            if (ok > 0 && !string.IsNullOrEmpty(g.SpeedUrl) && tunnelRoute && !speedViaTunnel) parts.Add(Loc.T("скорость через туннель меряется только при проверке выбранных врат"));
            else if (ok > 0 && !string.IsNullOrEmpty(g.SpeedUrl)) { speed = Speed(g.SpeedUrl, out snote); if (speed >= 0) parts.Add(speed + Loc.T(" Мбит/с")); if (snote != null) parts.Add(snote); }

            if (ok == 0)
            {
                res.Key = 'r'; res.Status = Loc.T("ЗАПЕЧАТАНЫ");
                if (why != null) parts.Insert(0, why);
            }
            else if (ok < sent || avg > 500 || (speed >= 0 && speed < 2) || snote != null || certBad)
            {
                res.Key = 'a'; res.Status = Loc.T("СКРИПЯТ");
                if (why != null && ok < sent) parts.Add(why);
            }
            else { res.Key = 'g'; res.Status = Loc.T("ОТКРЫТЫ"); }
            res.Detail = string.Join(" · ", parts);
            string tag = res.Key == 'g' ? Loc.T("[ ЧИСТО  ] ") : res.Key == 'a' ? Loc.T("[ТРЕВОГА ] ") : Loc.T("[ ЕРЕСЬ  ] ");
            res.LogLine = tag + g.Name + " (" + Gate.Kinds[g.Kind] + " " + g.Target + ") — " + res.Status + (res.Detail.Length > 0 ? " · " + res.Detail : "");
            return res;
        }
    }

    // ---------- переключатель вариантов ----------
    class ChipBar : CrtControl
    {
        public string[] Options = new string[0];
        public int Selected;
        public event Action Changed;
        int hover = -1;

        public ChipBar() { Height = 30; Cursor = Cursors.Hand; BackColor = Theme.Bg; }

        RectangleF Chip(int i) { float w = (Width - 2 - (Options.Length - 1) * 8f) / Math.Max(1, Options.Length); return new RectangleF(1 + i * (w + 8), 1, w, Height - 3); }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            int h = -1; for (int i = 0; i < Options.Length; i++) if (Chip(i).Contains(e.Location)) h = i;
            if (h != hover) { hover = h; Invalidate(); }
            base.OnMouseMove(e);
        }
        protected override void OnMouseLeave(EventArgs e) { hover = -1; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseClick(MouseEventArgs e)
        {
            for (int i = 0; i < Options.Length; i++)
                if (Chip(i).Contains(e.Location) && i != Selected) { Selected = i; Invalidate(); if (Changed != null) Changed(); }
            base.OnMouseClick(e);
        }

        protected override void PaintContent(Graphics g)
        {
            var f = Theme.Mono(9.5f, FontStyle.Bold);
            for (int i = 0; i < Options.Length; i++)
            {
                var r = Chip(i); bool sel = i == Selected, hov = i == hover;
                if (sel) using (var b = new SolidBrush(Theme.GreenDark)) g.FillRectangle(b, r);
                Theme.Box(g, r, sel ? Theme.Green : hov ? Theme.GreenMid : Theme.GreenDim, sel ? 1.5f : 1.1f);
                if (sel) Theme.Line(g, Theme.Orange, r.X + 5, r.Bottom - 3, r.Right - 5, r.Bottom - 3, 1.5f);
                Theme.Glow(g, Options[i], f, sel ? Theme.Green : Theme.GreenMid, r, Theme.Center);
            }
        }
    }

