        void AutoDetectAsync(bool manual)
        {
            if (autoBusy) return;
            autoBusy = true;
            if (bAuto != null) bAuto.Enabled = false;
            var th = new Thread(() =>
            {
                var log = new List<string>();
                List<AutoDetect.Found> found;
                try { found = AutoDetect.Run(log); }
                catch (Exception ex) { found = new List<AutoDetect.Found>(); log.Add(Loc.T("сбой: ") + ex.Message); }
                try { BeginInvoke(new Action(() => ApplyFound(found, log, manual))); } catch { }
            });
            th.IsBackground = true;
            th.Start();
        }

        string UniqueName(string name)
        {
            if (Store.Sanctums.All(x => x.Name != name)) return name;
            for (int i = 2; i < 50; i++) { var n = name + " " + ToRoman(i); if (Store.Sanctums.All(x => x.Name != n)) return n; }
            return name;
        }

        void ApplyFound(List<AutoDetect.Found> found, List<string> log, bool manual)
        {
            autoBusy = false;
            if (bAuto != null) bAuto.Enabled = true;
            var added = new List<Sanctum>();
            foreach (var f in found)
            {
                if (Store.Sanctums.Any(x => string.Equals(x.Addr, f.Host, StringComparison.OrdinalIgnoreCase))) continue;
                var s = new Sanctum
                {
                    Name = UniqueName(string.IsNullOrEmpty(f.Name) ? Loc.T("Авто · ") + f.Host : f.Name),
                    Addr = f.Host, Port = f.Port,
                    Note = Loc.T("найдено автоматически (") + (f.Source.StartsWith(Loc.T("реестр")) ? Loc.T("настройки Amnezia") : f.Source.StartsWith(Loc.T("служба")) ? Loc.T("служба туннеля") : Loc.T("файл конфигурации")) + ")"
                };
                Store.Sanctums.Add(s);
                added.Add(s);
            }
            if (added.Count > 0)
            {
                if (Store.Active.Length == 0) Store.Active = added[0].Addr;
                Store.SaveSanctums(); Store.SaveSettings();
                RefreshSanctList(); RefreshCombo(); RefreshHome();
                notice = Loc.T("НОВЫХ СВЯТИЛИЩ ВНЕСЕНО: ") + added.Count + " (" + string.Join(", ", added.Select(x => x.Addr)) + ")";
                IdleMessage();
                if (!running)
                    AppendParts(new[] { Loc.T("++ АВТОПОИСК: "), Loc.T("в реестр внесено ") + added.Count + " — " + string.Join(", ", added.Select(x => x.Name + " (" + x.Addr + ")")) },
                        new[] { Theme.Orange, Theme.Green }, false);
            }
            if (manual)
            {
                string msgText;
                if (found.Count == 0)
                    msgText = Loc.T("Святилищ в системе не найдено.\n\nПроверено: ") + string.Join(", ", log) +
                        Loc.T(".\n\nКлиент Amnezia, вероятно, хранит записи под шифром. Начертай адрес сам — он виден в клиенте под именем сервера.");
                else if (added.Count == 0)
                    msgText = Loc.T("Найдено святилищ: ") + found.Count + Loc.T(" — все уже есть в реестре.\n\n") + string.Join("\n", found.Select(f => "· " + f.Host));
                else
                    msgText = Loc.T("Найдено: ") + found.Count + Loc.T(", внесено новых: ") + added.Count + ".\n\n" + string.Join("\n", added.Select(x => "· " + x.Name + " — " + x.Addr + " (SSH " + x.Port + ")")) +
                        Loc.T("\n\nСверь имена и SSH-порты — их правят в форме справа.");
                MessageBox.Show(this, msgText, Loc.T("Автопоиск святилищ"), MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
        }

        CrtButton Small(string t) { return new CrtButton("", t, "") { Margin = new Padding(3, 4, 3, 4) }; }

        void DrawSanctItem(object sender, DrawItemEventArgs e)
        {
            if (e.Index < 0 || e.Index >= Store.Sanctums.Count) return;
            var g = e.Graphics; Theme.Prep(g);
            var s = Store.Sanctums[e.Index];
            bool sel = (e.State & DrawItemState.Selected) != 0;
            bool act = s.Addr == Store.Active;
            Ui.ItemFrame(g, e.Bounds, sel);
            var b = e.Bounds;
            float half = b.Height / 2f;
            string name = (act ? "» " : "  ") + s.Name.ToUpperInvariant() + (act ? Loc.T("   [АКТИВНО]") : "");
            using (var br = new SolidBrush(act ? Theme.Orange : Theme.Green))
                g.DrawString(name, Theme.Mono(10.5f, FontStyle.Bold), br, new RectangleF(b.X + 10, b.Y + 4, b.Width * 0.62f, half), Ui.NoWrap);
            var stR = new RectangleF(b.X + b.Width * 0.55f, b.Y + 4, b.Width * 0.45f - 12, half);
            if (sanctFx == null || !sanctFx.Draw(g, s, b, stR, Theme.Mono(9f, FontStyle.Bold), Ui.NoWrapRight))
                using (var br = new SolidBrush(s.Status == null ? Theme.GreenDim : s.StatusColor))
                    g.DrawString(s.Status ?? Loc.T("НЕ ОПРОШЕНО"), Theme.Mono(9f, FontStyle.Bold), br, stR, Ui.NoWrapRight);
            string sub = "   " + s.Addr + "  ·  SSH " + s.Port + (s.Note.Length > 0 ? "  ·  " + s.Note : "");
            using (var br = new SolidBrush(Theme.GreenMid))
                g.DrawString(sub, Theme.Mono(9f, FontStyle.Regular), br, new RectangleF(b.X + 10, b.Y + half - 2, b.Width - 20, half), Ui.NoWrap);
        }

        void RefreshSanctList()
        {
            int sel = sanctList.SelectedIndex;
            sanctList.BeginUpdate();
            sanctList.Items.Clear();
            foreach (var s in Store.Sanctums) sanctList.Items.Add(s);
            sanctList.EndUpdate();
            if (sel >= 0 && sel < sanctList.Items.Count) sanctList.SelectedIndex = sel;
            var a = Store.ActiveSanctum;
            sanctFrame.RightText = Loc.T("ВСЕГО: ") + Store.Sanctums.Count + Loc.T("  ·  АКТИВНО: ") + (a != null ? a.Name.ToUpperInvariant() : Loc.T("НЕТ"));
            sanctFrame.Invalidate();
        }

        void LoadSanctToForm()
        {
            int i = sanctList.SelectedIndex;
            if (i < 0 || i >= Store.Sanctums.Count) return;
            var s = Store.Sanctums[i];
            editIndex = i;
            fName.Box.Text = s.Name; fAddr.Box.Text = s.Addr; fPortS.Box.Text = s.Port.ToString(); fNote.Box.Text = s.Note;
        }

        void NewSanct()
        {
            editIndex = -1;
            sanctList.ClearSelected();
            fName.Box.Text = Loc.T("Святилище ") + ToRoman(Store.Sanctums.Count + 1);
            fAddr.Box.Text = ""; fPortS.Box.Text = "22"; fNote.Box.Text = "";
            fAddr.Box.Focus();
        }

        static string ToRoman(int n)
        {
            string[] r = { "", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII" };
            return n < r.Length ? r[n] : n.ToString();
        }

        void SaveSanct()
        {
            string addr = fAddr.Box.Text.Trim();
            if (addr.Length == 0) { MessageBox.Show(this, Loc.T("Впиши адрес святилища: IP или домен сервера."), Loc.T("Когитатор"), MessageBoxButtons.OK, MessageBoxIcon.Information); return; }
            int port; if (!int.TryParse(fPortS.Box.Text.Trim(), out port) || port < 1 || port > 65535) port = 22;
            string name = fName.Box.Text.Trim(); if (name.Length == 0) name = Loc.T("Святилище ") + ToRoman(Store.Sanctums.Count + 1);
            Sanctum s;
            if (editIndex >= 0 && editIndex < Store.Sanctums.Count)
            {
                s = Store.Sanctums[editIndex];
                if (s.Addr == Store.Active) Store.Active = addr;
                if (s.Addr != addr) s.Status = null;
            }
            else
            {
                if (Store.Sanctums.Any(x => x.Addr == addr)) { MessageBox.Show(this, Loc.T("Святилище с таким адресом уже есть в реестре."), Loc.T("Когитатор"), MessageBoxButtons.OK, MessageBoxIcon.Information); return; }
                s = new Sanctum(); Store.Sanctums.Add(s); editIndex = Store.Sanctums.Count - 1;
                if (Store.Active.Length == 0) Store.Active = addr;
            }
            s.Name = name; s.Addr = addr; s.Port = port; s.Note = fNote.Box.Text.Trim();
            Store.SaveSanctums(); Store.SaveSettings();
            RefreshSanctList(); sanctList.SelectedIndex = editIndex;
            RefreshCombo(); IdleMessage(); RefreshHome();
        }

        void DeleteSanct()
        {
            int i = sanctList.SelectedIndex;
            if (i < 0 || i >= Store.Sanctums.Count) return;
            var s = Store.Sanctums[i];
            if (MessageBox.Show(this, Loc.T("Изгнать святилище «") + s.Name + Loc.T("» из реестра?"), Loc.T("Когитатор"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
            Store.Sanctums.RemoveAt(i);
            if (s.Addr == Store.Active) Store.Active = Store.Sanctums.Count > 0 ? Store.Sanctums[0].Addr : "";
            Store.SaveSanctums(); Store.SaveSettings();
            editIndex = -1;
            RefreshSanctList(); RefreshCombo(); IdleMessage(); RefreshHome();
        }

        void MakeActive()
        {
            int i = sanctList.SelectedIndex;
            if (i < 0 || i >= Store.Sanctums.Count) return;
            Store.Active = Store.Sanctums[i].Addr;
            Store.SaveSettings();
            RefreshSanctList(); RefreshCombo(); IdleMessage(); RefreshHome();
        }

        RowFx sanctFx, gateFx;

        void ProbeAll()
        {
            if (Store.Sanctums.Count == 0) return;
            bProbe.Enabled = false;
            var list = Store.Sanctums.ToList();
            foreach (var s in list) { s.Status = Loc.T("ОПРОС..."); s.StatusColor = Theme.Orange; sanctFx.Queue(s); }
            sanctList.Invalidate();
            var th = new Thread(() =>
            {
                Diag.NoSample = true;
                foreach (var s in list)
                {
                    var cur = s;
                    try { BeginInvoke(new Action(() => sanctFx.Probe(cur))); } catch { }
                    Color c;
                    string st = new Diag(s.Addr, s.Port, Store.Pattern, Store.Isp, (k, t) => { }, t => { }).Probe(out c);
                    s.Status = st; s.StatusColor = c;
                    try { BeginInvoke(new Action(() => sanctFx.Result(cur, st, c))); } catch { }
                }
                try { BeginInvoke(new Action(() => { bProbe.Enabled = true; })); } catch { }
            });
            th.IsBackground = true;
            th.Start();
        }

        // ================= СТРАНИЦА: ВРАТА =================
        FramePanel gateFrame;
        ListBox gateList;
        CrtField gName, gTarget, gSpeed;
        ChipBar gKind;
        Label gTargetCap;
        CrtButton gCheckAll, gCheckOne, gAuspexBtn;
        int gateEdit = -1;
        bool gatesBusy;

        static readonly string[] TargetHints =
        {
            Loc.T("АДРЕС: https://… (САЙТ ИЛИ API СЕРВИСА)"),
            Loc.T("ХОСТ:ПОРТ (НАПРИМЕР, ИГРОВОЙ СЕРВЕР)"),
            Loc.T("ХОСТ ИЛИ IP")
        };

        Control BuildGates()
        {
            var page = new PagePanel { Dock = DockStyle.Fill, Padding = new Padding(10, 6, 10, 10) };
            gateFrame = new FramePanel(Loc.T("РЕЕСТР ВРАТ"), true) { Dock = DockStyle.Fill };
            gateList = Ui.MakeList(56);
            gateList.DrawItem += DrawGateItem;
            gateFx = new RowFx(gateList, o => Store.Gates.IndexOf((Gate)o), DrawGateItem);
            gateList.SelectedIndexChanged += (s, e) => LoadGateToForm();
            gateFrame.Controls.Add(new CrtScrollHost(gateList));

            var right = new Panel { Dock = DockStyle.Right, Width = 440, Padding = new Padding(16, 6, 6, 6), BackColor = Color.Transparent };
            var form = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 290, FlowDirection = FlowDirection.TopDown, WrapContents = false, BackColor = Color.Transparent };
            gName = new CrtField(400); gTarget = new CrtField(400); gSpeed = new CrtField(400);
            gKind = new ChipBar { Width = 400, Options = Gate.Kinds, Margin = new Padding(0, 0, 0, 6) };
            gTargetCap = Ui.Caption(TargetHints[0]);
            gKind.Changed += () => { gTargetCap.Text = TargetHints[gKind.Selected]; gSpeed.Enabled = gKind.Selected == 0; if (gTarget.Box.Text.Trim().Length > 0 && gTarget.Box.Text.Trim() != "https://") gTarget.Box.Text = GateCheck.Convert(gTarget.Box.Text, gKind.Selected); };
            form.Controls.Add(Ui.Caption(Loc.T("ИМЯ ВРАТ")));
            form.Controls.Add(gName);
            form.Controls.Add(Ui.Caption(Loc.T("РОД ПРОВЕРКИ")));
            form.Controls.Add(gKind);
            form.Controls.Add(gTargetCap);
            form.Controls.Add(gTarget);
            form.Controls.Add(Ui.Caption(Loc.T("ЗАМЕР СКОРОСТИ: URL ФАЙЛА (НЕОБЯЗАТЕЛЬНО)")));
            form.Controls.Add(gSpeed);

            var grid = new TableLayoutPanel { Dock = DockStyle.Top, Height = 4 * 50, ColumnCount = 2, RowCount = 4, BackColor = Color.Transparent };
            grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50f));
            grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50f));
            for (int i = 0; i < 4; i++) grid.RowStyles.Add(new RowStyle(SizeType.Percent, 25f));
            var bNew = Small(Loc.T("НОВЫЕ ВРАТА")); bNew.Click += (s, e) => NewGate();
            var bSave = Small(Loc.T("СОХРАНИТЬ")); bSave.Click += (s, e) => SaveGate();
            var bPre = Small(Loc.T("ПРЕСЕТЫ  ▾")); bPre.Click += (s, e) => ShowPresets(bPre);
            var bDel = Small(Loc.T("УДАЛИТЬ")); bDel.Click += (s, e) => DeleteGate();
            gCheckOne = Small(Loc.T("ПРОВЕРИТЬ ВЫБРАННЫЕ")); gCheckOne.Click += (s, e) => { int i = gateList.SelectedIndex; if (i >= 0 && i < Store.Gates.Count) CheckGates(new List<Gate> { Store.Gates[i] }, false); };
            gCheckAll = Small(Loc.T("ПРОВЕРИТЬ ВСЕ ВРАТА")); gCheckAll.Click += (s, e) => CheckGates(Store.Gates.ToList(), true);
            gAuspexBtn = Small(Loc.T("◉ ВЫВЕСТИ В АУСПИК")); gAuspexBtn.Click += (s, e) => ToggleGateAuspex();
            grid.Controls.Add(bNew, 0, 0); grid.Controls.Add(bSave, 1, 0);
            grid.Controls.Add(bPre, 0, 1); grid.Controls.Add(bDel, 1, 1);
            grid.Controls.Add(gCheckOne, 0, 2); grid.Controls.Add(gCheckAll, 1, 2);
            grid.Controls.Add(gAuspexBtn, 0, 3); grid.SetColumnSpan(gAuspexBtn, 2);

            var help = new MessagePanel { Dock = DockStyle.Fill, BackColor = Theme.Bg };
            help.Set(
                Loc.T("++ НАСТАВЛЕНИЕ ++"), Theme.Orange,
                Loc.T("ВРАТА — ДАЛЬНИЕ ТВЕРДЫНИ: DISCORD, YOUTUBE, ИГРОВЫЕ МИРЫ. ОБЩИЙ ПИНГ СЛЕП, КОГДА ПРОВАЙДЕР ДУШИТ ОДНУ ИЗ НИХ, — ВРАТА ЗРЯТ."), Theme.Green,
                Loc.T("HTTPS — СОЕДИНЕНИЕ С ИМЕНЕМ СЕРВИСА: ЛОВИТ БЛОКИРОВКУ ПО SNI. TCP — ХОСТ:ПОРТ. PING — ОБЫЧНЫЙ ПИНГ С ПОТЕРЯМИ."), Theme.GreenMid,
                Loc.T("«ВЫВЕСТИ В АУСПИК» — ВРАТА ВСТАНУТ ОТДЕЛЬНОЙ СТРОКОЙ ПОД ОКОМ АУСПИКА."), Theme.GreenMid);

            right.Controls.Add(help);
            right.Controls.Add(grid);
            right.Controls.Add(form);
            page.Controls.Add(gateFrame);
            page.Controls.Add(right);
            return page;
        }

        void DrawGateItem(object sender, DrawItemEventArgs e)
        {
            if (e.Index < 0 || e.Index >= Store.Gates.Count) return;
            var g = e.Graphics; Theme.Prep(g);
            var gt = Store.Gates[e.Index];
            bool sel = (e.State & DrawItemState.Selected) != 0;
            Ui.ItemFrame(g, e.Bounds, sel);
            var b = e.Bounds; float half = b.Height / 2f;
            using (var br = new SolidBrush((gateFx != null ? gateFx.BarColor(gt) : null) ?? gt.StatusColor)) g.FillRectangle(br, b.X + 4, b.Y + 8, 4, b.Height - 16);
            bool aus = Store.AuspexGates.Contains(gt.Name);
            string title = gt.Name.ToUpperInvariant() + (aus ? Loc.T("   ◉ АУСПИК") : "");
            using (var br = new SolidBrush(aus ? Theme.Orange : Theme.Green))
                g.DrawString(title, Theme.Mono(10.5f, FontStyle.Bold), br, new RectangleF(b.X + 16, b.Y + 4, b.Width * 0.6f, half), Ui.NoWrap);
            string st = gt.Status == null ? Loc.T("НЕ ПРОВЕРЕНЫ") : gt.Status + "  ·  " + gt.At.ToString("HH:mm");
            var stR = new RectangleF(b.X + b.Width * 0.5f, b.Y + 4, b.Width * 0.5f - 12, half);
            if (gateFx == null || !gateFx.Draw(g, gt, b, stR, Theme.Mono(9f, FontStyle.Bold), Ui.NoWrapRight))
                using (var br = new SolidBrush(gt.Status == null ? Theme.GreenDim : gt.StatusColor))
                    g.DrawString(st, Theme.Mono(9f, FontStyle.Bold), br, stR, Ui.NoWrapRight);
            bool hidden = gateFx != null && gateFx.BarColor(gt) != null;   // подробности — только после раскрытия итога
            string sub = Gate.Kinds[gt.Kind] + "  ·  " + gt.Target + (string.IsNullOrEmpty(gt.Detail) || hidden ? "" : "  ·  " + gt.Detail);
            using (var br = new SolidBrush(Theme.GreenMid))
                g.DrawString(sub, Theme.Mono(9f, FontStyle.Regular), br, new RectangleF(b.X + 16, b.Y + half - 2, b.Width - 26, half), Ui.NoWrap);
        }

        void RefreshGateList()
        {
            int sel = gateList.SelectedIndex;
            gateList.BeginUpdate();
            gateList.Items.Clear();
            foreach (var gt in Store.Gates) gateList.Items.Add(gt);
            gateList.EndUpdate();
            if (sel >= 0 && sel < gateList.Items.Count && currentPage == 4) gateList.SelectedIndex = sel;
            int r = Store.Gates.Count(x => x.Key == 'r'), a = Store.Gates.Count(x => x.Key == 'a');
            gateFrame.RightText = Loc.T("ВРАТ: ") + Store.Gates.Count + (r + a > 0 ? Loc.T("  ·  ЗАПЕЧАТАНО: ") + r + Loc.T("  ·  СКРИПЯТ: ") + a : "");
            gateFrame.Invalidate();
            UpdateGateAuspexBtn();
        }

        void LoadGateToForm()
        {
            int i = gateList.SelectedIndex;
            if (i < 0 || i >= Store.Gates.Count) return;
            var gt = Store.Gates[i];
            gateEdit = i;
            gName.Box.Text = gt.Name; gTarget.Box.Text = gt.Target; gSpeed.Box.Text = gt.SpeedUrl;
            gKind.Selected = gt.Kind; gKind.Invalidate();
            gTargetCap.Text = TargetHints[gt.Kind]; gSpeed.Enabled = gt.Kind == 0;
            UpdateGateAuspexBtn();
        }

        void NewGate()
        {
            gateEdit = -1;
            gateList.ClearSelected();
            gName.Box.Text = ""; gTarget.Box.Text = "https://"; gSpeed.Box.Text = "";
            gKind.Selected = 0; gKind.Invalidate(); gTargetCap.Text = TargetHints[0]; gSpeed.Enabled = true;
            gName.Box.Focus();
            UpdateGateAuspexBtn();
        }

        void SaveGate()
        {
            string name = gName.Box.Text.Trim(), target = gTarget.Box.Text.Trim();
            if (name.Length == 0 || target.Length == 0 || target == "https://")
            {
                MessageBox.Show(this, Loc.T("Впиши имя врат и адрес проверки."), "Cogitator", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            if (Store.Gates.Where((x, idx) => idx != gateEdit).Any(x => x.Name == name))
            {
                MessageBox.Show(this, Loc.T("Врата с таким именем уже есть."), "Cogitator", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            Gate gt;
            if (gateEdit >= 0 && gateEdit < Store.Gates.Count)
            {
                gt = Store.Gates[gateEdit];
                int ai = Store.AuspexGates.IndexOf(gt.Name); if (ai >= 0) Store.AuspexGates[ai] = name;
                if (gt.Target != target || gt.Kind != gKind.Selected) { gt.Status = null; gt.Detail = null; gt.Key = ' '; }
            }
            else { gt = new Gate(); Store.Gates.Add(gt); gateEdit = Store.Gates.Count - 1; }
            gt.Name = name; gt.Target = target; gt.Kind = gKind.Selected; gt.SpeedUrl = gKind.Selected == 0 ? gSpeed.Box.Text.Trim() : "";
            Store.SaveGates(); Store.SaveSettings();
            RefreshGateList(); gateList.SelectedIndex = gateEdit;
            RestartGateWatch();
        }

        void DeleteGate()
        {
            int i = gateList.SelectedIndex;
            if (i < 0 || i >= Store.Gates.Count) return;
            var gt = Store.Gates[i];
            if (MessageBox.Show(this, Loc.T("Запечатать навсегда врата «") + gt.Name + Loc.T("» и убрать из реестра?"), "Cogitator", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
            Store.Gates.RemoveAt(i);
            if (Store.AuspexGates.Remove(gt.Name)) RestartGateWatch();
            Store.SaveGates(); Store.SaveSettings();
            gateEdit = -1;
            RefreshGateList();
        }

        void ShowPresets(Control anchor)
        {
            var menu = new ContextMenuStrip { Renderer = new ToolStripProfessionalRenderer(new CrtMenuColors()), ShowImageMargin = false, Font = Theme.Mono(9.5f, FontStyle.Bold) };
            foreach (var p in GateCheck.Presets)
            {
                var pr = p;
                string nm = (string)pr[0];
                bool exists = Store.Gates.Any(x => x.Name == nm);
                var it = new ToolStripMenuItem(nm.ToUpperInvariant() + "   ·   " + Gate.Kinds[(int)pr[1]] + (exists ? Loc.T("   (УЖЕ ЕСТЬ)") : "")) { ForeColor = exists ? Theme.GreenDim : Theme.Green, Enabled = !exists };
                it.Click += (s, e) =>
                {
                    Store.Gates.Add(new Gate { Name = nm, Kind = (int)pr[1], Target = (string)pr[2], SpeedUrl = (string)pr[3] });
                    Store.SaveGates();
                    RefreshGateList();
                    gateList.SelectedIndex = Store.Gates.Count - 1;
                };
                menu.Items.Add(it);
            }
            menu.Show(anchor, new Point(0, anchor.Height));
        }

        void UpdateGateAuspexBtn()
        {
            if (gAuspexBtn == null) return;
            int i = gateList.SelectedIndex;
            bool isA = i >= 0 && i < Store.Gates.Count && Store.AuspexGates.Contains(Store.Gates[i].Name);
            gAuspexBtn.Title = isA ? Loc.T("◎ УБРАТЬ ИЗ АУСПИКА") : Loc.T("◉ ВЫВЕСТИ В АУСПИК");
            gAuspexBtn.Invalidate();
        }

        void ToggleGateAuspex()
        {
            int i = gateList.SelectedIndex;
            if (i < 0 || i >= Store.Gates.Count) { MessageBox.Show(this, Loc.T("Выбери врата в списке слева."), "Cogitator", MessageBoxButtons.OK, MessageBoxIcon.Information); return; }
            var gt = Store.Gates[i];
            if (!Store.AuspexGates.Remove(gt.Name))
            {
                if (Store.AuspexGates.Count >= Store.MaxAuspexGates)
                {
                    MessageBox.Show(this, Loc.T("Око ауспика вмещает не больше четырёх врат. Убери одни, чтобы вывести другие."), "Cogitator", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }
                Store.AuspexGates.Add(gt.Name);
            }
            Store.SaveSettings();
            gateList.Invalidate();
            UpdateGateAuspexBtn();
            if (Store.AuspexGates.Count > 0 && !Store.Hud) SetHud(true);
            RestartGateWatch();
        }

        void CheckGates(List<Gate> list, bool all)
        {
            if (gatesBusy || list.Count == 0) return;
            gatesBusy = true;
            gCheckAll.Enabled = false; gCheckOne.Enabled = false;
            foreach (var gt in list) { gt.Status = Loc.T("ПРОВЕРКА..."); gt.Key = ' '; gt.Detail = null; gateFx.Queue(gt); }
            gateList.Invalidate();
            string pattern = Store.Pattern;
            var t0g = DateTime.Now;
            var th = new Thread(() =>
            {
                var lines = new GateResult[list.Count];
                Parallel.For(0, list.Count, new ParallelOptions { MaxDegreeOfParallelism = 4 }, k =>
                {
                    GateResult r;
                    var cur = list[k];
                    try { BeginInvoke(new Action(() => gateFx.Probe(cur))); } catch { }
                    try { r = GateCheck.Run(list[k], pattern, !all); }
                    catch (Exception ex) { r = new GateResult { Key = 'r', Status = Loc.T("СБОЙ"), Detail = ex.Message, LogLine = Loc.T("[ ЕРЕСЬ  ] ") + list[k].Name + " — " + ex.Message }; }
                    lines[k] = r;
                    var gt = list[k];
                    try { BeginInvoke(new Action(() => { gt.Status = r.Status; gt.Detail = r.Detail; gt.Key = r.Key; gt.At = DateTime.Now; gateFx.Result(gt, gt.Status + "  ·  " + gt.At.ToString("HH:mm"), gt.StatusColor); })); } catch { }
                });
                try { BeginInvoke(new Action(() => FinishGates(list, lines, all, t0g))); } catch { }
            });
            th.IsBackground = true;
            th.Start();
        }

        void FinishGates(List<Gate> list, GateResult[] res, bool all, DateTime t0g)
        {
            gatesBusy = false;
            gCheckAll.Enabled = true; gCheckOne.Enabled = true;
            RefreshGateList();
            if (!all) return;
            int r = res.Count(x => x != null && x.Key == 'r'), a = res.Count(x => x != null && x.Key == 'a');
            string head = r == res.Length ? Loc.T("ВРАТА ЗАПЕЧАТАНЫ") : r > 0 ? Loc.T("ЧАСТЬ ВРАТ ЗАПЕЧАТАНА") : a > 0 ? Loc.T("ВРАТА СКРИПЯТ") : Loc.T("ВРАТА ОТКРЫТЫ");
            char key = r > 0 ? 'r' : a > 0 ? 'a' : 'g';
            var sealedNames = list.Where((g, i) => res[i] != null && res[i].Key == 'r').Select(g => g.Name).ToList();
            string side = r > 0 ? Loc.T("Не открываются: ") + string.Join(", ", sealedNames) : a > 0 ? Loc.T("Часть врат отвечает с трудом") : Loc.T("Все врата открыты");
            var sb = new StringBuilder();
            sb.AppendLine(Loc.T("++ ДОЗОР ВРАТ ++"));
            sb.AppendLine(t0g.ToString("dd.MM.yyyy HH:mm:ss") + "  ·  " + Environment.MachineName);
            sb.AppendLine("");
            foreach (var x in res) if (x != null) sb.AppendLine(x.LogLine);
            sb.AppendLine("");
            sb.AppendLine(Loc.T("++ ПРИГОВОР ++"));
            sb.AppendLine(">>> " + head + " <<<");
            sb.AppendLine(side);
            Store.AddChron(new ChronEntry { Id = t0g.ToString("yyyyMMdd-HHmmss"), When = t0g, Ritual = 6, Sanctum = "", Headline = head, Side = side, Key = key, Seconds = (int)(DateTime.Now - t0g).TotalSeconds }, sb.ToString());
            if (pages[3].Visible) RefreshChron();
            RefreshHome();
        }

        // ---- строка врат в ауспике ----
        int gateWatchGen;

        void RestartGateWatch()
        {
            gateWatchGen++;
            var list = Store.AuspexGates.Select(n => Store.Gates.FirstOrDefault(x => x.Name == n)).Where(x => x != null).ToList();
            if (list.Count == 0 || !Store.Hud) { if (hud != null) { hud.Gates = new List<GateLive>(); hud.Height = 92; hud.Invalidate(); } return; }
            var lives = list.Select(gt => new GateLive { Name = gt.Name }).ToList();
            if (hud != null) { hud.Gates = lives; hud.Height = 100 + lives.Count * 22; hud.Invalidate(); }
            int gen = gateWatchGen;
            for (int n = 0; n < list.Count; n++)
            {
                var gt = list[n]; var live = lives[n];
                var copy = new Gate { Name = gt.Name, Kind = gt.Kind, Target = gt.Target };
                var th = new Thread(() =>
                {
                    string gip = null; DateTime resolvedAt = DateTime.MinValue, tlsAt = DateTime.MinValue;
                    int interval = copy.Kind == 2 ? 1000 : 2000;
                    var tcpOnly = new Gate { Name = copy.Name, Kind = copy.Kind == 2 ? 2 : 1, Target = copy.Target };
                    bool tlsBad = false;
                    while (hudRun && gen == gateWatchGen)
                    {
                        var sw = Stopwatch.StartNew();
                        string why = null;
                        if (gip == null || (DateTime.Now - resolvedAt).TotalMinutes > 2) { gip = GateCheck.Resolve(GateCheck.HostOf(copy)); resolvedAt = DateTime.Now; }
                        double tlsMs; bool cb;
                        // сама задержка — голое соединение (как пинг), лучшее из трёх: одиночный замер ловит случайные задержки планировщика
                        double ms = -1;
                        for (int k = 0; k < (copy.Kind == 2 ? 1 : 3); k++)
                        {
                            string w; double v = GateCheck.Probe(tcpOnly, gip, 2000, out w, out tlsMs, out cb);
                            if (v >= 0 && (ms < 0 || v < ms)) ms = v;
                            if (v < 0) why = w;
                            if (v < 0 && k == 0) break;
                        }
                        // HTTPS: раз в 30 с — полное рукопожатие с именем сервиса, чтобы заметить блокировку по SNI
                        if (copy.Kind == 0 && ms >= 0 && (DateTime.Now - tlsAt).TotalSeconds >= 30)
                        {
                            tlsAt = DateTime.Now;
                            string w; tlsBad = GateCheck.Probe(copy, gip, 4000, out w, out tlsMs, out cb) < 0;
                            if (tlsBad) why = w;
                        }
                        if (tlsBad) ms = -1;
                        lock (live.Hist) { live.Hist.Add(ms); if (live.Hist.Count > 12) live.Hist.RemoveAt(0); }
                        live.Last = ms; live.Why = why;
                        try { BeginInvoke(new Action(() => { if (hud != null && gen == gateWatchGen) hud.Invalidate(); })); } catch { }
                        int rest = interval - (int)sw.ElapsedMilliseconds;
                        if (rest > 0) Thread.Sleep(rest);
                    }
                });
                th.IsBackground = true;
                th.Start();
            }
        }

