        void RefreshCombo()
        {
            suppressCombo = true;
            combo.Items.Clear();
            combo.Items.Add("-");
            int selIdx = 0;
            for (int i = 0; i < Store.Sanctums.Count; i++)
            {
                combo.Items.Add(Store.Sanctums[i]);
                if (Store.Sanctums[i].Addr == Store.Active) selIdx = i + 1;
            }
            combo.SelectedIndex = selIdx;
            suppressCombo = false;
        }

        void ComboChanged()
        {
            if (suppressCombo) return;
            var s = combo.SelectedItem as Sanctum;
            Store.Active = s != null ? s.Addr : "";
            Store.SaveSettings();
            RefreshSanctList(); IdleMessage(); RefreshHome();
        }

