        void ToggleSummary()
        {
            bool show = !summary.Visible;
            Curtain(show ? Loc.T("СВОДКА ЛЕТОПИСИ") : Loc.T("ЗАПИСИ ЛЕТОПИСИ"), () =>
            {
                if (show) summary.Rebuild();
                summary.Visible = show;
                chronTable.Visible = !show;
                bSumm.Title = show ? Loc.T("К ЗАПИСЯМ") : Loc.T("СВОДКА");
                bSumm.Invalidate();
            });
