        void DrawChronItem(object sender, DrawItemEventArgs e)
        {
            if (e.Index < 0 || e.Index >= chronList.Items.Count) return;
            var en = chronList.Items[e.Index] as ChronEntry;
            if (en == null) return;
            var g = e.Graphics; Theme.Prep(g);
            bool sel = (e.State & DrawItemState.Selected) != 0;
            Ui.ItemFrame(g, e.Bounds, sel);
            var b = e.Bounds;
            using (var br = new SolidBrush(en.Color)) g.FillRectangle(br, b.X + 4, b.Y + 8, 4, b.Height - 16);
            float half = b.Height / 2f;
            using (var br = new SolidBrush(Theme.GreenMid))
                g.DrawString(en.When.ToString("dd.MM HH:mm"), Theme.Mono(9f, FontStyle.Bold), br, new RectangleF(b.X + 16, b.Y + 4, 110, half), Ui.NoWrap);
            using (var br = new SolidBrush(Theme.Orange))
                g.DrawString(en.Ritual == 9 ? Loc.T("СТРАЖ") : en.Ritual == 6 ? Loc.T("ВРАТА") : Loc.T("РИТУАЛ ") + (en.Ritual >= 1 && en.Ritual <= 5 ? Nums[en.Ritual] : "?"), Theme.Mono(9f, FontStyle.Bold), br, new RectangleF(b.X + 124, b.Y + 4, 110, half), Ui.NoWrap);
            using (var br = new SolidBrush(Theme.Green))
                g.DrawString((en.Sanctum.Length > 0 ? en.Sanctum : Loc.T("без святилища")).ToUpperInvariant() + "  ·  " + en.Seconds + Loc.T(" С"), Theme.Mono(9f, FontStyle.Regular), br, new RectangleF(b.X + 230, b.Y + 4, b.Width - 240, half), Ui.NoWrap);
            using (var br = new SolidBrush(en.Color))
                g.DrawString(Loc.TH(en.Headline), Theme.Mono(10f, FontStyle.Bold), br, new RectangleF(b.X + 16, b.Y + half - 2, b.Width - 26, half), Ui.NoWrap);
        }

        void RefreshChron()
        {
            chronList.BeginUpdate();
            int diff = Store.Chronicle.Count - chronList.Items.Count;
            bool tail = diff > 0 && chronList.Items.Count > 0 && Store.Chronicle.Count > diff && ReferenceEquals(chronList.Items[0], Store.Chronicle[diff]);
            if (tail) for (int k = diff - 1; k >= 0; k--) chronList.Items.Insert(0, Store.Chronicle[k]);
            else { chronList.Items.Clear(); chronList.Items.AddRange(Store.Chronicle.Cast<object>().ToArray()); }
            chronList.EndUpdate();
            int r = Store.Chronicle.Count(x => x.Key == 'r'), a = Store.Chronicle.Count(x => x.Key == 'a'), gq = Store.Chronicle.Count(x => x.Key == 'g');
            if (summary != null && summary.Visible) summary.Rebuild();
            chronFrame.RightText = Loc.T("ЗАПИСЕЙ: ") + Store.Chronicle.Count;
            viewFrame.RightText = Loc.T("ЕРЕСЕЙ ") + r + Loc.T("  ·  ТРЕВОГ ") + a + Loc.T("  ·  ЧИСТЫХ ") + gq;
            chronFrame.Invalidate(); viewFrame.Invalidate();
            if (chronList.Items.Count > 0)
            {
                if (pages != null && pages[3].Visible) BeginInvoke(new Action(() => { if (chronList.Items.Count > 0) chronList.SelectedIndex = 0; }));
            }
            else
            {
                chronView.Clear();
                Colorize(chronView, Loc.T("++ ЛЕТОПИСЬ ПУСТА ++\nСоверши первое испытание — когитатор занесёт его сюда."));
            }
        }

        void ShowChron()
        {
            var en = chronList.SelectedItem as ChronEntry;
            if (en == null) return;
            chronView.Clear();
            Colorize(chronView, Store.ReadReport(en));
            chronView.SelectionStart = 0;
            chronView.ScrollToCaret();
        }

        static string RtfEsc(string t)
        {
            var sb = new StringBuilder(t.Length + 16);
            foreach (char ch in t)
            {
                if (ch == '\\' || ch == '{' || ch == '}') sb.Append('\\').Append(ch);
                else if (ch < 128) sb.Append(ch);
                else sb.Append("\\u").Append((int)(short)ch).Append('?');
            }
            return sb.ToString();
        }

        void Colorize(RichTextBox box, string text)
        {
            // цвета: 1 текст, 2 зелёный, 3 янтарь, 4 красный, 5 тусклый, 6 оранжевый
            var cols = new[] { Theme.Text, Theme.Green, Theme.Amber, Theme.Red, Theme.GreenMid, Theme.Orange };
            var sb = new StringBuilder(text.Length * 2 + 512);
            sb.Append("{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0\\fmodern ").Append(mono.Name).Append(";}}{\\colortbl ;");
            foreach (var c in cols) sb.Append("\\red").Append(c.R).Append("\\green").Append(c.G).Append("\\blue").Append(c.B).Append(';');
            sb.Append("}\\f0\\fs").Append((int)Math.Round(mono.SizeInPoints * 2)).Append(' ');
            foreach (var raw in text.Replace("\r", "").Split(new[] { '\n' }))
            {
                int c = 1; bool bold = false;
                if (Loc.Starts(raw, "[ ЧИСТО  ] ")) c = 2;
                else if (Loc.Starts(raw, "[ТРЕВОГА ] ")) c = 3;
                else if (Loc.Starts(raw, "[ ЕРЕСЬ  ] ")) c = 4;
                else if (Loc.Starts(raw, "[ ДАННЫЕ ] ") || Loc.Starts(raw, "[  УЗЕЛ  ] ")) c = 5;
                else if (raw.StartsWith("++")) { c = 6; bold = true; }
                else if (raw.StartsWith(">>>")) { c = 4; bold = true; }
                sb.Append("\\cf").Append(c).Append(bold ? "\\b " : "\\b0 ").Append(RtfEsc(raw)).Append("\\par\n");
            }
            sb.Append('}');
            try { box.Rtf = sb.ToString(); }
            catch { box.Text = text; }
        }

        void RepeatChron()
        {
            var en = chronList.SelectedItem as ChronEntry;
            if (en == null || running) return;
            if (en.Ritual == 6) { ShowPage(4); CheckGates(Store.Gates.ToList(), true); return; }
            var s = Store.Sanctums.FirstOrDefault(x => x.Name == en.Sanctum);
            if (s != null) { Store.Active = s.Addr; Store.SaveSettings(); RefreshCombo(); RefreshSanctList(); }
            ShowPage(2);
            StartRitual(en.Ritual == 9 ? 5 : en.Ritual >= 1 && en.Ritual <= 5 ? en.Ritual : 1);
        }

