        void RefreshHome()
        {
            var a = Store.ActiveSanctum;
            var last = Store.Chronicle.FirstOrDefault();
            home.Tiles[0].Stat = Loc.T("В РЕЕСТРЕ: ") + Store.Sanctums.Count + Loc.T("  ·  АКТИВНО: ") + (a != null ? a.Name.ToUpperInvariant() : Loc.T("НЕТ"));
            home.Tiles[0].StatColor = a != null ? Theme.GreenMid : Theme.Orange;
            if (running) { home.Tiles[1].Stat = Loc.T("ИДЁТ РИТУАЛ ") + Nums[curMode] + "..."; home.Tiles[1].StatColor = Theme.Orange; }
            else if (last != null) { home.Tiles[1].Stat = Loc.T("ПОСЛЕДНИЙ: ") + Loc.TH(last.Headline); home.Tiles[1].StatColor = last.Color; }
            else { home.Tiles[1].Stat = Loc.T("ИСПЫТАНИЙ ЕЩЁ НЕ БЫЛО"); home.Tiles[1].StatColor = Theme.GreenDim; }
            home.Tiles[2].Stat = Loc.T("ЗАПИСЕЙ: ") + Store.Chronicle.Count + Loc.T("  ·  ЕРЕСЕЙ: ") + Store.Chronicle.Count(x => x.Key == 'r');
            home.Tiles[2].StatColor = Theme.GreenMid;
            foreach (var t in home.Tiles) t.Invalidate();

            home.SetStatus(new[]
            {
                Loc.T("МАШИННЫЙ ДУХ: ") + (running ? Loc.T("СОВЕРШАЕТСЯ РИТУАЛ ") + Nums[curMode] : Loc.T("ОЖИДАЕТ ПРИКАЗА")),
                Loc.T("АКТИВНОЕ СВЯТИЛИЩЕ: ") + (a != null ? a.Name.ToUpperInvariant() + "  ·  " + a.Addr : Loc.T("НЕ ИЗБРАНО")),
                last != null ? Loc.T("ПОСЛЕДНИЙ ПРИГОВОР: ") + Loc.TH(last.Headline) + "  ·  " + last.When.ToString("dd.MM HH:mm") : Loc.T("ЛЕТОПИСЬ ПУСТА"),
                !Store.Guard ? Loc.T("СТРАЖ ДРЕМЛЕТ — ПРИЗОВИ ЕГО ЗНАКОМ ВВЕРХУ") : guardDown ? Loc.T("СТРАЖ: СВЯЗИ НЕТ С ") + downSince.ToString("HH:mm:ss") : Loc.T("СТРАЖ: НЕСЁТ СЛУЖБУ, ПРОВЕРКА КАЖДЫЕ 10 С")
            }, new[] { running ? Theme.Orange : Theme.Green, a != null ? Theme.Green : Theme.Orange, last != null ? last.Color : Theme.GreenDim,
                       !Store.Guard ? Theme.GreenDim : guardDown ? Theme.Red : Theme.Green });
        }

        static readonly string[] PageNames = { Loc.T("ГЛАВНЫЙ ТЕРМИНАЛ"), Loc.T("СВЯТИЛИЩА"), Loc.T("ИСПЫТАНИЯ"), Loc.T("ЛЕТОПИСЬ"), Loc.T("ВРАТА") };

        void ShowPage(int i)
        {
            if (i < 0 || i >= pages.Length) return;
            if (transTarget >= 0) { transQueued = i; return; }
            if (i == currentPage) return;
            transTarget = i; transSwitched = false; transAction = null;
            nav.Selected = i; nav.Invalidate();
            trans.Label = PageNames[i];
            trans.Open = 0; trans.Progress = 0;
            trans.Apply();
            trans.Visible = true;
            trans.BringToFront();
            transClock = Stopwatch.StartNew();
            transTimer.Start();
        }

        // тот же занавес, но для смены вида внутри страницы
        Action transAction;
        void Curtain(string label, Action act)
        {
            if (transTarget >= 0) return;
            transTarget = currentPage; transSwitched = false; transAction = act;
            trans.Label = label;
            trans.Open = 0; trans.Progress = 0;
            trans.Apply();
            trans.Visible = true;
            trans.BringToFront();
            transClock = Stopwatch.StartNew();
            transTimer.Start();
        }

        void TransSwitch()
        {
            transSwitched = true;
            if (transAction != null) { var a = transAction; transAction = null; a(); }
            else ShowPageNow(transTarget);          // страница строится под занавесом
            pages[currentPage].Update();
        }

        static float EaseOut(float t) { t = Math.Max(0, Math.Min(1, t)); return 1 - (1 - t) * (1 - t) * (1 - t); }
        static float EaseIn(float t) { t = Math.Max(0, Math.Min(1, t)); return t * t * t; }

        void TransTick()
        {
            long t = transClock.ElapsedMilliseconds;
            trans.Angle += 0.09f;
            if (t < TOpen)
            {
                trans.Open = EaseOut(t / (float)TOpen);
                trans.Progress = 0;
            }
            else if (t < TOpen + THold)
            {
                trans.Open = 1;
                if (!transSwitched) TransSwitch();
                trans.Progress = (t - TOpen) / (float)THold;
            }
            else if (t < TOpen + THold + TClose)
            {
                if (!transSwitched) TransSwitch();
                trans.Progress = 1;
                trans.Open = 1 - EaseIn((t - TOpen - THold) / (float)TClose);
            }
            else
            {
                transTimer.Stop();
                trans.Visible = false;
                transTarget = -1;
                if (transQueued >= 0) { int q = transQueued; transQueued = -1; if (q != currentPage) ShowPage(q); }
                return;
            }
            trans.Apply();
        }

        void ShowPageNow(int i)
        {
            if (combo != null) combo.ClosePopup();
            if (i < 0 || i >= pages.Length) return;
            currentPage = i;
            for (int k = 0; k < pages.Length; k++) pages[k].Visible = k == i;
            trans.BringToFront();
            nav.Selected = i; nav.Invalidate();
            if (i == 0) RefreshHome();
            if (i == 1 && sanctList.SelectedIndex < 0 && editIndex >= 0 && editIndex < sanctList.Items.Count)
                BeginInvoke(new Action(() => { sanctList.SelectedIndex = editIndex; }));
            if (i == 3)
            {
                if (chronList.Items.Count != Store.Chronicle.Count) RefreshChron();
                else if (chronList.SelectedIndex < 0 && chronList.Items.Count > 0)
                    BeginInvoke(new Action(() => { if (chronList.Items.Count > 0) chronList.SelectedIndex = 0; }));
            }
        }

        protected override void OnKeyDown(KeyEventArgs e)
        {
            if (e.Control)
            {
                int k = -1;
                if (e.KeyCode >= Keys.D1 && e.KeyCode <= Keys.D5) k = e.KeyCode - Keys.D1;
                else if (e.KeyCode >= Keys.NumPad1 && e.KeyCode <= Keys.NumPad5) k = e.KeyCode - Keys.NumPad1;
                if (k >= 0) { ShowPage(k); e.Handled = true; e.SuppressKeyPress = true; }
            }
            base.OnKeyDown(e);
        }

        // ================= ЖУРНАЛ =================
        class LogChunk { public string Text; public Color C; public bool Bold; }
        readonly List<LogChunk> logQueue = new List<LogChunk>();   // List, а не Queue: Queue в .NET Framework живёт в другой сборке
        System.Windows.Forms.Timer logTyper;
        bool typeLog;
        int logTick;

        void LogTyperTick()
        {
            if (logQueue.Count == 0 || IsDisposed) { logTyper.Stop(); return; }
            logTick++;
            int budget = 3 + (logTick % 5 == 0 ? 0 : 1);   // неровный темп телетайпа
            while (budget > 0 && logQueue.Count > 0)
            {
                var ch = logQueue[0];
                int n = Math.Min(budget, ch.Text.Length);
                log.SelectionStart = log.TextLength; log.SelectionLength = 0;
                log.SelectionColor = ch.C; log.SelectionFont = ch.Bold ? monoB : mono;
                log.AppendText(ch.Text.Substring(0, n));
                ch.Text = ch.Text.Substring(n); budget -= n;
                if (ch.Text.Length == 0) logQueue.RemoveAt(0);
            }
            log.SelectionStart = log.TextLength;
            log.ScrollToCaret();
        }

        void FlushLogTyper()
        {
            // новый ритуал или очистка — допечатать мгновенно не нужно, просто сбросить очередь
            logQueue.Clear(); if (logTyper != null) logTyper.Stop();
        }

        void AppendParts(string[] parts, Color[] colors, bool bold)
        {
            if (IsDisposed) return;
            if (InvokeRequired)
            {
                try { BeginInvoke(new Action(() => AppendParts(parts, colors, bold))); } catch { }
                return;
            }
            if (typeLog)
            {
                // приговор печатается посимвольно: в отчёт — сразу, на экран — по таймеру
                report.AppendLine(string.Concat(parts));
                for (int i = 0; i < parts.Length; i++) if (parts[i].Length > 0) logQueue.Add(new LogChunk { Text = parts[i], C = colors[i], Bold = bold });
                logQueue.Add(new LogChunk { Text = "\n", C = Theme.Text, Bold = false });
                if (!logTyper.Enabled) logTyper.Start();
                return;
            }
            var sb = new StringBuilder();
            for (int i = 0; i < parts.Length; i++)
            {
                log.SelectionStart = log.TextLength;
                log.SelectionLength = 0;
                log.SelectionColor = colors[i];
                log.SelectionFont = bold ? monoB : mono;
                log.AppendText(parts[i]);
                sb.Append(parts[i]);
            }
            log.AppendText("\n");
            log.SelectionStart = log.TextLength;
            log.ScrollToCaret();
            report.AppendLine(sb.ToString());
        }

        void LogLine(string kind, string text)
        {
            string tag; Color c, tc = Theme.Text;
            switch (kind)
            {
                case "ok": tag = Loc.T("[ ЧИСТО  ] "); c = Theme.Green; break;
                case "warn": tag = Loc.T("[ТРЕВОГА ] "); c = Theme.Amber; tc = Color.FromArgb(255, 205, 150); break;
                case "fail": tag = Loc.T("[ ЕРЕСЬ  ] "); c = Theme.Red; tc = Color.FromArgb(255, 170, 150); break;
                case "hop0": tag = Loc.T("[  УЗЕЛ  ] "); c = Theme.GreenDim; break;
                case "hop1": tag = Loc.T("[  УЗЕЛ  ] "); c = Theme.GreenDim; tc = Theme.Amber; break;
                case "hop2": tag = Loc.T("[  УЗЕЛ  ] "); c = Theme.GreenDim; tc = Theme.Red; break;
                default: tag = Loc.T("[ ДАННЫЕ ] "); c = Theme.GreenDim; tc = Theme.GreenMid; break;
            }
            AppendParts(new[] { tag, text }, new[] { c, tc }, false);
        }

        void Section(string title)
        {
            AppendParts(new[] { "" }, new[] { Theme.Text }, false);
            AppendParts(new[] { "++ " + title + " ++" }, new[] { Theme.Orange }, true);
        }

        // ================= РИТУАЛ =================
        void SetButtons(bool en)
        {
            foreach (var b in rb) b.Enabled = en;
            combo.Enabled = en;
        }

        void StartRitual(int mode)
        {
            if (running) return;
            var a = Store.ActiveSanctum;
            curSanctum = a != null ? a.Name : "";
            running = true; curMode = mode;
            SetButtons(false);
            FlushLogTyper();
            log.Clear(); report.Clear(); scope.Clear();
            scope.TrafficMode = false; scope.Mode = 1;
            t0 = DateTime.Now; tick = 0; litIdx = new Random().Next(Litany.Length);
            frame.RightText = Loc.T("РИТУАЛ: ") + Nums[mode] + " · " + RitualNames[mode]; frame.Invalidate();
            nav.Busy = true;
            RunningMessage();
            RefreshHome();

            AppendParts(new[] { Loc.T("++ РИТУАЛ ") + Nums[mode] + ": " + RitualNames[mode] + " ++" }, new[] { Theme.Red }, true);
            AppendParts(new[] { DateTime.Now.ToString("dd.MM.yyyy HH:mm:ss") + "  ·  " + Environment.MachineName +
                (a != null ? Loc.T("  ·  святилище: ") + a.Name + " (" + a.Addr + ")" : Loc.T("  ·  без святилища")) }, new[] { Theme.GreenDim }, false);

            var d = new Diag(a != null ? a.Addr : "", a != null ? a.Port : 22, Store.Pattern, Store.Isp, LogLine, Section);
            var th = new Thread(() =>
            {
                Verdict v;
                try { v = d.Run(mode); }
                catch (Exception ex)
                {
                    LogLine("fail", Loc.T("Сбой когитатора: ") + ex.Message);
                    v = new Verdict { Headline = Loc.T("СБОЙ КОГИТАТОРА"), Side = Loc.T("Во время ритуала произошла ошибка: ") + ex.Message, Color = Theme.Red };
                }
                var legs = d.Legs;
                if (d.DetectedIsp != null && d.DetectedIsp != Store.Isp) { Store.Isp = d.DetectedIsp; try { BeginInvoke(new Action(Store.SaveSettings)); } catch { } }
                try { BeginInvoke(new Action(() => { Finish(v); if (legs != null && legs.Count > 0) scope.SetPath(legs); })); } catch { }
            });
            th.IsBackground = true;
            th.Start();
        }

        void RunningMessage()
        {
            int sec = (int)(DateTime.Now - t0).TotalSeconds;
            var a = Store.ActiveSanctum;
            msg.Set(
                Loc.T("++ НАЧАЛО РИТУАЛА ++"), Theme.Orange,
                Loc.T("РИТУАЛ ") + Nums[curMode] + ": " + RitualNames[curMode], Theme.Green,
                curSanctum.Length > 0 ? Loc.T("СВЯТИЛИЩЕ: ") + curSanctum.ToUpperInvariant() : "", Theme.Green,
                Litany[litIdx] + "...", Theme.Green,
                Loc.T("НЕ ТРЕВОЖЬ КОГИТАТОР."), Theme.Orange,
                Loc.T("ПРОШЛО: ") + sec + Loc.T(" С"), Theme.GreenDim);   // секунды — последней строкой: обновляются, не трогая остальное
        }

        void Finish(Verdict v)
        {
            if (logTyper == null) { logTyper = new System.Windows.Forms.Timer { Interval = 22 }; logTyper.Tick += (s, e) => LogTyperTick(); }
            typeLog = true;
            Section(Loc.T("ПРИГОВОР"));
            AppendParts(new[] { ">>> " + v.Headline + " <<<" }, new[] { v.Color }, true);
            AppendParts(new[] { v.Side }, new[] { Theme.Text }, true);
            foreach (var t in v.Tips) AppendParts(new[] { "  + ", t }, new[] { Theme.Orange, Theme.Text }, false);
            int sec = (int)(DateTime.Now - t0).TotalSeconds;
            AppendParts(new[] { "" }, new[] { Theme.Text }, false);
            AppendParts(new[] { Loc.T("Ритуал завершён за ") + sec + Loc.T(" с. Хвала машинному духу.") }, new[] { Theme.GreenDim }, false);
            typeLog = false;

            var parts = new List<object>
            {
                Loc.T("++ ПРИГОВОР ВЫНЕСЕН ++"), Theme.Orange,
                Loc.T("ПО ВОЛЕ АДЕПТА СЕТИ. РИТУАЛ ") + Nums[curMode] + Loc.T(" ЗАВЕРШЁН ЗА ") + sec + Loc.T(" С."), Theme.Green,
                Loc.T("УГРОЗА: ") + v.Headline, v.Color,
                v.Side.ToUpperInvariant(), Theme.Green
            };
            for (int i = 0; i < v.Tips.Count && i < 2; i++) { parts.Add(v.Tips[i]); parts.Add(Theme.GreenMid); }
            msg.Set(parts.ToArray());

            char key = v.Color == Theme.Green ? 'g' : v.Color == Theme.Red ? 'r' : 'a';
            Store.AddChron(new ChronEntry
            {
                Id = t0.ToString("yyyyMMdd-HHmmss"), When = t0, Ritual = curMode, Sanctum = curSanctum,
                Headline = v.Headline, Side = v.Side, Key = key, Seconds = sec
            }, report.ToString());

            top.Status = key == 'g' ? Loc.T("СИСТЕМА :НОРМА") : key == 'r' ? Loc.T("СИСТЕМА :ЕРЕСЬ ОБНАРУЖЕНА") : Loc.T("СИСТЕМА :ТРЕВОГА");
            top.StatusColor = v.Color; top.Invalidate();
            running = false;
            nav.Busy = false; nav.Invalidate();
            SetButtons(true);
            RefreshHome();
            if (pages[3].Visible) RefreshChron();
            AutoDetectAsync(false);
        }

        // ================= СТРАЖ =================
        NotifyIcon tray;
        Icon iconOk, iconAlert;
        System.Windows.Forms.Timer guardTimer;
        bool guardBusy, guardDown, vpnSeen, lastVpnUp, reallyExit, trayHintShown;
        int guardChecks;
        DateTime downSince, lastCheck;
        string lastVia = "";
        ToolStripMenuItem miGuard, miHud;

        void InitGuard()
        {
            iconOk = Icon ?? SystemIcons.Application;
            try
            {
                using (var bmp = new Bitmap(32, 32, PixelFormat.Format32bppArgb))
                {
                    using (var g = Graphics.FromImage(bmp))
                    {
                        g.SmoothingMode = SmoothingMode.AntiAlias;
                        g.DrawIcon(new Icon(iconOk, 32, 32), new Rectangle(0, 0, 32, 32));
                        using (var b = new SolidBrush(Color.FromArgb(230, 255, 40, 30))) g.FillEllipse(b, 15, 15, 16, 16);
                        using (var pen = new Pen(Color.Black, 2f)) g.DrawEllipse(pen, 15, 15, 16, 16);
                        using (var pen = new Pen(Color.White, 2.4f)) { g.DrawLine(pen, 23, 18.5f, 23, 24.5f); g.DrawLine(pen, 23, 26.5f, 23, 28); }
                    }
                    iconAlert = Icon.FromHandle(bmp.GetHicon());
                }
            }
            catch { iconAlert = iconOk; }

            var menu = new ContextMenuStrip { Renderer = new ToolStripProfessionalRenderer(new CrtMenuColors()), ShowImageMargin = false, Font = Theme.Mono(9.5f, FontStyle.Bold) };
            var miOpen = new ToolStripMenuItem(Loc.T("ОТКРЫТЬ КОГИТАТОР")) { ForeColor = Theme.Green };
            miOpen.Click += (s, e) => RestoreFromTray();
            miGuard = new ToolStripMenuItem(Loc.T("СТРАЖ: ВКЛЮЧЁН")) { ForeColor = Theme.Orange };
            miGuard.Click += (s, e) => SetGuard(!Store.Guard);
            var miExit = new ToolStripMenuItem(Loc.T("ВЫХОД")) { ForeColor = Theme.GreenMid };
            miExit.Click += (s, e) => { reallyExit = true; Close(); };
            miHud = new ToolStripMenuItem(Loc.T("АУСПИК")) { ForeColor = Theme.GreenMid };
            miHud.Click += (s, e) => SetHud(!Store.Hud);
            menu.Items.Add(miOpen); menu.Items.Add(miGuard); menu.Items.Add(miHud); menu.Items.Add(new ToolStripSeparator()); menu.Items.Add(miExit);

            tray = new NotifyIcon { Icon = iconOk, Text = Loc.T("Когитатор Связи"), ContextMenuStrip = menu, Visible = false };
            tray.DoubleClick += (s, e) => RestoreFromTray();
            tray.BalloonTipClicked += (s, e) => RestoreFromTray();

            guardTimer = new System.Windows.Forms.Timer { Interval = 10000 };
            guardTimer.Tick += (s, e) => GuardTick();
            nav.GuardClicked += () => SetGuard(!Store.Guard);
            nav.LangClicked += SwitchLanguage;

            if (Store.Guard) SetGuard(true);
            else UpdateGuardUi();
        }

        void SwitchLanguage()
        {
            if (running)
            {
                MessageBox.Show(this, Loc.En ? "Wait for the ritual to finish, then switch the language." : "Дождись окончания ритуала, потом смени язык.", "Cogitator", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            Store.Lang = Loc.En ? "ru" : "en";
            Store.SaveSettings();
            // перезапуск: весь интерфейс собирается заново на новом языке
            string exe = Application.ExecutablePath;
            reallyExit = true;
            Program.ReleaseSingle();
            Close();
            try { Process.Start(exe); } catch { }
        }

        void SetGuard(bool on)
        {
            Store.Guard = on;
            Store.SaveSettings();
            if (on)
            {
                guardDown = false; vpnSeen = false; guardChecks = 0;
                tray.Visible = true;
                guardTimer.Start();
                GuardTick();
            }
            else
            {
                guardTimer.Stop();
                guardDown = false;
                if (!Store.Hud) tray.Icon = iconOk;
                tray.Visible = !Visible || Store.Hud;
            }
            UpdateGuardUi();
            RefreshHome();
        }

        void GuardTick()
        {
            if (!Store.Guard || guardBusy || running) return;
            guardBusy = true;
            string pattern = Store.Pattern;
            var th = new Thread(() =>
            {
                GuardResult r;
                try
                {
                    r = Guardian.Check(pattern);
                    if (!r.Ok) { Thread.Sleep(3000); r = Guardian.Check(pattern); }   // повтор: защита от ложной тревоги
                }
                catch { r = new GuardResult(); }
                try { BeginInvoke(new Action(() => GuardApply(r))); } catch { }
            });
            th.IsBackground = true;
            th.Start();
        }

        void Push(string title, string text, ToolTipIcon icon)
        {
            try { tray.Visible = true; tray.ShowBalloonTip(10000, title, text, icon); } catch { }
        }

        void GuardChron(string headline, string side, char key, int seconds, string[] lines)
        {
            var now = DateTime.Now;
            var sb = new StringBuilder();
            sb.AppendLine(Loc.T("++ СТРАЖ: ") + headline + " ++");
            sb.AppendLine(now.ToString("dd.MM.yyyy HH:mm:ss") + "  ·  " + Environment.MachineName);
            sb.AppendLine("");
            foreach (var l in lines) sb.AppendLine(l);
            sb.AppendLine("");
            sb.AppendLine(Loc.T("++ ПРИГОВОР ++"));
            sb.AppendLine(">>> " + headline + " <<<");
            sb.AppendLine(side);
            var a = Store.ActiveSanctum;
            string id = now.ToString("yyyyMMdd-HHmmss");
            if (Store.Chronicle.Any(x => x.Id == id)) id = now.AddSeconds(1).ToString("yyyyMMdd-HHmmss");
            Store.AddChron(new ChronEntry { Id = id, When = now, Ritual = 9, Sanctum = a != null ? a.Name : "", Headline = headline, Side = side, Key = key, Seconds = seconds }, sb.ToString());
            if (pages[3].Visible) RefreshChron();
        }

        void GuardApply(GuardResult r)
        {
            guardBusy = false;
            if (!Store.Guard) return;
            guardChecks++;
            lastCheck = DateTime.Now;
            if (r.Ok) lastVia = r.Via + " · " + r.Ms + Loc.T(" мс");
            NoteReading(r.Ok ? Loc.T("СТРАЖ · ") + r.Ms + Loc.T(" МС") + (r.VpnUp ? " · " + Loc.T("ТУННЕЛЬ") : " · " + Loc.T("НАПРЯМУЮ")) : Loc.T("СТРАЖ · СВЯЗИ НЕТ"), r.Ok ? (r.VpnUp ? Theme.Green : Theme.Amber) : Theme.Red);

            if (vpnSeen && lastVpnUp && !r.VpnUp)
            {
                Push(Loc.T("VPN ОТКЛЮЧЁН"), Loc.T("Адаптер туннеля пропал: VPN выключен вручную или упал клиент Amnezia.") + (r.Ok ? Loc.T(" Интернет идёт напрямую, без VPN.") : ""), ToolTipIcon.Warning);
                GuardChron(Loc.T("VPN ОТКЛЮЧЁН"), Loc.T("Адаптер туннеля пропал") + (r.Ok ? Loc.T(", интернет идёт напрямую") : ""), 'a', 0,
                    new[] { Loc.T("[ТРЕВОГА ] Адаптер VPN больше не активен."), r.Ok ? Loc.T("[ ДАННЫЕ ] Связь есть: ") + r.Via : Loc.T("[ ЕРЕСЬ  ] Связи нет.") });
            }
            lastVpnUp = r.VpnUp; vpnSeen = true;

            if (!r.Ok && !guardDown)
            {
                guardDown = true;
                downSince = DateTime.Now;
                string head = r.VpnUp ? Loc.T("ТУННЕЛЬ ПАЛ") : Loc.T("СВЯЗЬ ПРОПАЛА");
                string text = r.VpnUp ? Loc.T("VPN включён, но пакеты не возвращаются. Нажми, чтобы открыть когитатор и запустить ритуал II.")
                                      : Loc.T("Интернет пропал. Нажми, чтобы открыть когитатор и запустить ритуал I.");
                Push(head, text, ToolTipIcon.Error);
                if (!Store.Hud) tray.Icon = iconAlert;
                GuardChron(head, r.VpnUp ? Loc.T("VPN включён, но ни один пакет не вернулся (две проверки подряд)") : Loc.T("Ни ping, ни HTTPS не проходят (две проверки подряд)"), 'r', 0,
                    new[] { Loc.T("[ ЕРЕСЬ  ] Ping 1.1.1.1 / 8.8.8.8 / 77.88.8.8 — нет ответа."), Loc.T("[ ЕРЕСЬ  ] HTTPS generate_204 — не открывается."),
                            Loc.T("[ ДАННЫЕ ] VPN: ") + (r.VpnUp ? Loc.T("включён (") + r.VpnName + ")" : Loc.T("выключен")) });
                if (!running && !Visible) { }
            }
            else if (r.Ok && guardDown)
            {
                guardDown = false;
                var dur = DateTime.Now - downSince;
                Push(Loc.T("СВЯЗЬ ВОССТАНОВЛЕНА"), Loc.T("Простой: ") + Guardian.Fmt(dur) + Loc.T(". Машинный дух снова слышит сеть."), ToolTipIcon.Info);
                if (!Store.Hud) tray.Icon = iconOk;
                GuardChron(Loc.T("СВЯЗЬ ВОССТАНОВЛЕНА · ПРОСТОЙ ") + Guardian.Fmt(dur).ToUpperInvariant(), Loc.T("Связь вернулась после простоя ") + Guardian.Fmt(dur), 'g', (int)dur.TotalSeconds,
                    new[] { Loc.T("[ ДАННЫЕ ] Пропала: ") + downSince.ToString("HH:mm:ss") + Loc.T(", вернулась: ") + DateTime.Now.ToString("HH:mm:ss"),
                            Loc.T("[ ЧИСТО  ] Проверка: ") + r.Via + " · " + r.Ms + Loc.T(" мс") });
            }
            UpdateGuardUi();
            if (!running)
            {
                if (guardDown) { top.Status = Loc.T("СИСТЕМА :СВЯЗИ НЕТ"); top.StatusColor = Theme.Red; }
                else if (top.Status == Loc.T("СИСТЕМА :СВЯЗИ НЕТ")) { top.Status = Loc.T("СИСТЕМА :ГОТОВ"); top.StatusColor = Theme.Green; }
                top.Invalidate();
            }
            if (currentPage == 0) RefreshHome();
        }

        void UpdateGuardUi()
        {
            nav.GuardOn = Store.Guard;
            nav.GuardDown = guardDown;
            string state;
            if (!Store.Guard) state = Loc.T("СТРАЖ: ВЫКЛЮЧЕН");
            else if (guardDown) state = Loc.T("СТРАЖ: СВЯЗИ НЕТ · ") + Guardian.Fmt(DateTime.Now - downSince).ToUpperInvariant();
            else if (guardChecks == 0) state = Loc.T("СТРАЖ: ЗАСТУПАЕТ...");
            else state = Loc.T("СТРАЖ: СВЯЗЬ ЕСТЬ · ") + guardChecks + Loc.T(" ПРОВ.");
            nav.GuardText = state;
            nav.Invalidate();
            if (miGuard != null) miGuard.Text = Store.Guard ? Loc.T("СТРАЖ: ВКЛЮЧЁН (ВЫКЛЮЧИТЬ)") : Loc.T("СТРАЖ: ВЫКЛЮЧЕН (ВКЛЮЧИТЬ)");
            if (tray != null && !Store.Hud)
            {
                string t = !Store.Guard ? Loc.T("Когитатор · страж выключен") : guardDown ? Loc.T("Когитатор · СВЯЗИ НЕТ") : Loc.T("Когитатор · связь есть (") + lastVia + ")";
                tray.Text = t.Length > 63 ? t.Substring(0, 63) : t;
            }
        }

        void RestoreFromTray()
        {
            Show();
            if (WindowState == FormWindowState.Minimized) WindowState = FormWindowState.Normal;
            Activate();
            if (guardDown && currentPage != 2) ShowPage(2);
            if (!Store.Guard && !Store.Hud) tray.Visible = false;
        }

        // ================= ТРАФИК ДЛЯ ОСЦИЛЛОГРАФА =================
        bool trafBusy;
        string trafId; long trafRx = -1, trafTx = -1; DateTime trafT;
        int vpnZeroStreak;

        void SampleTraffic()
        {
            if (trafBusy) return;
            trafBusy = true;
            string pattern = Store.Pattern;
            ThreadPool.QueueUserWorkItem(_ =>
            {
                double dn = -1, upb = -1; string src = "—";
                try
                {
                    var all = NetworkInterface.GetAllNetworkInterfaces();
                    NetworkInterface vpn = Tun.Find(pattern), phys = null; int best = int.MinValue;
                    foreach (var n in all)
                    {
                        if (n.OperationalStatus != OperationalStatus.Up || n.NetworkInterfaceType == NetworkInterfaceType.Loopback) continue;
                        if ((vpn != null && n.Id == vpn.Id) || Tun.Looks(n, pattern)) continue;
                        if (n.NetworkInterfaceType == NetworkInterfaceType.Tunnel) continue;
                        bool gw = false;
                        try { gw = n.GetIPProperties().GatewayAddresses.Any(a => a.Address.AddressFamily == AddressFamily.InterNetwork && !a.Address.Equals(IPAddress.Any)); } catch { }
                        if (!gw) continue;
                        int score = (n.NetworkInterfaceType == NetworkInterfaceType.Ethernet || n.NetworkInterfaceType == NetworkInterfaceType.Wireless80211) ? 40 : 0;
                        if (Regex.IsMatch(n.Name + " " + n.Description, "Hyper-V|vEthernet|VirtualBox|VMware|Virtual|Docker|WSL", RegexOptions.IgnoreCase)) score -= 80;
                        if (score > best) { best = score; phys = n; }
                    }
                    // туннель — если он есть и его счётчики живые; иначе сетевая карта
                    NetworkInterface srcNi = vpn != null && vpnZeroStreak < 4 ? vpn : phys;
                    if (srcNi != null)
                    {
                        src = (srcNi == vpn ? Loc.T("ТУННЕЛЬ · ") : "") + srcNi.Name.ToUpperInvariant();
                        var st = srcNi.GetIPStatistics();
                        long rx = st.BytesReceived, tx = st.BytesSent;
                        var now = DateTime.Now;
                        if (srcNi.Id == trafId && trafRx >= 0)
                        {
                            double secs = Math.Max(0.05, (now - trafT).TotalSeconds);
                            long drx = rx - trafRx, dtx = tx - trafTx;
                            if (drx >= 0 && dtx >= 0) { dn = drx * 8 / secs; upb = dtx * 8 / secs; }
                            if (srcNi == vpn) vpnZeroStreak = (rx == 0 && tx == 0) ? vpnZeroStreak + 1 : 0;
                        }
                        trafId = srcNi.Id; trafRx = rx; trafTx = tx; trafT = now;
                        src = (srcNi == vpn ? Loc.T("ТУННЕЛЬ · ") : "") + srcNi.Name.ToUpperInvariant();
                    }
                }
                catch { }
                try
                {
                    BeginInvoke(new Action(() =>
                    {
                        trafBusy = false;
                        if (dn >= 0) scope.AddTraffic(dn, upb, src);
                        else scope.Source = src;
                    }));
                }
                catch { trafBusy = false; }
            });
        }

        // ================= АУСПИК =================
        [DllImport("user32.dll")] static extern bool RegisterHotKey(IntPtr h, int id, uint mods, uint vk);
        [DllImport("user32.dll")] static extern bool UnregisterHotKey(IntPtr h, int id);
        [DllImport("user32.dll")] static extern bool DestroyIcon(IntPtr h);
        const int HotkeyId = 0xC061;
        AuspexForm hud;
        Thread hudThread;
        volatile bool hudRun;
        IntPtr trayIconHandle = IntPtr.Zero;
        string lastIconKey;

        void InitHud()
        {
            try { RegisterHotKey(Handle, HotkeyId, 0x1 | 0x2 | 0x4000, (uint)Keys.A); } catch { }   // Ctrl+Alt+A, без автоповтора
            home.HudSwitch.On = Store.Hud;
            home.HudSwitch.Click += (s, e) => SetHud(!Store.Hud);
            if (Store.Hud) SetHud(true);
            UpdateHudUi();
        }

        void SetHud(bool on)
        {
            Store.Hud = on;
            Store.SaveSettings();
            if (on)
            {
                if (hud == null)
                {
                    hud = new AuspexForm();
                    hud.OpenRequested += RestoreFromTray;
                    hud.HideRequested += () => SetHud(false);
                    hud.Moved += () => { Store.HudX = hud.Left; Store.HudY = hud.Top; Store.SaveSettings(); };
                }
                var wa = Screen.PrimaryScreen.WorkingArea;
                var pos = new Point(Store.HudX, Store.HudY);
                bool onScreen = Screen.AllScreens.Any(sc => sc.WorkingArea.Contains(new Rectangle(pos, new Size(40, 40))));
                hud.Location = onScreen ? pos : new Point(wa.Right - hud.Width - 16, wa.Top + 16);
                hud.Show();
                tray.Visible = true;
                if (!hudRun)
                {
                    hudRun = true;
                    hudThread = new Thread(HudLoop) { IsBackground = true };
                    hudThread.Start();
                }
                RestartGateWatch();
            }
            else
            {
                hudRun = false;
                gateWatchGen++;
                if (hud != null) hud.Hide();
                lastIconKey = null;
                tray.Icon = guardDown ? iconAlert : iconOk;
                if (trayIconHandle != IntPtr.Zero) { try { DestroyIcon(trayIconHandle); } catch { } trayIconHandle = IntPtr.Zero; }
                tray.Visible = Store.Guard || !Visible;
                UpdateGuardUi();
            }
            UpdateHudUi();
        }

        void UpdateHudUi()
        {
            home.HudSwitch.On = Store.Hud; home.HudSwitch.Invalidate();
            if (miHud != null) miHud.Text = Store.Hud ? Loc.T("АУСПИК: ВКЛЮЧЁН (СКРЫТЬ)") : Loc.T("АУСПИК: ВЫКЛЮЧЕН (ПОКАЗАТЬ)");
        }

        // раз в секунду — один пинг по текущему пути (через туннель, если он включён)
        void HudLoop()
        {
            var d = new AuspexData();
            var times = new List<double>();
            int tickN = 0;
            using (var p = new Ping())
            {
                while (hudRun)
                {
                    var sw = Stopwatch.StartNew();
                    double v = -1;
                    try { var r = p.Send("1.1.1.1", 1000); if (r.Status == IPStatus.Success) v = r.RoundtripTime; } catch { }
                    if (tickN++ % 5 == 0)
                    {
                        try
                        {
                            string pat = Store.Pattern;
                            d.Vpn = Tun.Find(pat) != null;
                            d.Proxy = !d.Vpn && Tun.SystemProxy() != null;
                        }
                        catch { }
                    }
                    lock (d.Hist) { d.Hist.Add(v); if (d.Hist.Count > 60) d.Hist.RemoveAt(0); }
                    AuspexLog.Add(v, d.Vpn ? 1 : d.Proxy ? 2 : 0);
                    d.Last = v;
                    d.MissStreak = v < 0 ? d.MissStreak + 1 : 0;
                    List<double> last; lock (d.Hist) last = d.Hist.Skip(Math.Max(0, d.Hist.Count - 30)).ToList();
                    d.Loss = Math.Round(100.0 * last.Count(x => x < 0) / last.Count, 1);
                    var ok = last.Where(x => x >= 0).ToList();
                    double j = 0; for (int i = 1; i < ok.Count; i++) j += Math.Abs(ok[i] - ok[i - 1]);
                    d.Jitter = ok.Count > 1 ? j / (ok.Count - 1) : 0;
                    try { BeginInvoke(new Action(() => HudApply(d))); } catch { }
                    int rest = 1000 - (int)sw.ElapsedMilliseconds;
                    if (rest > 0) Thread.Sleep(rest);
                }
            }
            AuspexLog.Flush();
        }

        void HudApply(AuspexData d)
        {
            if (!Store.Hud || hud == null) return;
            hud.Data = d;
            if (d.Last >= 0 || d.MissStreak >= 3) NoteReading(Loc.T("АУСПИК · ") + (d.MissStreak >= 3 ? Loc.T("НЕТ СВЯЗИ") : Math.Round(d.Last) + Loc.T(" МС") + (d.Loss > 0 ? " · " + d.Loss.ToString("0.#", CultureInfo.InvariantCulture) + "%" : "")), d.State);
            hud.Invalidate();
            // живой пинг в трее
            string txt = d.MissStreak >= 3 || d.Last < 0 ? "×" : Math.Min(999, Math.Round(d.Last)).ToString();
            Color c = d.State;
            string key = txt + c.ToArgb();
            if (key != lastIconKey)
            {
                lastIconKey = key;
                try
                {
                    int sz = Math.Max(16, SystemInformation.SmallIconSize.Width);
                    using (var bmp = new Bitmap(sz, sz, PixelFormat.Format32bppArgb))
                    {
                        using (var g = Graphics.FromImage(bmp))
                        {
                            g.Clear(Color.FromArgb(255, 4, 9, 5));
                            using (var pen = new Pen(c, Math.Max(1, sz / 16))) g.DrawRectangle(pen, 0, 0, sz - 1, sz - 1);
                            g.TextRenderingHint = TextRenderingHint.SingleBitPerPixelGridFit;
                            float fs = sz * (txt.Length >= 3 ? 0.36f : txt.Length == 2 ? 0.56f : 0.7f);
                            using (var f = new Font("Consolas", fs, txt.Length >= 3 ? FontStyle.Regular : FontStyle.Bold, GraphicsUnit.Pixel))
                            using (var b = new SolidBrush(c))
                            using (var sfm = new StringFormat(StringFormatFlags.NoWrap | StringFormatFlags.NoClip) { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                                g.DrawString(txt, f, b, new RectangleF(-sz * 0.3f, 0, sz * 1.6f, sz), sfm);
                        }
                        var h = bmp.GetHicon();
                        tray.Icon = Icon.FromHandle(h);
                        if (trayIconHandle != IntPtr.Zero) { try { DestroyIcon(trayIconHandle); } catch { } }
                        trayIconHandle = h;
                    }
                }
                catch { }
            }
            string tt = d.MissStreak >= 3 ? Loc.T("Ауспик: СВЯЗИ НЕТ") : Loc.T("Ауспик: ") + (d.Last < 0 ? Loc.T("нет ответа") : Math.Round(d.Last) + Loc.T(" мс")) + Loc.T(" · потери ") + Math.Round(d.Loss, 1) + "% · " + (d.Vpn ? Loc.T("туннель") : Loc.T("напрямую"));
            tray.Text = tt.Length > 63 ? tt.Substring(0, 63) : tt;
        }

        GlitchOverlay glitch; System.Windows.Forms.Timer glitchTimer; DateTime nextGlitch; readonly Random glitchRnd = new Random();

        void MaybeGlitch()
        {
            if (!Store.Glitch || glitch == null || glitch.Visible || DateTime.Now < nextGlitch) return;
            nextGlitch = DateTime.Now.AddSeconds(10 + glitchRnd.Next(20));
            // только когда окно на виду и ничего не происходит: не во время перехода, перетаскивания и нажатой мыши
            if (moving || transTarget >= 0 || Form.ActiveForm != this || MouseButtons != MouseButtons.None || WindowState == FormWindowState.Minimized) return;
            try
            {
                var shot = new Bitmap(ClientSize.Width, ClientSize.Height);
                using (var g = Graphics.FromImage(shot)) g.CopyFromScreen(PointToScreen(Point.Empty), Point.Empty, ClientSize);
                if (glitch.Shot != null) glitch.Shot.Dispose();
                glitch.Shot = shot;
                glitch.Bounds = ClientRectangle;
                glitch.Frame = 0; glitch.Roll();
                glitch.Visible = true; glitch.BringToFront(); glitch.Update();
                glitchTimer.Interval = 40 + glitchRnd.Next(40);
                glitchTimer.Start();
            }
            catch { }
        }

        ScanBeam beam; System.Windows.Forms.Timer beamTimer; Stopwatch beamClock; DateTime nextBeam;
        const int BeamDur = 1500;
        string lastReading; Color lastReadingCol = Theme.Green; DateTime lastReadingAt = DateTime.MinValue;

        // показание для луча: последнее, что знает когитатор о связи
        void NoteReading(string tag, Color c) { lastReading = tag; lastReadingCol = c; lastReadingAt = DateTime.Now; }

        void MaybeBeam(bool fresh)
        {
            if (!Store.Scan || beam == null || beam.Visible || (glitch != null && glitch.Visible)) return;
            if (!fresh && DateTime.Now < nextBeam) return;
            nextBeam = DateTime.Now.AddSeconds(14 + glitchRnd.Next(8));
            if (moving || transTarget >= 0 || Form.ActiveForm != this || MouseButtons != MouseButtons.None || WindowState == FormWindowState.Minimized) return;
            try
            {
                var shot = new Bitmap(ClientSize.Width, ClientSize.Height);
                using (var g = Graphics.FromImage(shot)) g.CopyFromScreen(PointToScreen(Point.Empty), Point.Empty, ClientSize);
                if (beam.Shot != null) beam.Shot.Dispose();
                beam.Shot = shot;
                bool recent = (DateTime.Now - lastReadingAt).TotalSeconds < 30;
                beam.Col = recent ? lastReadingCol : Theme.Green;
                beam.Reading = recent ? lastReading : null;
                beam.Cy = -ScanBeam.H;
                beam.SetBounds(0, -ScanBeam.H, ClientSize.Width, ScanBeam.H);
                beam.Visible = true; beam.BringToFront();
                beamClock = Stopwatch.StartNew();
                beamTimer.Start();
            }
            catch { }
        }

        void BeamStep()
        {
            float t = beamClock.ElapsedMilliseconds / (float)BeamDur;
            if (t >= 1 || moving || WindowState == FormWindowState.Minimized)
            {
                beamTimer.Stop(); beam.Visible = false;
                if (beam.Shot != null) { beam.Shot.Dispose(); beam.Shot = null; }
                return;
            }
            float e = t < 0.5f ? 2 * t * t : 1 - (float)Math.Pow(-2 * t + 2, 2) / 2;   // плавно в начале и в конце
            float cy = -ScanBeam.H + (ClientSize.Height + ScanBeam.H * 2) * e;
            beam.Cy = cy;
            beam.Top = (int)(cy - ScanBeam.H / 2f);
            beam.Invalidate();
        }

        void GlitchStep()
        {
            glitch.Frame++;
            if (glitch.Frame >= 2 + glitchRnd.Next(2))
            {
                glitchTimer.Stop(); glitch.Visible = false;
                if (glitch.Shot != null) { glitch.Shot.Dispose(); glitch.Shot = null; }
                return;
            }
            glitch.Roll(); glitch.Invalidate();
            glitchTimer.Interval = 30 + glitchRnd.Next(50);
        }

        bool moving;
        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x312 && (int)m.WParam == HotkeyId) SetHud(!Store.Hud);   // Ctrl+Alt+A
            if (m.Msg == 0x231) moving = true;          // WM_ENTERSIZEMOVE — окно тащат
            else if (m.Msg == 0x232) moving = false;    // WM_EXITSIZEMOVE
            base.WndProc(ref m);
        }

        void AnimTick()
        {
            tick++;
            if (moving || WindowState == FormWindowState.Minimized || !Visible) return;   // не греть процессор впустую
            if (guardDown) { nav.Blink++; if (nav.Blink % 4 == 0) { UpdateGuardUi(); } }
            int s = DateTime.Now.Second;
            if (pages[0].Visible && transTarget < 0) home.Tick();
            if (tick % 20 == 0) MaybeGlitch();
            if (pages[2].Visible && tick % 6 == 0) SampleTraffic();
            if (!pages[2].Visible) SonarProbe.Want = false;
            if (pages[2].Visible)
            {
                scope.Phase += 0.09f;
                scope.Invalidate();
                SonarProbe.Want = true;
                emblem.Angle += 0.045f; emblem.Invalidate();
            }
            if (running)
            {
                if (tick % 30 == 0) litIdx = (litIdx + 1) % Litany.Length;
                if (tick % 6 == 0) RunningMessage();
                int sec = (int)(DateTime.Now - t0).TotalSeconds;
                string st = Loc.T("СИСТЕМА :РИТУАЛ :") + sec + Loc.T("С");
                if (st != top.Status) { top.Status = st; top.StatusColor = Theme.Orange; top.Invalidate(); }
                nav.Blink++;
                if (nav.Blink % 5 == 0) nav.Invalidate();
            }
            lastSec = s;
        }

        void SaveText(string text, string name)
        {
            if (string.IsNullOrEmpty(text)) { MessageBox.Show(this, Loc.T("Отчёт пуст — сначала соверши ритуал."), Loc.T("Когитатор"), MessageBoxButtons.OK, MessageBoxIcon.Information); return; }
            using (var dlg = new SaveFileDialog
            {
                Filter = Loc.T("Текстовый отчёт (*.txt)|*.txt"),
                FileName = name,
                InitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.Desktop)
            })
            {
                if (dlg.ShowDialog(this) == DialogResult.OK)
                {
                    try { File.WriteAllText(dlg.FileName, text, new UTF8Encoding(true)); }
                    catch (Exception ex) { MessageBox.Show(this, ex.Message, Loc.T("Не удалось сохранить"), MessageBoxButtons.OK, MessageBoxIcon.Error); }
                }
            }
        }

        protected override void OnDeactivate(EventArgs e) { if (combo != null) combo.ClosePopup(); base.OnDeactivate(e); }
        protected override void OnResize(EventArgs e)
        {
            if (combo != null) combo.ClosePopup();
            base.OnResize(e);
            if (WindowState == FormWindowState.Minimized && Store.Guard && tray != null)
            {
                Hide();
                tray.Visible = true;
                if (!trayHintShown) { trayHintShown = true; Push(Loc.T("СТРАЖ НЕСЁТ СЛУЖБУ"), Loc.T("Когитатор свернулся в трей и проверяет связь каждые 10 секунд."), ToolTipIcon.Info); }
            }
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (Store.Guard && !reallyExit && e.CloseReason == CloseReason.UserClosing && tray != null)
            {
                e.Cancel = true;
                Hide();
                tray.Visible = true;
                if (!trayHintShown) { trayHintShown = true; Push(Loc.T("СТРАЖ ПРОДОЛЖАЕТ СЛУЖБУ"), Loc.T("Когитатор ушёл в трей. Полный выход — через меню значка: «Выход»."), ToolTipIcon.Info); }
                return;
            }
            Store.SaveSettings();
            hudRun = false;
            try { UnregisterHotKey(Handle, HotkeyId); } catch { }
            if (hud != null) { hud.Close(); }
            if (tray != null) { tray.Visible = false; tray.Dispose(); }
            base.OnFormClosing(e);
        }
    }
}
